# ── Live account reconnect ──────────────────────────────────────────────────

@app.post("/reconnect")
async def reconnect_endpoint(req: ReconnectRequest):
    """
    Switch TWS port. 7497 = paper, 7496 = live.
    Disconnects the current session; streaming loop auto-reconnects.
    """
    if req.port not in (7496, 7497, 4001, 4002):
        raise HTTPException(400, "Port must be 7496 (live), 7497 (paper), 4001 or 4002 (gateway)")
    state["reconnect_port"] = req.port
    if state.get("ib") and state["ib"].isConnected():
        state["ib"].disconnect()
    mode = "LIVE" if req.port == 7496 else ("paper" if req.port == 7497 else "gateway")
    _at_log("SYSTEM", f"Reconnecting to port {req.port} ({mode})")
    return {"ok": True, "port": req.port, "mode": mode,
            "message": f"Reconnecting to {mode} account on port {req.port}…"}


@app.post("/ibkr/reconcile")
async def manual_reconcile():
    """Trigger an immediate IBKR position reconciliation."""
    ib = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IB not connected")
    loop = state.get("streaming_loop")
    if loop:
        loop.run_in_executor(
            None,
            lambda: _run_in_streaming_loop(_ibkr_reconcile(ib, on_startup=False), timeout=30))
    return {"ok": True, "message": "Reconciliation triggered — check Telegram for results"}


@app.get("/reconcile/status")
def reconcile_status():
    """Last auto-correct reconciliation cycle: corrections made, open
    divergences (untracked / partial-leg), skips, and the kill-switch state."""
    cfg = _reconcile_cfg()
    out = dict(_reconcile_last_summary)
    out["autocorrect_enabled"] = cfg["autocorrect_enabled"]
    out["cycle_seconds"] = cfg["cycle_seconds"]
    return out


@app.post("/reconcile/run")
async def reconcile_run():
    """Run one auto-correcting reconciliation cycle right now."""
    ib = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IB not connected")
    with _reconcile_lock:
        summ = await asyncio.get_event_loop().run_in_executor(None, _reconcile_all, ib)
        _reconcile_last_summary.update(summ)
    return summ


# ── Trade Journal endpoints ────────────────────────────────────────────────

@app.get("/journal")
def get_journal(limit: int = Query(100, description="Most recent N trades")):
    """Return completed and open trade journal entries."""
    con = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
    total = con.execute("SELECT COUNT(*) FROM trade_journal").fetchone()[0]
    rows  = con.execute(
        "SELECT * FROM trade_journal ORDER BY id DESC LIMIT ?", (limit,)
    ).fetchall()
    cols = [d[0] for d in con.execute("SELECT * FROM trade_journal LIMIT 0").description or []]
    con.close()
    trades = [dict(zip(cols, r)) for r in rows]
    return {"trades": trades, "count": len(trades), "total": total}


@app.get("/journal/stats")
def get_journal_stats():
    """Win rate, avg P&L, feature importances from completed trades."""
    con = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
    rows = con.execute(
        "SELECT win, pnl, pnl_pct, exit_reason, strategy_type, iv_rank, score "
        "FROM trade_journal "
        "WHERE closed_at IS NOT NULL AND win IS NOT NULL "
        f"AND exit_reason IN ({_REAL_EXIT_REASONS})"
    ).fetchall()
    model_rows = con.execute(
        "SELECT * FROM model_log ORDER BY id DESC LIMIT 10"
    ).fetchall()
    model_cols = [d[0] for d in (con.execute("SELECT * FROM model_log LIMIT 0").description or [])]
    con.close()

    if not rows:
        return {"total_trades": 0, "win_rate": None, "avg_pnl": None, "model_log": []}

    wins     = [r for r in rows if r[0] == 1]
    losses   = [r for r in rows if r[0] == 0]
    pnls     = [r[1] for r in rows if r[1] is not None]
    by_reason = {}
    for r in rows:
        rr = r[3] or "unknown"
        by_reason.setdefault(rr, {"total": 0, "wins": 0})
        by_reason[rr]["total"] += 1
        if r[0] == 1:
            by_reason[rr]["wins"] += 1

    by_strategy: dict = {}
    for r in rows:
        st = (r[4] or "csp").lower()
        by_strategy.setdefault(st, {"total": 0, "wins": 0, "pnl": 0.0})
        by_strategy[st]["total"] += 1
        if r[0] == 1:
            by_strategy[st]["wins"] += 1
        if r[1] is not None:
            by_strategy[st]["pnl"] = round(by_strategy[st]["pnl"] + r[1], 2)

    model_log = [dict(zip(model_cols, r)) for r in model_rows]

    win_pnls  = [r[1] for r in wins   if r[1] is not None]
    loss_pnls = [r[1] for r in losses if r[1] is not None]
    return {
        "total_trades":    len(rows),
        "win_rate":        round(len(wins) / len(rows) * 100, 1),
        "avg_pnl":         round(sum(pnls) / len(pnls), 2) if pnls else 0,
        "total_pnl":       round(sum(pnls), 2) if pnls else 0,
        "avg_win_pnl":     round(sum(win_pnls) / len(win_pnls), 2) if win_pnls else 0,
        "avg_loss_pnl":    round(sum(loss_pnls) / len(loss_pnls), 2) if loss_pnls else 0,
        "exit_breakdown":  by_reason,
        "by_strategy":     by_strategy,
        "model_version":   state.get("model_version", 0),
        "model_log":       model_log,
        "assumed_win_rate":state["autotrader"]["config"].get("assumed_win_rate"),
    }


# ── IBKR Flex Query helpers ────────────────────────────────────────────────────

FLEX_SEND    = "https://www.interactivebrokers.com/Universal/servlet/FlexStatementService.SendRequest"
FLEX_GET     = "https://www.interactivebrokers.com/Universal/servlet/FlexStatementService.GetStatement"


def _flex_load_token() -> str:
    cfg = json.load(open(os.path.join(os.path.dirname(__file__), "scanner_config.json")))
    tok = cfg.get("flex_token", "")
    if not tok:
        raise ValueError("flex_token not set in scanner_config.json")
    return tok


def _flex_load_query_id() -> str:
    cfg = json.load(open(os.path.join(os.path.dirname(__file__), "scanner_config.json")))
    qid = cfg.get("flex_query_id", "")
    if not qid:
        raise ValueError("flex_query_id not set in scanner_config.json")
    return str(qid)


FLEX_CACHE_PATH = os.path.join(os.path.dirname(__file__), "flex_cache.xml")
FLEX_CACHE_TTL_S = 15 * 60   # reuse a fetched statement for 15 minutes


def _flex_fetch_xml(query_id: str, token: str | None = None, max_send_attempts: int = 5,
                    use_cache: bool = True) -> str:
    """Send a Flex Query request and poll until the XML statement is ready.
    Retries on IBKR error 1001 (rate limit / temporary unavailability).

    Caches the raw XML to FLEX_CACHE_PATH; concurrent/back-to-back consumers
    (MT backfills, reports) reuse it for FLEX_CACHE_TTL_S instead of hitting
    the API again — IBKR rate-limits aggressively (error 1001).
    """
    import xml.etree.ElementTree as ET
    import time as _time

    if use_cache:
        try:
            age = _time.time() - os.path.getmtime(FLEX_CACHE_PATH)
            if age < FLEX_CACHE_TTL_S:
                with open(FLEX_CACHE_PATH, encoding="utf-8") as fh:
                    cached = fh.read()
                if "<FlexQueryResponse" in cached or "<FlexStatements" in cached:
                    log.info("Flex: using cached statement (%.0fs old)", age)
                    return cached
        except OSError:
            pass

    tok = token or _flex_load_token()

    # Step 1 — request statement, retry on 1001
    ref = None
    for send_try in range(max_send_attempts):
        if send_try:
            _time.sleep(30)   # wait 30s between send retries
        r1 = requests.get(FLEX_SEND, params={"t": tok, "q": query_id, "v": "3"}, timeout=20)
        r1.raise_for_status()
        root1 = ET.fromstring(r1.text)
        status1 = root1.findtext("Status")
        if status1 == "Success":
            ref = root1.findtext("ReferenceCode")
            break
        ec = root1.findtext("ErrorCode")
        if ec == "1001":
            log.debug("Flex 1001 (rate limit), retry %d/%d", send_try + 1, max_send_attempts)
            continue
        raise ValueError(f"Flex SendRequest error: {root1.findtext('ErrorMessage') or r1.text}")
    if not ref:
        raise ValueError("Flex SendRequest failed after retries (1001 rate limit)")

    # Step 2 — poll until ready (up to 90s)
    get_url = root1.findtext("Url") or FLEX_GET
    for attempt in range(30):
        _time.sleep(3)
        r2 = requests.get(get_url, params={"t": tok, "q": ref, "v": "3"}, timeout=30)
        r2.raise_for_status()
        if "<FlexQueryResponse" in r2.text or "<FlexStatements" in r2.text:
            try:
                with open(FLEX_CACHE_PATH, "w", encoding="utf-8") as fh:
                    fh.write(r2.text)
            except OSError as _ce:
                log.warning("Flex: could not write cache: %s", _ce)
            return r2.text
        try:
            root2 = ET.fromstring(r2.text)
            if root2.findtext("ErrorCode") == "1019":
                continue   # still generating
            raise ValueError(f"Flex GetStatement error: {root2.findtext('ErrorMessage') or r2.text}")
        except ET.ParseError:
            pass
    raise TimeoutError("Flex statement not ready after 90s")


def _flex_parse_trades(xml_str: str) -> list[dict]:
    """Parse Flex Query XML into list of execution dicts."""
    import xml.etree.ElementTree as ET
    root = ET.fromstring(xml_str)
    trades = []
    for trade in root.iter("Trade"):
        def _f(key, default=None):
            v = trade.get(key)
            if v in (None, "", "N/A"):
                return default
            return v

        def _ff(key, default=0.0):
            v = _f(key)
            try:
                return float(v) if v is not None else default
            except (ValueError, TypeError):
                return default

        fifo = _ff("fifoPnlRealized", None)
        trades.append({
            "account":       _f("accountId", ""),
            "symbol":        _f("symbol", ""),
            "description":   _f("description", ""),
            "asset_cat":     _f("assetCategory", ""),
            "expiry":        _f("expiry", ""),
            "strike":        _ff("strike"),
            "put_call":      _f("putCall", ""),
            "multiplier":    _ff("multiplier", 100),
            "trade_date":    _f("tradeDate", ""),
            "trade_time":    _f("tradeTime", ""),
            "quantity":      _ff("quantity"),
            "trade_price":   _ff("tradePrice"),
            "proceeds":      _ff("proceeds"),
            "commission":    _ff("ibCommission"),
            "net_cash":      _ff("netCash"),
            "fifo_pnl":      fifo,
            "open_close":    _f("openCloseIndicator", ""),
            "order_type":    _f("orderType", ""),
            "ib_order_id":   _f("ibOrderID", ""),
        })
    return trades


@app.get("/flex-query/executions")
def flex_executions(query_id: str, ticker: str = None):
    """Fetch executions from IBKR Flex Query. query_id from IBKR web portal."""
    try:
        xml_str = _flex_fetch_xml(query_id)
    except Exception as exc:
        raise HTTPException(500, str(exc))
    trades = _flex_parse_trades(xml_str)
    if ticker:
        trades = [t for t in trades if t["symbol"].upper() == ticker.upper()]
    return {"count": len(trades), "query_id": query_id, "trades": trades}


@app.post("/manual-trader/backfill-pnl")
def mt_backfill_pnl(query_id: str):
    """
    Fetch executions via Flex Query and backfill close_fills + close_pnl
    for MT closed positions that have close_fills={}.
    Also updates trade_journal rows.
    """
    try:
        xml_str = _flex_fetch_xml(query_id)
    except Exception as exc:
        raise HTTPException(500, f"Flex fetch failed: {exc}")

    all_trades = _flex_parse_trades(xml_str)
    # Index closing option trades by local_symbol (e.g. "AMD   260731P00440000")
    # Flex's `symbol` field for options IS the local symbol — use it directly.
    close_by_local: dict[str, dict] = {}
    for t in all_trades:
        if t["open_close"] != "C" or t["asset_cat"] != "OPT":
            continue
        sym = t["symbol"].strip()
        # Keep most recent close if duplicate
        if sym not in close_by_local or t["trade_date"] > close_by_local[sym]["trade_date"]:
            close_by_local[sym] = t

    mt = state["manual_trader"]
    updated = []
    skipped = []

    for pos in list(mt["closed"]):
        if pos.get("close_fills"):        # already has fills — skip
            skipped.append(pos["pos_id"])
            continue

        new_fills: dict[str, float] = {}
        new_pnl = 0.0
        for leg in pos.get("legs", []):
            local_sym = leg["local_symbol"].strip()
            cand = close_by_local.get(local_sym)
            if not cand:
                break   # leg not found — can't reconcile this position fully
            close_price = abs(cand["trade_price"])
            new_fills[leg["local_symbol"]] = close_price
            sign = 1 if leg["action"] == "BUY" else -1
            new_pnl += sign * (close_price - leg["fill_price"]) * leg["qty"] * leg.get("multiplier", 100)
        else:
            # All legs found
            new_pnl = round(new_pnl, 2)
            pos["close_fills"] = new_fills
            pos["close_pnl"]   = new_pnl
            pos["win"]         = 1 if new_pnl > 0 else 0
            updated.append({"pos_id": pos["pos_id"], "fills": new_fills, "pnl": new_pnl})

            # Update trade_journal
            jid = pos.get("journal_id")
            if jid:
                try:
                    con = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
                    con.execute("""
                        UPDATE trade_journal
                        SET pnl=?, win=?, notes=notes||?
                        WHERE id=?
                    """, (new_pnl, pos["win"], "\nFILLS(flex):" + json.dumps(new_fills), jid))
                    con.commit()
                    con.close()
                except Exception as exc:
                    log.warning("backfill_pnl journal update failed: %s", exc)

    if updated:
        _mt_save_state()

    return {
        "updated":  updated,
        "skipped":  skipped,
        "total_flex_trades": len(all_trades),
    }


@app.get("/pnl/dashboard")
def pnl_dashboard():
    """Unified P&L dashboard: account metrics, per-position data, chart series."""
    from collections import defaultdict

    acct: dict = {}
    try:
        acct = account_summary()
    except Exception:
        pass

    # ── Alpaca account snapshot -- found 2026-09-03 that this dashboard's
    # "Net Liquidation" was IBKR-only (account_summary() never touches
    # Alpaca), even though a real, growing share of this account's capital
    # and trading (GOOG condor, 0DTE butterflies, Ashley signal-follow,
    # Safe Income once it fires) lives at Alpaca, not IBKR. Same
    # TradingClient pattern already used by GET /alpaca/positions. Never
    # fatal to the dashboard if Alpaca is unreachable.
    alpaca_acct: dict = {}
    _apositions: list = []
    try:
        from alpaca.trading.client import TradingClient as _AlpTC
        with open(os.path.join(os.path.dirname(__file__), "scanner_config.json")) as _f:
            _acfg = json.load(_f)
        if _acfg.get("alpaca_api_key") and _acfg.get("alpaca_secret_key"):
            _aclient = _AlpTC(_acfg["alpaca_api_key"], _acfg["alpaca_secret_key"],
                               paper=False, url_override=_acfg.get("alpaca_base_url"))
            _aacct = _aclient.get_account()
            _apositions = _aclient.get_all_positions()
            alpaca_acct = {
                "cash":   float(_aacct.cash),
                "equity": float(_aacct.equity),
                "options_buying_power": float(_aacct.options_buying_power) if _aacct.options_buying_power else None,
                "unrealized_pnl": round(sum(float(p.unrealized_pl or 0) for p in _apositions), 2),
                "open_position_count": len(_apositions),
            }
    except Exception as exc:
        log.warning("pnl_dashboard: alpaca account fetch failed: %s", exc)

    combined_net_liquidation = round((acct.get("net_liquidation") or 0) + (alpaca_acct.get("equity") or 0), 2)

    con      = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
    all_rows = con.execute("SELECT * FROM trade_journal ORDER BY id").fetchall()
    desc     = con.execute("SELECT * FROM trade_journal LIMIT 0").description or []
    cols     = [d[0] for d in desc]
    con.close()

    trades        = [dict(zip(cols, r)) for r in all_rows]
    open_trades   = [t for t in trades if t.get("closed_at") is None]
    closed_trades = sorted(
        [t for t in trades if t.get("closed_at") is not None],
        key=lambda t: t["closed_at"], reverse=True,
    )

    # ── Merge in Alpaca-executed strategies tracked via the separate registry
    # (alpaca_0dte_positions.json, register_position/close_position in
    # alpaca_0dte_common.py) instead of trade_journal.db -- found 2026-09-03
    # that GOOG weekly condor and the 0DTE butterflies (SPY/QQQ/IWM) were
    # completely invisible to this dashboard because they never write to
    # trade_journal.db at all. Excludes iron_condor_earnings/_INCOMPLETE
    # (pre-EVC-migration artifacts already tracked via EVC's own direct
    # trade_journal writes under strategy_type='earnings_vol_crush' --
    # merging them here too would double-count). Only rows with a real,
    # non-null close_pnl are included -- some registry entries were
    # reconciled 2026-09-03 with close_pnl deliberately left null because
    # the real number wasn't confidently verifiable (MLEG auto-close combo
    # pricing); showing a fabricated number would be worse than omitting it.
    _ALPACA_STRATEGY_MAP = {"iron_condor_weekly": "GOOG_CONDOR", "long_butterfly_0dte": None,
                             "ashley_signal": "ASHLEY_SIGNAL"}
    try:
        with open("alpaca_0dte_positions.json") as _f:
            _alp_reg = json.load(_f)
        for _p in _alp_reg.get("closed", []):
            _strat = _p.get("strategy")
            if _strat not in _ALPACA_STRATEGY_MAP or _p.get("close_pnl") is None:
                continue
            _stype = _ALPACA_STRATEGY_MAP[_strat] or f"BUTTERFLY_{_p.get('ticker', '')}"
            _strike, _right = None, None
            if _strat == "ashley_signal":
                _legs = _p.get("legs") or []
                if _legs:
                    _strike = _legs[0].get("strike")
                    _sym = _legs[0].get("symbol") or ""
                    if len(_sym) >= 9 and _sym[-9] in ("C", "P"):
                        _right = _sym[-9]
                    else:
                        # fall back to parsing pos_id, e.g. "ASHLEY_765.0C_20260826_122634"
                        _head = _p.get("pos_id", "").rsplit("_", 2)[0]
                        if _head and _head[-1] in ("C", "P"):
                            _right = _head[-1]
            closed_trades.append({
                "id": None, "opened_at": _p.get("entry_time"), "closed_at": _p.get("closed_at"),
                "ticker": _p.get("ticker"), "expiry": None, "strike": _strike, "right": _right,
                "action": {"iron_condor_weekly": "SELL_CONDOR", "ashley_signal": "BUY"}.get(_strat, "BUY_BUTTERFLY"),
                "qty": _p.get("qty", 1), "entry_price": _p.get("net_entry_credit"), "exit_price": None,
                "pnl": _p.get("close_pnl"), "pnl_pct": None,
                "win": 1 if _p.get("close_pnl", 0) > 0 else 0,
                "exit_reason": "alpaca_registry_close", "strategy_type": _stype,
                "commission": 0.0, "is_paper": 0, "notes": _p.get("close_reason"),
                "max_profit": None, "dte": None,
            })
        closed_trades.sort(key=lambda t: t["closed_at"], reverse=True)
    except Exception as exc:
        log.warning("pnl_dashboard: alpaca registry merge failed: %s", exc)

    daily: dict = defaultdict(float)
    for t in closed_trades:
        day = (t.get("closed_at") or "")[:10]
        if day and t.get("pnl") is not None:
            daily[day] += t["pnl"]
    cum      = 0.0
    daily_pnl = []
    for day, pnl in sorted(daily.items()):
        cum += pnl
        daily_pnl.append({"date": day, "pnl": round(pnl, 2), "cumulative": round(cum, 2)})

    # Found 2026-09-03: this used to be an INCLUDE whitelist of known-good exit
    # reasons -- and EVC alone has accumulated 7+ bespoke, incident-descriptive
    # exit reasons over time (e.g. "expired_ITM_call_spread_max_loss_real_..."
    # "premature_stop_pre_earnings_gate_bug", "manual_close_3of4_legs_1_..."),
    # none of which were ever added to the whitelist. Net effect: ALL 11 of
    # EVC's real (is_paper=0) closed trades were silently excluded from every
    # stat on this dashboard (total_realized_pnl, win_rate, EVC's own
    # per-strategy card) -- real net -$1,653 completely invisible. A
    # dynamically-worded reason from Manual Trader ("profit_target_hit
    # ($+18.19 >= $18.0)") was excluded the same way. Checked the full real
    # distribution: "orphaned" is the ONLY genuinely non-informative value in
    # the entire table (274 rows) -- every other exit_reason, however
    # bespoke-worded, represents a real completed close. An EXCLUDE list is
    # inherently more robust here: a new incident can only ever produce a new
    # DESCRIPTIVE reason (which should count), never accidentally resurrect
    # "orphaned" as if it were a real exit.
    _JUNK_EXIT_REASONS = {"orphaned", "unknown", None, ""}
    real_closed   = [t for t in closed_trades if t.get("exit_reason") not in _JUNK_EXIT_REASONS]
    closed_pnls   = [t["pnl"] for t in real_closed if t.get("pnl") is not None]
    wins          = [t for t in real_closed if t.get("win") == 1]
    losses        = [t for t in real_closed if t.get("win") == 0]
    today_str     = date.today().isoformat()
    today_pnl     = sum(
        t["pnl"] for t in real_closed
        if (t.get("closed_at") or "")[:10] == today_str and t.get("pnl") is not None
    )

    exit_breakdown: dict = {}
    for t in closed_trades:
        reason = t.get("exit_reason") or "unknown"
        exit_breakdown.setdefault(reason, {"count": 0, "pnl": 0.0})
        exit_breakdown[reason]["count"] += 1
        if t.get("pnl") is not None:
            exit_breakdown[reason]["pnl"] = round(exit_breakdown[reason]["pnl"] + t["pnl"], 2)

    portfolio_items: list = []
    ib_connected = bool(state.get("ib") and state.get("connected"))
    if ib_connected:
        try:
            for item in state["ib"].portfolio():
                c = item.contract
                portfolio_items.append({
                    "ticker":         c.symbol,
                    "sec_type":       getattr(c, "secType", ""),
                    "strike":         getattr(c, "strike", None),
                    "right":          getattr(c, "right", None),
                    "expiry":         (getattr(c, "lastTradeDateOrContractMonth", "") or "")[:8] or None,
                    "position":       item.position,
                    "avg_cost":       round(float(item.averageCost or 0), 4),
                    "market_value":   round(float(item.marketValue or 0), 2),
                    "unrealized_pnl": round(float(item.unrealizedPNL or 0), 2),
                    "realized_pnl":   round(float(item.realizedPNL or 0), 2),
                })
        except Exception:
            pass

    # ── Per-strategy today breakdown ─────────────────────────────────────────
    strategy_today: dict = {}
    for t in real_closed:
        if (t.get("closed_at") or "")[:10] != today_str:
            continue
        if t.get("pnl") is None:
            continue
        key = t.get("strategy_type") or "OTHER"
        if key not in strategy_today:
            strategy_today[key] = {"pnl": 0.0, "trades": 0, "wins": 0, "losses": 0}
        strategy_today[key]["pnl"]    = round(strategy_today[key]["pnl"] + t["pnl"], 2)
        strategy_today[key]["trades"] += 1
        if t.get("win") == 1:
            strategy_today[key]["wins"] += 1
        else:
            strategy_today[key]["losses"] += 1
    # Merge live SPX 0DTE today_pnl (includes trades not yet in journal from this session)
    spx_live = state.get("spx_0dte", {})
    if spx_live.get("today_pnl") and "SPX_0DTE" not in strategy_today:
        strategy_today["SPX_0DTE"] = {
            "pnl":    round(float(spx_live["today_pnl"]), 2),
            "trades": spx_live.get("attempts_today", 0),
            "wins":   sum(1 for t in spx_live.get("closed_today", []) if t.get("exit_type") == "profit_target"),
            "losses": sum(1 for t in spx_live.get("closed_today", []) if t.get("exit_type") == "stop_loss"),
        }
    elif spx_live.get("today_pnl") and "SPX_0DTE" in strategy_today:
        # Prefer live state over journal (more up-to-date intraday)
        strategy_today["SPX_0DTE"]["pnl"] = round(float(spx_live["today_pnl"]), 2)

    total_commission = round(sum(t.get("commission") or 0 for t in real_closed), 2)
    total_realized   = round(sum(closed_pnls), 2) if closed_pnls else 0.0
    total_unrealized = round(float(acct.get("unrealized_pnl") or 0) + float(alpaca_acct.get("unrealized_pnl") or 0), 2)

    # ── Build open_positions: IBKR is the source of truth when connected ──────
    # Enrich each IBKR portfolio item with journal metadata (entry price, IV, etc.)
    # If not connected, fall back to recent journal entries (last 7 days).
    # Also auto-close journal entries that have no corresponding IBKR position.
    if ib_connected:
        # Build a lookup: (ticker, str(strike), right, expiry[:6]) → journal row
        def _jkey(ticker, strike, right, expiry):
            return (ticker, str(strike or ""), right or "", (expiry or "")[:6])

        jlookup = {}
        for t in open_trades:
            k = _jkey(t.get("ticker",""), t.get("strike"), t.get("right",""), t.get("expiry",""))
            jlookup[k] = t

        ibkr_keys = {
            _jkey(p["ticker"], p.get("strike"), p.get("right"), p.get("expiry"))
            for p in portfolio_items
        }

        # Auto-close open journal entries not present in IBKR portfolio.
        # Guard: only orphan when portfolio_items is non-empty. If the feed is
        # temporarily empty (post-reconnect, TWS restart), ibkr_keys = {} and
        # every open entry would be falsely orphaned, corrupting the journal.
        # Also guard: skip entries that have an active open order (Submitted /
        # PreSubmitted) — unfilled limit orders are not in the portfolio yet
        # and should not be marked orphaned before they have a chance to fill.
        active_order_jkeys: set = set()
        try:
            for t in state["ib"].openTrades():
                if t.orderStatus.status in ("Submitted", "PreSubmitted", "PendingSubmit"):
                    c = t.contract
                    active_order_jkeys.add(_jkey(
                        getattr(c, "symbol", ""),
                        getattr(c, "strike", None),
                        getattr(c, "right", None),
                        (getattr(c, "lastTradeDateOrContractMonth", "") or "")[:8],
                    ))
        except Exception:
            pass

        orphan_ids = [
            t["id"] for t in open_trades
            if t.get("strategy_type") != "manual_trader"   # MT spreads have no single strike/right
            and _jkey(t.get("ticker",""), t.get("strike"), t.get("right",""), t.get("expiry",""))
            not in ibkr_keys
            and _jkey(t.get("ticker",""), t.get("strike"), t.get("right",""), t.get("expiry",""))
            not in active_order_jkeys
        ]
        if orphan_ids and portfolio_items:
            try:
                _con = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
                ph   = ",".join("?" * len(orphan_ids))
                _con.execute(
                    f"UPDATE trade_journal SET closed_at=?, exit_reason='orphaned' "
                    f"WHERE id IN ({ph}) AND closed_at IS NULL",
                    [_utcnow().isoformat()] + orphan_ids,
                )
                _con.commit()
                _con.close()
                log.info("pnl_dashboard: auto-closed %d orphaned journal entries", len(orphan_ids))
            except Exception as e:
                log.warning("pnl_dashboard orphan cleanup failed: %s", e)

        # Build a roll_count lookup from live position tracking (not stored in journal schema)
        at_positions = state["autotrader"].get("positions", {})
        rc_lookup: dict = {}  # (ticker, right, str(strike), expiry[:8]) → roll_count
        for _info in at_positions.values():
            _key = (
                _info.get("ticker", ""),
                _info.get("right", ""),
                str(_info.get("strike", "")),
                (_info.get("expiry", "") or "")[:8],
            )
            rc_lookup[_key] = _info.get("roll_count", 0)

        # Merge IBKR portfolio item with journal enrichment
        visible_open = []
        for p in portfolio_items:
            jrow = jlookup.get(_jkey(p["ticker"], p.get("strike"), p.get("right"), p.get("expiry")), {})
            rc_key = (p["ticker"], p.get("right") or "", str(p.get("strike") or ""), (p.get("expiry") or "")[:8])
            visible_open.append({
                "id":             jrow.get("id"),
                "ticker":         p["ticker"],
                "strategy_type":  jrow.get("strategy_type") or None,
                "action":         jrow.get("action", "BUY" if (p.get("position") or 0) > 0 else "SELL"),
                "strike":         p.get("strike"),
                "right":          p.get("right"),
                "expiry":         p.get("expiry"),
                "qty":            abs(p.get("position") or 0),
                "entry_price":    jrow.get("entry_price"),
                "avg_cost":       p.get("avg_cost"),
                "market_value":   p.get("market_value"),
                "unrealized_pnl": p.get("unrealized_pnl"),
                "live_iv_entry":  jrow.get("live_iv_entry"),
                "roll_count":     rc_lookup.get(rc_key, 0),
                "opened_at":      jrow.get("opened_at"),
                "dte":            jrow.get("dte"),
                "is_paper":       jrow.get("is_paper", 1),
            })
    else:
        # Disconnected: fall back to recent journal entries (last 7 days)
        recent_cutoff = (_utcnow() - timedelta(days=7)).isoformat()
        visible_open  = [
            t for t in open_trades
            if (t.get("opened_at") or "") >= recent_cutoff
        ]

    # ── Merge in currently-OPEN Alpaca-registry positions (added 2026-09-04) ──
    # Real gap found live: visible_open only ever came from IBKR's own
    # portfolio_items above -- a position actually held at Alpaca (the 0DTE
    # butterflies, Ashley signal-follow, GOOG condor) was completely invisible
    # here WHILE STILL OPEN, even though its P&L is already folled into
    # alpaca_acct's aggregate unrealized_pnl a few lines up. Made concrete
    # 2026-09-04: 3 real trades (QQQ butterfly, IWM butterfly, Ashley SPY
    # 770C) sat open all morning with zero visibility on this dashboard --
    # the user could see the TOTAL move but not which position caused it.
    # Reuses _apositions (already fetched above for alpaca_acct -- no extra
    # API call) for real, live qty/market_value/unrealized_pnl per leg.
    try:
        _apos_by_symbol = {p.symbol: p for p in _apositions}
        with open("alpaca_0dte_positions.json") as _f:
            _alp_reg_open = json.load(_f)
        for _pid, _p in _alp_reg_open.get("positions", {}).items():
            for _leg in _p.get("legs", []):
                _sym = _leg.get("symbol", "")
                _ap = _apos_by_symbol.get(_sym)
                if _ap is None:
                    continue   # already closed at Alpaca but registry hasn't caught up yet
                _right = _sym[-9] if len(_sym) >= 9 else None
                _expiry = ("20" + _sym[-15:-9]) if len(_sym) >= 15 else None
                visible_open.append({
                    "id": None, "ticker": _p.get("ticker"),
                    "strategy_type": f"{_p.get('strategy', 'alpaca')}_{_leg.get('leg', '')}".upper(),
                    "action": "BUY" if str(_ap.side).endswith("LONG") else "SELL",
                    "strike": _leg.get("strike"), "right": _right, "expiry": _expiry,
                    "qty": abs(float(_ap.qty)),
                    "entry_price": _leg.get("fill"),
                    "avg_cost": float(_ap.avg_entry_price) if _ap.avg_entry_price else None,
                    "market_value": float(_ap.market_value) if _ap.market_value else None,
                    "unrealized_pnl": round(float(_ap.unrealized_pl), 2) if _ap.unrealized_pl else 0.0,
                    "live_iv_entry": None, "roll_count": 0,
                    "opened_at": _p.get("entry_time"), "dte": None, "is_paper": 0,
                    "pos_id": _pid,
                })
    except Exception as exc:
        log.warning("pnl_dashboard: alpaca open-position merge failed: %s", exc)

    return {
        "account":  acct,
        "alpaca_account": alpaca_acct,
        "combined_net_liquidation": combined_net_liquidation,
        "is_live":  state.get("is_live", False),
        "stats": {
            "total_trades":         len(real_closed),
            "open_count":           len(portfolio_items) if ib_connected else len(open_trades),
            "win_rate":             round(len(wins) / len(real_closed) * 100, 1) if real_closed else None,
            "total_realized_pnl":   total_realized,
            "total_commission":     total_commission,
            "net_realized_pnl":     round(total_realized - total_commission, 2),
            "total_unrealized_pnl": total_unrealized,
            "total_pnl":            round(total_realized + total_unrealized, 2),
            "today_pnl":            round(today_pnl, 2),
            "avg_win":              round(sum(t["pnl"] for t in wins   if t.get("pnl")) / len(wins),   2) if wins   else 0,
            "avg_loss":             round(sum(t["pnl"] for t in losses if t.get("pnl")) / len(losses), 2) if losses else 0,
            "best_trade":           round(max(closed_pnls), 2) if closed_pnls else 0,
            "worst_trade":          round(min(closed_pnls), 2) if closed_pnls else 0,
        },
        "open_positions":   visible_open,
        "closed_trades":   real_closed[:300],
        "daily_pnl":       daily_pnl,
        "portfolio":       portfolio_items,
        "exit_breakdown":  exit_breakdown,
        "strategy_today":  strategy_today,
        "mt_open":  [
            {
                "pos_id":     pos_id,
                "name":       pos.get("name"),
                "ticker":     pos.get("ticker"),
                "strategy":   pos.get("strategy"),
                "expiry":     pos.get("expiry"),
                "net_entry":  pos.get("net_entry"),
                "live_pnl":   pos.get("live_pnl", 0.0),
                "profit_target_usd": pos.get("profit_target_usd"),
                "stop_loss_usd":     pos.get("stop_loss_usd"),
                "hard_close_time":   pos.get("hard_close_time"),
                "entry_time": pos.get("entry_time"),
                "journal_id": pos.get("journal_id"),
            }
            for pos_id, pos in state.get("manual_trader", {}).get("positions", {}).items()
        ],
        "mt_closed": [
            {
                "pos_id":       pos.get("pos_id"),
                "name":         pos.get("name"),
                "ticker":       pos.get("ticker"),
                "strategy":     pos.get("strategy"),
                "net_entry":    pos.get("net_entry"),
                "close_pnl":    pos.get("close_pnl"),
                "live_pnl":     pos.get("live_pnl"),
                "close_reason": pos.get("close_reason"),
                "closed_at":    pos.get("closed_at"),
                "close_fills":  pos.get("close_fills", {}),
            }
            for pos in state.get("manual_trader", {}).get("closed", [])
        ],
    }


@app.post("/journal/cleanup")
def journal_cleanup():
    """
    Mark phantom open journal entries as closed (exit_reason='orphaned').

    An entry is orphaned when closed_at IS NULL but is not tracked in the
    current autotrader positions dict AND was opened more than 24 hours ago.
    Entries opened within the last 24 h are left alone — they may still be
    working orders waiting to fill.
    """
    active_journal_ids: set = {
        info.get("journal_id")
        for info in state["autotrader"].get("positions", {}).values()
        if info.get("journal_id") is not None
    }
    cutoff = (_utcnow() - timedelta(hours=24)).isoformat()
    con = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
    # Fetch all open entries older than 24 h
    rows = con.execute(
        "SELECT id FROM trade_journal WHERE closed_at IS NULL AND opened_at < ?",
        (cutoff,),
    ).fetchall()
    orphan_ids = [r[0] for r in rows if r[0] not in active_journal_ids]
    if orphan_ids:
        con.execute(
            f"UPDATE trade_journal SET closed_at=?, exit_reason='orphaned' "
            f"WHERE id IN ({','.join('?' * len(orphan_ids))}) AND closed_at IS NULL",
            [_utcnow().isoformat()] + orphan_ids,
        )
        con.commit()
    con.close()
    log.info("Journal cleanup: marked %d orphaned entries as closed", len(orphan_ids))
    return {
        "ok": True,
        "orphaned": len(orphan_ids),
        "active_tracked": len(active_journal_ids),
        "message": f"Closed {len(orphan_ids)} phantom open entries (exit_reason=orphaned, pnl left null — excluded from stats)",
    }


@app.post("/journal/retrain")
def trigger_retrain():
    """Manually trigger model retraining from journal data."""
    try:
        result = _retrain_from_journal()
        return result
    except Exception as exc:
        raise HTTPException(500, str(exc))


