@app.get("/earnings-vol-crush/preview/{ticker}")
async def evc_preview_ticker(ticker: str):
    """Read-only: build the real condor quote and run the same CRO/CFO
    pre-trade review /enter/{ticker} uses, WITHOUT calling
    _evc_place_condor -- lets a candidate be evaluated (strikes, credit,
    approval, scenarios) without risking an actual order."""
    ib = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IBKR not connected — ensure TWS/IB Gateway is running")
    ticker = ticker.upper()
    ev_cfg = state["evc"]["config"]

    async def _do_preview(ib):
        quote = await _evc_quote_condor(ib, ticker)
        try:
            alp_cfg = _alp_load_config()
            client  = _alp_client(alp_cfg)
            alpaca_equity = float(client.get_account().equity)
        except Exception:
            alpaca_equity = 0.0
        ibkr_net_liq = _get_net_liq(ib) if ib and ib.isConnected() else 0.0
        review = _evc_pretrade_review(ticker, quote, ibkr_net_liq, alpaca_equity, ev_cfg)
        return {
            "ticker":         ticker,
            "spot":           quote["spot"],
            "expected_move":  quote["expected_move"],
            "strikes":        f"{quote['long_put']}/{quote['short_put']}P | {quote['short_call']}/{quote['long_call']}C",
            "net_credit":     quote["net_credit"],
            "im_pct":         quote.get("im_pct"),
            "approved":       review["approved"],
            "findings":       review["findings"],
            "scenarios":      review["scenarios"],
        }

    loop = asyncio.get_event_loop()
    try:
        result = await loop.run_in_executor(
            None,
            lambda: _run_in_streaming_loop(_do_preview(ib), timeout=120))
    except (ValueError, RuntimeError) as e:
        raise HTTPException(400, str(e))
    return result


@app.post("/earnings-vol-crush/enter/{ticker}")
async def evc_enter_ticker(ticker: str):
    """Manually trigger EVC entry for a specific ticker, bypassing the candidate list and time window."""
    ev  = state["evc"]
    ib  = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IBKR not connected — ensure TWS/IB Gateway is running")
    ticker = ticker.upper()
    if ticker in ev["positions"]:
        raise HTTPException(409, f"{ticker} already has an open EVC position")

    async def _do_enter(ib):
        quote   = await _evc_quote_condor(ib, ticker)
        success = await _evc_place_condor(ib, quote)
        return {
            "success": success,
            "ticker":  ticker,
            "strikes": f"{quote['long_put']}/{quote['short_put']}P | {quote['short_call']}/{quote['long_call']}C",
            "credit":  quote["net_credit"],
            "em_pct":  f"{quote['im_pct']:.1%}",
        }

    loop = asyncio.get_event_loop()
    try:
        # timeout raised 180->300s: real incident 2026-08-26 (DLTR). At
        # 180s this timed out while place_condor_sequential's ladder
        # retries were still legitimately in progress (up to ~240s worst
        # case across 4 legs since the 2026-08-26 ladder fix) --
        # _run_in_streaming_loop's future.cancel() doesn't stop the
        # underlying synchronous, time.sleep()-based executor thread, so
        # the real order placement kept running orphaned in the
        # background after this endpoint had already returned an error,
        # with no path left to record the eventual result into
        # ev["positions"]. 300s comfortably covers the new worst case.
        result = await loop.run_in_executor(
            None,
            lambda: _run_in_streaming_loop(_do_enter(ib), timeout=300))
    except (ValueError, RuntimeError) as e:
        raise HTTPException(400, str(e))
    return result


# ══════════════════════════════════════════════════════════════════════════════
# IBKR POSITION RECONCILIATION
# Startup: runs once after IB connects, flags any divergence between
#          strategy state and what IBKR actually holds.
# Periodic: runs every 5 min during market hours (9:00–17:00 ET).
# Alerts via Telegram on:
#   • PHANTOM CLOSE  — state marked position closed, IBKR still holds the legs
#   • UNTRACKED      — IBKR holds a position no strategy claims ownership of
#   • GHOST OPEN     — state thinks position is open, IBKR holds nothing
# ══════════════════════════════════════════════════════════════════════════════

async def _ibkr_reconcile(ib, *, on_startup: bool = False) -> None:
    """Diff IBKR portfolio against all strategy states and alert on divergence."""
    label = "STARTUP" if on_startup else "PERIODIC"
    try:
        portfolio = list(ib.portfolio())
    except Exception as exc:
        log.warning("RECON [%s]: portfolio() failed: %s", label, exc)
        return

    if not portfolio:
        log.debug("RECON [%s]: empty portfolio response — skipping", label)
        return

    # ── 1. Build claimed conid / symbol sets from all open strategy positions ──
    claimed_conids: dict[int, str] = {}   # conid (int) → "STRAT/key"

    # EVC: 4 conids per open position
    for pos_id, pos in state["evc"]["positions"].items():
        for leg, cid in pos.get("conids", {}).items():
            if cid:
                claimed_conids[int(cid)] = f"EVC/{pos_id}/{leg}"

    # SPX 0DTE: up to 4 conids per spread
    for sid, sp in state["spx_0dte"]["spreads"].items():
        for cid in (sp.get("put_conids") or []) + (sp.get("call_conids") or []):
            if cid:
                claimed_conids[int(cid)] = f"SPX/{sid}"

    # Signal Trader: 1 conid per open position
    for pid, pos in state["sig_trader"]["positions"].items():
        if pos.get("conid") and pos.get("phase") != "closed":
            claimed_conids[int(pos["conid"])] = f"SIGT/{pid}"

    # Auto-trader: matched by contract key (symbol_right_strike_expiry), no conid stored
    at_keys = set(state["autotrader"].get("positions", {}).keys())

    # Manual Trader: legs matched by localSymbol (no conid stored in the leg
    # records), same identity _mt_reconcile_sync uses. Without this, every open
    # MT option leg lands in the 5-min "UNTRACKED OPTIONS" Telegram alert.
    mt_leg_syms = set()
    for _mp in state.get("manual_trader", {}).get("positions", {}).values():
        if _mp.get("phase") == "open":
            for _lg in _mp.get("legs", []):
                _ls = str(_lg.get("local_symbol") or "").replace(" ", "").upper()
                if _ls:
                    mt_leg_syms.add(_ls)

    # Day Trader + Auto-trader + Stock-trader stocks: matched by symbol.
    # Day Trader runs as its own standalone process since 2026-08-27
    # (day_trader_agent.py) -- read its positions from the shared state
    # file it owns rather than in-process state that no longer exists here.
    try:
        with open("day_trader_state.json") as _dtf:
            dt_symbols = set(json.load(_dtf).get("positions", {}).keys())
    except Exception:
        dt_symbols = set()
    at_symbols  = {k.split("_")[0] for k in at_keys}
    st_symbols  = set(state.get("stock_trader", {}).get("positions", {}).keys())
    # harami_daily_trader.py: real live stock positions, own standalone
    # process (same reason day-trader needs its state file read above) --
    # without this every real fill Telegrams as "UNTRACKED STOCKS".
    try:
        with open("harami_trader_state.json") as _hdf:
            harami_symbols = {p["ticker"].upper() for p in json.load(_hdf).get("positions", {}).values() if p.get("ticker")}
    except Exception:
        harami_symbols = set()
    claimed_stk = dt_symbols | at_symbols | st_symbols | harami_symbols

    # ── 2. Classify each IBKR position ──
    # Tickers the EVC strategy recently closed (may be phantom closes)
    evc_closed_tickers = {r["ticker"] for r in state["evc"].get("closed_today", [])}
    ibkr_conid_set = set()

    phantom_evc:    list = []
    untracked_opt:  list = []
    untracked_stk:  list = []

    for item in portfolio:
        c   = item.contract
        qty = item.position
        if qty == 0:
            continue

        cid = int(c.conId) if c.conId else None
        if cid:
            ibkr_conid_set.add(cid)

        if c.secType == "OPT":
            if cid and cid in claimed_conids:
                continue                        # owned by a strategy
            if _at_contract_key(c) in at_keys:
                continue                        # owned by auto-trader
            if (c.localSymbol or "").replace(" ", "").upper() in mt_leg_syms:
                continue                        # owned by Manual Trader

            # Unclaimed option — phantom close or truly foreign?
            if c.symbol in evc_closed_tickers:
                phantom_evc.append(item)
            else:
                untracked_opt.append(item)

        elif c.secType == "STK":
            if c.symbol in claimed_stk:
                continue
            if _at_contract_key(c) in at_keys:
                continue
            untracked_stk.append(item)

    # ── 3. Ghost opens: state says open, but the REAL venue holds none of it ──
    # Real bug found 2026-08-25 (INTU): every EVC position since 2026-08-19 is
    # placed via Alpaca (2026-08-11 architecture decision), so its "conids"
    # are only ever used for IBKR pricing/qualification -- they were never
    # expected to appear in IBKR's own portfolio. This check used to compare
    # them against ibkr_conid_set regardless, so a perfectly real, freshly-
    # filled Alpaca condor got immediately misclassified as a ghost and
    # stamped externally_closed, silently turning off its own exit monitoring
    # the same day it was entered. Fixed to check Alpaca-venue positions
    # against Alpaca's real holdings instead of IBKR's.
    ghost_evc: list = []
    alpaca_symbols_held: Optional[set] = None  # lazy-loaded, only if needed
    for pos_id, pos in list(state["evc"]["positions"].items()):
        if pos.get("phase") not in ("open", None):
            continue  # already closing/closed -- not a ghost-open candidate
        if pos.get("venue") == "alpaca":
            if alpaca_symbols_held is None:
                alpaca_symbols_held = set()
                try:
                    alp_cfg = _alp_load_config()
                    alp_client = _alp_client(alp_cfg)
                    alpaca_symbols_held = {p.symbol for p in alp_client.get_all_positions()}
                except Exception as exc:
                    log.warning("RECON [%s]: could not fetch Alpaca positions for ghost-check: %s", label, exc)
                    continue  # can't verify -- don't misclassify on a fetch failure
            pos_symbols = set(pos.get("alpaca_symbols", {}).values())
            if pos_symbols and not pos_symbols & alpaca_symbols_held:
                ghost_evc.append((pos_id, pos))
                pos["phase"] = "externally_closed"   # stop monitor from trying to exit
        else:
            pos_conids = {int(c) for c in pos.get("conids", {}).values() if c}
            if pos_conids and not pos_conids & ibkr_conid_set:
                ghost_evc.append((pos_id, pos))
                pos["phase"] = "externally_closed"   # stop monitor from trying to exit
    if ghost_evc:
        _evc_save_state()

    # ── 4. Nothing to report? ──
    total_issues = len(phantom_evc) + len(untracked_opt) + len(untracked_stk) + len(ghost_evc)
    if total_issues == 0:
        log.info("RECON [%s]: all %d IBKR positions accounted for", label, len(portfolio))
        return

    # ── 5. Build Telegram alert ──
    lines: list[str] = []

    if phantom_evc:
        lines.append(f"<b>PHANTOM CLOSE ({len(phantom_evc)} legs)</b>")
        lines.append("State marked these closed; IBKR still holds them:")
        for item in phantom_evc:
            c = item.contract
            lines.append(
                f"  {c.symbol} {c.right}{int(c.strike)}"
                f" exp={c.lastTradeDateOrContractMonth}"
                f" pos={item.position:+.0f}"
                f" upnl={item.unrealizedPNL:+.2f}"
            )
        lines.append("  Manual close required (TWS or /evc-close endpoint).")
        lines.append("")

    if untracked_opt:
        lines.append(f"<b>UNTRACKED OPTIONS ({len(untracked_opt)})</b>")
        lines.append("No strategy owns these option legs:")
        for item in untracked_opt:
            c = item.contract
            lines.append(
                f"  {c.symbol} {c.right}{int(c.strike)}"
                f" exp={c.lastTradeDateOrContractMonth}"
                f" pos={item.position:+.0f}"
                f" upnl={item.unrealizedPNL:+.2f}"
            )
        lines.append("")

    if untracked_stk:
        lines.append(f"<b>UNTRACKED STOCKS ({len(untracked_stk)})</b>")
        for item in untracked_stk:
            c = item.contract
            lines.append(
                f"  {c.symbol}  pos={item.position:+.0f}"
                f"  upnl={item.unrealizedPNL:+.2f}"
            )
        lines.append("")

    if ghost_evc:
        lines.append(f"<b>GHOST OPENS ({len(ghost_evc)} EVC)</b>")
        lines.append("State showed open but IBKR holds nothing — marked externally_closed:")
        for pos_id, pos in ghost_evc:
            lines.append(
                f"  {pos_id}  credit={pos.get('net_credit', '?')}"
                f"  entry={pos.get('entry_time', '?')[:10]}"
            )
        lines.append("")

    msg = f"<b>⚠️ IBKR RECON [{label}]</b>\n\n" + "\n".join(lines)
    log.warning("RECON [%s]: %d issue(s) detected", label, total_issues)
    _evc_notify(msg)


async def _ibkr_startup_reconcile() -> None:
    """Wait for IB to connect, then run a one-time startup reconcile."""
    for _ in range(60):         # poll up to 5 minutes (5s intervals)
        await asyncio.sleep(5)
        ib = state.get("ib")
        if ib and ib.isConnected():
            await asyncio.sleep(3)  # let portfolio items populate
            try:
                await _ibkr_reconcile(ib, on_startup=True)
            except Exception as exc:
                log.warning("RECON startup: unhandled error: %s", exc)
            return
    log.warning("RECON startup: IB never connected within 5 min — skipped")


async def _ibkr_reconcile_loop() -> None:
    """Run IBKR reconciliation every 5 minutes during market hours."""
    from zoneinfo import ZoneInfo
    _ET = ZoneInfo("America/New_York")
    while True:
        await asyncio.sleep(300)
        ib = state.get("ib")
        if not ib or not ib.isConnected():
            continue
        now_et = datetime.now(_ET)
        if now_et.weekday() >= 5:
            continue                         # weekend
        t = now_et.strftime("%H:%M")
        if not ("09:00" <= t <= "17:00"):
            continue
        try:
            await _ibkr_reconcile(ib, on_startup=False)
        except Exception as exc:
            log.warning("RECON periodic: unhandled error: %s", exc)


# ══════════════════════════════════════════════════════════════════════════════
# REAL-TIME AUTO-CORRECTING RECONCILIATION ENGINE  (2026-09-10)
# ══════════════════════════════════════════════════════════════════════════════
# Continuously forces every strategy's own position records to match real
# IBKR + Alpaca state. Motivated by a live incident: a Signal Trader CVX
# call was recorded "closed" while still really open at IBKR. Auto-corrects
# two cases -- PHANTOM CLOSE (record closed but broker still holds it ->
# reopen) and EXTERNAL CLOSE (record open but broker is flat -> mark
# closed) -- across every in-process strategy, the alpaca_0dte registry,
# and (via HTTP /reconcile) the two standalone agents. Every mutation is
# debounced >=2 cycles, Telegram-alerted, and written to oversight_log. A
# kill-switch (reconciliation_config.json autocorrect_enabled=false) drops
# it to detect+alert-only. Runs ALONGSIDE _ibkr_reconcile (kept for its
# untracked-position alerting) -- this engine owns the auto-correction.

RECONCILE_STATE_PATH  = "reconciliation_state.json"
RECONCILE_CONFIG_PATH = "reconciliation_config.json"
_reconcile_lock = threading.Lock()
_reconcile_last_summary: dict = {
    "last_run": None, "corrections": [], "alerts": [], "skips": [], "autocorrect_enabled": True,
}
_FES_MANUAL_CONID = 773081649   # user's own manual FES futures-option -- never flag (project_fes_position_manual memory)
DAY_TRADER_AGENT_URL_RECON = "http://localhost:8010"
SPY_CONDOR_AGENT_URL_RECON = "http://localhost:8011"


def _reconcile_cfg() -> dict:
    try:
        with open(RECONCILE_CONFIG_PATH) as f:
            c = json.load(f)
    except Exception:
        c = {}
    return {"autocorrect_enabled": bool(c.get("autocorrect_enabled", True)),
            "cycle_seconds": int(c.get("cycle_seconds", 60))}


def _reconcile_state_load() -> dict:
    try:
        with open(RECONCILE_STATE_PATH) as f:
            return json.load(f)
    except Exception:
        return {"absent_counts": {}}   # "strategy/pos_id" -> consecutive all-absent cycle count


def _reconcile_state_save(s: dict) -> None:
    try:
        with open(RECONCILE_STATE_PATH, "w") as f:
            json.dump(s, f, indent=2)
    except Exception as e:
        log.warning("reconcile state save failed: %s", e)


def _recon_iter_all_open():
    """Yield one normalized open-position record per in-process strategy +
    the alpaca_0dte registry. Manual Trader is intentionally EXCLUDED --
    _mt_reconcile_sync already auto-corrects it on every MT monitor tick
    with the exact same logic (folding it in here would just race)."""
    def _ci(x):
        try:
            return int(x)
        except Exception:
            return None

    for pid, p in list(state.get("sig_trader", {}).get("positions", {}).items()):
        # "closing" counts as tracked-open too: a position stuck mid-close
        # (SELL filled but the code path was cut off before recording) is
        # invisible to the monitor AND was invisible here, so nothing ever
        # reconciled it. The 2-cycle debounce still protects a genuine
        # in-flight close (its conid is still in ib.positions() until filled).
        if p.get("phase") not in ("open", "closing"):
            continue
        cid = _ci(p.get("conid"))
        yield {"strategy": "sig_trader", "pos_id": pid, "conids": [cid] if cid else [],
               "leg_symbols": [], "symbols": [], "n_legs": 1, "venue": "ibkr", "raw": p}

    for pid, p in list(state.get("evc", {}).get("positions", {}).items()):
        if p.get("phase") not in ("open", None):
            continue
        conids = [c for c in (_ci(v) for v in (p.get("conids") or {}).values()) if c]
        asyms = [s for s in (p.get("alpaca_symbols") or []) if s]
        yield {"strategy": "evc", "pos_id": pid, "conids": conids, "leg_symbols": asyms,
               "symbols": [], "n_legs": max(len(conids), len(asyms), 4),
               "venue": p.get("venue", "alpaca"), "raw": p}

    for sid, sp in list(state.get("spx_0dte", {}).get("spreads", {}).items()):
        conids = [c for c in (_ci(v) for v in ((sp.get("put_conids") or []) + (sp.get("call_conids") or []))) if c]
        yield {"strategy": "spx_0dte", "pos_id": sid, "conids": conids, "leg_symbols": [],
               "symbols": [], "n_legs": max(len(conids), 4), "venue": "ibkr", "raw": sp}

    for tk, p in list(state.get("stock_trader", {}).get("positions", {}).items()):
        if p.get("phase") == 0:          # 0 = pending buy, not a real position yet
            continue
        yield {"strategy": "stock_trader", "pos_id": tk, "conids": [], "leg_symbols": [],
               "symbols": [tk], "n_legs": 1, "venue": "ibkr", "raw": p}

    for pair, p in list(state.get("fx_trader", {}).get("positions", {}).items()):
        if p.get("phase") not in ("open", "closing"):
            continue
        cid = _ci(p.get("conid"))
        yield {"strategy": "fx_trader", "pos_id": pair, "conids": [cid] if cid else [],
               "leg_symbols": [], "symbols": [], "n_legs": 1, "venue": "ibkr", "raw": p,
               "is_fx": True}

    for key, p in list(state.get("autotrader", {}).get("positions", {}).items()):
        yield {"strategy": "autotrader", "pos_id": key, "conids": [], "leg_symbols": [],
               "symbols": [], "at_key": key, "n_legs": 1, "venue": "ibkr", "raw": p,
               "no_reopen": True}

    try:
        with open("alpaca_0dte_positions.json") as f:
            areg = json.load(f)
        for pid, p in (areg.get("positions") or {}).items():
            legs = [l.get("symbol") for l in (p.get("legs") or []) if l.get("symbol")]
            yield {"strategy": "alpaca_registry", "pos_id": pid, "conids": [],
                   "leg_symbols": legs, "symbols": [], "n_legs": max(len(legs), 1),
                   "venue": "ibkr", "raw": p, "no_reopen": True,
                   "registry_strategy": p.get("strategy")}
    except Exception:
        pass


def _recon_iter_all_closed():
    """Yield (strategy, pos_id, record) for recently-closed records that
    still carry enough contract info to be re-opened if the broker turns
    out to still hold them (the phantom-close case)."""
    for p in list(state.get("sig_trader", {}).get("closed_today", [])):
        yield "sig_trader", p.get("pos_id"), p
    for p in list(state.get("evc", {}).get("closed_today", [])):
        yield "evc", p.get("pos_id"), p
    for p in list(state.get("fx_trader", {}).get("closed_today", [])):
        yield "fx_trader", p.get("pos_id", p.get("pair")), p
    for p in list(state.get("stock_trader", {}).get("closed_today", [])):
        yield "stock_trader", p.get("pos_id", p.get("ticker")), p


def _recon_present(rec: dict, ibkr_idx: dict, alp_idx: set) -> str:
    """'all_present' | 'some_present' | 'all_absent' for one normalized record."""
    hits = 0
    for cid in rec.get("conids", []):
        if cid in ibkr_idx["conids"]:
            hits += 1
    for sym in rec.get("leg_symbols", []):
        s = str(sym).replace(" ", "").upper()
        if s in ibkr_idx["localsyms"] or s in alp_idx:
            hits += 1
    for sym in rec.get("symbols", []):
        if str(sym).upper() in ibkr_idx["stock_syms"]:
            hits += 1
    if rec.get("at_key") and rec["at_key"] in ibkr_idx["at_keys"]:
        hits += 1
    n = max(rec.get("n_legs", 1), 1)
    if hits == 0:
        return "all_absent"
    return "all_present" if hits >= n else "some_present"


def _recon_journal_close(strategy_type: str, ticker) -> None:
    try:
        con = sqlite3.connect(JOURNAL_DB_PATH)
        con.execute("""UPDATE trade_journal SET
            closed_at=?, exit_reason='reconcile_externally_closed', win=0,
            notes=COALESCE(notes,'')||' | reconcile: externally closed'
            WHERE id = (SELECT id FROM trade_journal
                        WHERE ticker=? AND strategy_type=? AND closed_at IS NULL
                        ORDER BY id DESC LIMIT 1)""",
            (_utcnow().isoformat(), ticker, strategy_type))
        con.commit(); con.close()
    except Exception as e:
        log.warning("reconcile journal-close failed (%s/%s): %s", strategy_type, ticker, e)


def _recon_apply_close(rec: dict) -> bool:
    """Move a strategy's open record to its closed container. Returns True on success."""
    strat, pid, raw = rec["strategy"], rec["pos_id"], rec["raw"]
    now_z = _utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        if strat == "sig_trader":
            st = state["sig_trader"]; p = st["positions"].pop(pid, None)
            if not p:
                return False
            p.update({"phase": "closed", "exit_reason": "reconcile_externally_closed",
                      "exit_price": None, "pnl": None, "closed_at": now_z})
            st["closed_today"].append(p); _sigt_save_state()
            _recon_journal_close("signal_trader_futures" if p.get("instrument_type") == "future" else "signal_trader", p.get("ticker"))
            return True
        if strat == "evc":
            ev = state["evc"]; p = ev["positions"].pop(pid, None)
            if not p:
                return False
            p.update({"phase": "externally_closed", "close_reason": "reconcile_externally_closed",
                      "closed_at": now_z})
            ev["closed_today"].append(p); _evc_save_state()
            _recon_journal_close("earnings_vol_crush", p.get("ticker"))
            return True
        if strat == "spx_0dte":
            sx = state["spx_0dte"]; sp = sx["spreads"].pop(pid, None)
            if not sp:
                return False
            sp.update({"phase": "closed", "exit_type": "reconcile_externally_closed", "closed_at": now_z})
            sx.setdefault("closed_today", []).append(sp); _spx_save_state()
            _recon_journal_close("SPX_0DTE", "SPX")
            return True
        if strat == "stock_trader":
            stt = state["stock_trader"]; p = stt["positions"].pop(pid, None)
            if not p:
                return False
            p.update({"phase": 2, "close_reason": "reconcile_externally_closed", "closed_at": now_z})
            stt.setdefault("closed_today", []).append(p); _st_save_state()
            _recon_journal_close("STOCK_BREAKOUT", pid)
            return True
        if strat == "fx_trader":
            fx = state["fx_trader"]; p = fx["positions"].pop(pid, None)
            if not p:
                return False
            p.update({"phase": "closed", "close_reason": "reconcile_externally_closed", "closed_at": now_z})
            fx.setdefault("closed_today", []).append(p); _fx_save_state()
            _recon_journal_close("fx_trader", pid)
            return True
        if strat == "autotrader":
            at = state["autotrader"]
            if at.get("positions", {}).pop(pid, None) is None:
                return False
            _at_save_state()
            return True
        if strat == "alpaca_registry":
            try:
                from alpaca_0dte_common import close_position as _areg_close
                return _areg_close(pid, "reconcile_externally_closed", None) is not None
            except Exception as e:
                log.warning("reconcile: alpaca registry close failed %s: %s", pid, e)
                return False
    except Exception as e:
        log.warning("reconcile close-apply failed (%s/%s): %s", strat, pid, e)
    return False


def _recon_apply_reopen(strat: str, pid: str, closed_rec: dict) -> bool:
    """Move a phantom-closed record back to its open container."""
    try:
        if strat == "sig_trader":
            st = state["sig_trader"]
            st["closed_today"] = [c for c in st["closed_today"] if c.get("pos_id") != pid]
            closed_rec.update({"phase": "open", "exit_reason": None, "exit_price": None,
                               "pnl": None, "closed_at": None})
            st["positions"][pid] = closed_rec; _sigt_save_state()
            return True
        if strat == "evc":
            ev = state["evc"]
            ev["closed_today"] = [c for c in ev["closed_today"] if c.get("pos_id") != pid]
            closed_rec.update({"phase": "open", "close_reason": None, "closed_at": None})
            ev["positions"][pid] = closed_rec; _evc_save_state()
            return True
        if strat == "fx_trader":
            fx = state["fx_trader"]
            fx["closed_today"] = [c for c in fx.get("closed_today", []) if c.get("pos_id", c.get("pair")) != pid]
            closed_rec.update({"phase": "open", "close_reason": None, "closed_at": None})
            fx["positions"][pid] = closed_rec; _fx_save_state()
            return True
        if strat == "stock_trader":
            stt = state["stock_trader"]
            stt["closed_today"] = [c for c in stt.get("closed_today", []) if c.get("pos_id", c.get("ticker")) != pid]
            closed_rec.update({"phase": 1, "close_reason": None, "closed_at": None})
            stt["positions"][pid] = closed_rec; _st_save_state()
            return True
    except Exception as e:
        log.warning("reconcile reopen-apply failed (%s/%s): %s", strat, pid, e)
    return False


def _recon_call_agent(url: str) -> dict | None:
    try:
        r = requests.post(f"{url}/reconcile", timeout=5)
        r.raise_for_status()
        return r.json()
    except Exception as e:
        return {"_error": str(e)}


def _reconcile_all(ib) -> dict:
    """One full reconciliation cycle. Returns the summary dict."""
    cfg = _reconcile_cfg()
    autocorrect = cfg["autocorrect_enabled"]
    summary = {"last_run": _utcnow().isoformat(), "corrections": [], "alerts": [],
               "skips": [], "autocorrect_enabled": autocorrect}

    # ── 1. Ground truth, with hard guards ────────────────────────────────
    try:
        raw_positions = [p for p in ib.positions() if p.position != 0]
    except Exception as e:
        summary["skips"].append(f"ibkr positions() raised: {e}")
        return summary
    tracked = list(_recon_iter_all_open())
    if not raw_positions and tracked:
        summary["skips"].append(f"ibkr returned 0 positions while {len(tracked)} tracked -- suspicious, skipping")
        _oversight_log("programmer", "reconcile_skipped_bad_truth",
                       f"IBKR positions() empty while {len(tracked)} positions tracked -- cycle skipped, no mutations",
                       outcome="skipped")
        return summary

    ibkr_idx = {
        "conids": {p.contract.conId for p in raw_positions},
        "localsyms": {(p.contract.localSymbol or "").replace(" ", "").upper() for p in raw_positions},
        "stock_syms": {p.contract.symbol.upper() for p in raw_positions if p.contract.secType in ("STK", "CASH")},
        "at_keys": {_at_contract_key(p.contract) for p in raw_positions if p.contract.secType == "OPT"},
    }

    alp_idx: set = set()
    need_alpaca = any(r["venue"] == "alpaca" for r in tracked)
    if need_alpaca:
        try:
            _ac = _alp_client(_alp_load_config())
            _ap = _ac.get_all_positions()
            if not _ap and any(r["venue"] == "alpaca" for r in tracked):
                summary["skips"].append("alpaca returned 0 positions while alpaca-venue positions tracked -- skipping alpaca side")
            else:
                alp_idx = {str(getattr(x, "symbol", "")).replace(" ", "").upper() for x in _ap}
        except Exception as e:
            summary["skips"].append(f"alpaca get_all_positions failed: {e}")

    rstate = _reconcile_state_load()
    absent_counts = rstate.setdefault("absent_counts", {})

    # ── 2. External-close detection (tracked-open but broker flat) ────────
    for rec in tracked:
        key = f"{rec['strategy']}/{rec['pos_id']}"
        # alpaca-venue positions we couldn't verify (alpaca fetch failed) -> don't touch
        if rec["venue"] == "alpaca" and not alp_idx and need_alpaca:
            absent_counts.pop(key, None)
            continue
        status = _recon_present(rec, ibkr_idx, alp_idx)
        if status == "all_present":
            absent_counts.pop(key, None)
            continue
        if status == "some_present":
            absent_counts.pop(key, None)
            summary["alerts"].append(f"PARTIAL LEGS: {key} -- some legs present, some gone at broker (not auto-closing)")
            continue
        # all_absent
        absent_counts[key] = absent_counts.get(key, 0) + 1
        if absent_counts[key] < 2:
            summary["alerts"].append(f"pending externally-closed (cycle {absent_counts[key]}/2): {key}")
            continue
        if not autocorrect:
            summary["alerts"].append(f"WOULD auto-close (kill-switch off): {key} -- absent {absent_counts[key]} cycles")
            continue
        if _recon_apply_close(rec):
            absent_counts.pop(key, None)
            msg = f"reconcile: marked {key} externally closed (absent from broker {absent_counts.get(key, 2)}+ cycles)"
            summary["corrections"].append(msg)
            _oversight_log("programmer", "reconcile_autocorrect", msg,
                           rationale="Position record was open but no matching contract in IBKR/Alpaca for >=2 cycles.",
                           outcome="record moved to closed")
            _oversight_notify(f"🛠️ Reconcile auto-correct: {key} was open in records but flat at broker -- marked closed.")

    # ── 3. Phantom-close detection (record closed but broker still holds it) ──
    for strat, pid, crec in _recon_iter_all_closed():
        if not pid or not crec:
            continue
        # build a normalized record from the closed one
        cid = None
        try:
            cid = int(crec.get("conid")) if crec.get("conid") else None
        except Exception:
            cid = None
        nrec = {"strategy": strat, "pos_id": pid,
                "conids": [cid] if cid else [],
                "leg_symbols": [l.get("local_symbol") or l.get("symbol") for l in (crec.get("legs") or []) if (l.get("local_symbol") or l.get("symbol"))],
                "symbols": [crec.get("ticker")] if strat == "stock_trader" and crec.get("ticker") else [],
                "n_legs": 1}
        if not (nrec["conids"] or nrec["leg_symbols"] or nrec["symbols"]):
            continue
        status = _recon_present(nrec, ibkr_idx, alp_idx)
        if status == "all_absent":
            continue
        # still present at broker -> phantom close
        if not autocorrect:
            summary["alerts"].append(f"WOULD reopen (kill-switch off): {strat}/{pid} -- still held at broker")
            continue
        if _recon_apply_reopen(strat, pid, crec):
            msg = f"reconcile: re-opened {strat}/{pid} -- record said closed but broker still holds it (phantom close)"
            summary["corrections"].append(msg)
            _oversight_log("programmer", "reconcile_autocorrect", msg,
                           rationale="Closed record's contract is still present in IBKR/Alpaca.",
                           outcome="record moved back to open")
            _oversight_notify(f"🛠️ Reconcile auto-correct: {strat}/{pid} was marked closed but is still open at the broker -- re-opened in tracking.")

    # ── 4. Untracked broker positions (alert only) ──────────────────────
    claimed_conids = set()
    for rec in tracked:
        claimed_conids.update(rec.get("conids", []))
    # also honor _ibkr_reconcile's own claim sets by reading day-trader/spy-condor state files
    try:
        with open("day_trader_state.json") as f:
            _dt = json.load(f)
        dt_syms = {k.upper() for k in (_dt.get("positions") or {}).keys()}
    except Exception:
        dt_syms = set()
    # harami_daily_trader.py (real live stock positions, REAL money -- NOT
    # the chartexpert shadow one) runs as its own standalone process, same
    # as day-trader, so it's invisible to _recon_iter_all_open() too.
    # Claim its tracked tickers here or every real fill shows up as
    # "untracked at IBKR" (a real stock, unlike chartexpert's options).
    try:
        with open("harami_trader_state.json") as f:
            _hd = json.load(f).get("positions", {})
        harami_syms = {p["ticker"].upper() for p in _hd.values() if p.get("ticker")}
    except Exception:
        harami_syms = set()
    # Manual Trader is intentionally excluded from _recon_iter_all_open (it has
    # its own _mt_reconcile_sync), but its legs ARE tracked -- claim them here
    # by normalized localSymbol so they don't show as "untracked".
    mt_claimed_syms = set()
    for _mp in state.get("manual_trader", {}).get("positions", {}).values():
        if _mp.get("phase") != "open":
            continue
        for _lg in _mp.get("legs", []):
            _ls = str(_lg.get("local_symbol") or "").replace(" ", "").upper()
            if _ls:
                mt_claimed_syms.add(_ls)
    for p in raw_positions:
        c = p.contract
        if c.conId == _FES_MANUAL_CONID:
            continue
        if c.conId in claimed_conids:
            continue
        if c.secType in ("STK", "CASH") and c.symbol.upper() in (ibkr_idx["stock_syms"] & (dt_syms | harami_syms)):
            continue
        if c.secType == "OPT" and _at_contract_key(c) in {r.get("at_key") for r in tracked if r.get("at_key")}:
            continue
        # localSymbol claimed by any multi-leg record, or by Manual Trader?
        ls = (c.localSymbol or "").replace(" ", "").upper()
        if ls in mt_claimed_syms:
            continue
        if any(ls in {str(s).replace(' ', '').upper() for s in r.get("leg_symbols", [])} for r in tracked):
            continue
        summary["alerts"].append(f"UNTRACKED at IBKR: {c.localSymbol or c.symbol} ({c.secType}) qty={p.position} -- no strategy claims it")

    # ── 5. Standalone agents ───────────────────────────────────────────
    for name, url in (("day_trader", DAY_TRADER_AGENT_URL_RECON), ("spy_weekly_condor", SPY_CONDOR_AGENT_URL_RECON)):
        res = _recon_call_agent(url)
        if res is None or res.get("_error"):
            summary["skips"].append(f"{name} /reconcile unreachable: {res.get('_error') if res else 'no response'}")
            continue
        for corr in (res.get("corrections") or []):
            summary["corrections"].append(f"{name}: {corr}")
            _oversight_log("programmer", "reconcile_autocorrect", f"{name} agent: {corr}", outcome="agent self-corrected")
        for al in (res.get("alerts") or []):
            summary["alerts"].append(f"{name}: {al}")

    _reconcile_state_save(rstate)

    if summary["corrections"]:
        log.warning("RECONCILE: %d corrections, %d alerts, %d skips",
                    len(summary["corrections"]), len(summary["alerts"]), len(summary["skips"]))
    if summary["alerts"] and not summary["corrections"]:
        # de-dupe noisy repeat alerts: only notify on NEW untracked/partial items once per hour
        pass
    return summary


async def _reconcile_all_loop() -> None:
    """Runs the auto-correcting reconciliation cycle on the configured
    interval, weekdays 04:00-20:00 ET (covers futures + extended hours)."""
    from zoneinfo import ZoneInfo
    _ET = ZoneInfo("America/New_York")
    while True:
        cfg = _reconcile_cfg()
        await asyncio.sleep(max(30, cfg["cycle_seconds"]))
        ib = state.get("ib")
        if not ib or not ib.isConnected():
            continue
        now_et = datetime.now(_ET)
        if now_et.weekday() >= 5:
            continue
        t = now_et.strftime("%H:%M")
        if not ("04:00" <= t <= "20:00"):
            continue
        try:
            with _reconcile_lock:
                summ = await asyncio.get_event_loop().run_in_executor(None, _reconcile_all, ib)
                _reconcile_last_summary.update(summ)
        except Exception as exc:
            log.warning("RECONCILE loop: unhandled error: %s", exc, exc_info=True)


# ══════════════════════════════════════════════════════════════════════════════
# SIGNAL TRADER — auto-executes ATM calls on scanner alerts in prime windows
# ══════════════════════════════════════════════════════════════════════════════

def _sigt_log(action: str, ticker: str, detail: str) -> None:
    from zoneinfo import ZoneInfo as _ZI
    entry = {"time": datetime.now(_ZI("America/New_York")).strftime("%H:%M:%S"),
             "action": action, "ticker": ticker, "detail": detail}
    st = state["sig_trader"]
    st["decisions"].append(entry)
    st["decisions"] = st["decisions"][-200:]
    log.info("SIG_TRADER [%s] %s — %s", action, ticker, detail)


def _sigt_save_state() -> None:
    try:
        st = state["sig_trader"]
        with open(SIGT_STATE_PATH, "w") as f:
            json.dump({"config": st["config"], "positions": st["positions"],
                       "closed_today": st["closed_today"],
                       "decisions": st.get("decisions", [])[-200:]}, f, indent=2, default=str)
    except Exception as e:
        log.warning("SIG_TRADER save_state error: %s", e)


def _sigt_load_state() -> None:
    if not os.path.exists(SIGT_STATE_PATH):
        return
    try:
        from zoneinfo import ZoneInfo as _ZI
        with open(SIGT_STATE_PATH) as f:
            saved = json.load(f)
        st = state["sig_trader"]
        st["config"].update(saved.get("config", {}))
        st["decisions"] = saved.get("decisions", [])
        today     = datetime.now(_ZI("America/New_York")).strftime("%Y-%m-%d")
        today_ymd = today.replace("-", "")
        for pos_id, pos in saved.get("positions", {}).items():
            if pos.get("phase") != "open":
                continue
            entered_today  = pos.get("entry_time", "")[:10] == today
            # Keep multi-day positions (e.g. manual weekly options) as long as expiry is future
            expiry_future  = pos.get("expiry", "00000000") >= today_ymd
            if entered_today or (expiry_future and pos.get("manual", False)):
                st["positions"][pos_id] = pos
        st["closed_today"] = [p for p in saved.get("closed_today", [])
                               if p.get("entry_time", "")[:10] == today]
    except Exception as e:
        log.warning("SIG_TRADER load_state error: %s", e)


def _sigt_in_prime_window(ticker: str, signal_type: str, et_now) -> bool:
    setup = ST_SETUPS.get(ticker)
    if not setup:
        return False
    if setup["signal"] != signal_type:
        return False
    t = et_now.strftime("%H:%M")
    return setup["win_start"] <= t <= setup["win_end"]


async def _sigt_enter_trade(ib, ticker: str, signal_type: str, spot_price: float) -> None:
    """Qualify ATM call, place limit order, record position on fill."""
    from zoneinfo import ZoneInfo as _ZI
    st = state["sig_trader"]
    cfg = st["config"]
    setup = ST_SETUPS.get(ticker)
    if not setup:
        return

    pos_id = f"{ticker}_{datetime.now(_ZI('America/New_York')).strftime('%Y%m%d_%H%M%S')}"

    if len(st["positions"]) >= cfg["max_positions"]:
        _sigt_log("SKIP", ticker, f"max_positions={cfg['max_positions']} reached")
        return
    # Prevent duplicate entries for same ticker
    if any(p["ticker"] == ticker for p in st["positions"].values()):
        _sigt_log("SKIP", ticker, "already have open position")
        return

    try:
        # ── 1. Get real option chain ──────────────────────────────────────────
        expiry, real_strikes = await _evc_get_chain_params(ib, ticker)
        if not real_strikes:
            _sigt_log("SKIP", ticker, "no option chain returned")
            return

        # ── 2. Qualify the ATM call — try nearest strikes until one resolves ──
        # Strikes from chain params are real listed strikes, but IBKR qualification
        # can still fail for some (FLEX options, expired, delisted). Iterate by
        # distance from spot until we get a clean standard equity option.
        from ib_insync import Option as IbOpt
        strikes_by_dist = sorted(real_strikes, key=lambda s: abs(s - spot_price))
        contract = None
        atm_strike = None
        for candidate_strike in strikes_by_dist[:6]:
            cand = IbOpt(ticker, expiry, candidate_strike, "C", "SMART", "100", "USD")
            qualified = await ib.qualifyContractsAsync(cand)
            if qualified and not qualified[0].localSymbol.startswith("2"):
                contract  = qualified[0]
                atm_strike = candidate_strike
                break
        if contract is None:
            tried = strikes_by_dist[:6]
            _sigt_log("SKIP", ticker, f"no strike qualified near spot ${spot_price:.2f} (tried {tried})")
            return

        # ── 3. Get live quote ─────────────────────────────────────────────────
        tickers = await ib.reqTickersAsync(contract)
        await asyncio.sleep(3)
        mid = _spx_mid(tickers[0]) if tickers else 0.0
        if mid <= 0:
            _sigt_log("SKIP", ticker, f"no valid quote for {atm_strike}C")
            return

        cost = mid * 100
        if cost > cfg["budget_per_trade"]:
            _sigt_log("SKIP", ticker, f"cost ${cost:.0f} > budget ${cfg['budget_per_trade']}")
            return

        entry_price = round(mid + 0.05, 2)

        # ── 4. Place limit order ──────────────────────────────────────────────
        order = LimitOrder("BUY", 1, entry_price, tif="DAY")
        trade = ib.placeOrder(contract, order)
        _sigt_log("ORDERING", ticker, f"{atm_strike}C {expiry} @ ${entry_price:.2f} (mid ${mid:.2f})")

        # ── 5. Wait for fill (up to 30s) ──────────────────────────────────────
        for _ in range(30):
            await asyncio.sleep(1)
            if trade.orderStatus.status in ("Filled", "Submitted"):
                break
        if trade.orderStatus.status != "Filled":
            ib.cancelOrder(order)
            _sigt_log("SKIP", ticker, f"no fill in 30s (status={trade.orderStatus.status})")
            return

        fill_price = trade.orderStatus.avgFillPrice or entry_price
        now_utc = _utcnow()
        deadline = now_utc + timedelta(minutes=setup["hold_mins"])
        target_spot = round(spot_price * (1 + setup["target_pct"] / 100), 2)
        stop_spot   = round(spot_price * (1 - setup["stop_pct"]   / 100), 2)

        pos = {
            "pos_id":             pos_id,
            "ticker":             ticker,
            "signal_type":        signal_type,
            "entry_time":         now_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "deadline":           deadline.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "spot_at_entry":      round(spot_price, 2),
            "target_spot":        target_spot,
            "stop_spot":          stop_spot,
            "strike":             atm_strike,
            "expiry":             expiry,
            "conid":              contract.conId,
            "qty":                1,
            "option_entry_price": round(fill_price, 2),
            "order_id":           trade.order.orderId,
            "phase":              "open",
            "live_pnl":           0.0,
        }
        st["positions"][pos_id] = pos
        _sigt_log("ENTERED", ticker,
                f"{atm_strike}C {expiry} fill=${fill_price:.2f} spot=${spot_price:.2f} "
                f"tgt=${target_spot:.2f} stp=${stop_spot:.2f} dl={deadline.strftime('%H:%MZ')}")

        # ── 6. Journal insert ──────────────────────────────────────────────────
        # Real trade_journal schema -- the pre-2026-09-10 version referenced
        # columns (direction, entry_date, status) that don't exist, so every
        # Signal Trader journal write silently failed and no Signal Trader
        # trade ever reached the P&L dashboard. An open trade = closed_at IS NULL.
        try:
            con = sqlite3.connect(JOURNAL_DB_PATH)
            con.execute("""INSERT INTO trade_journal
                (opened_at, ticker, expiry, strike, right, action, qty, entry_price,
                 spot_price, strategy_type, is_paper, notes)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
                (_utcnow().isoformat(), ticker, expiry, atm_strike, "C", "BUY", 1, fill_price,
                 spot_price, "signal_trader", _is_paper(),
                 f"strike={atm_strike} expiry={expiry} signal={signal_type}"))
            con.commit()
            con.close()
        except Exception as je:
            log.warning("SIG_TRADER journal insert error: %s", je)

        _sigt_save_state()

    except Exception as e:
        _sigt_log("ERROR", ticker, f"_sigt_enter_trade: {e}")
        log.exception("SIG_TRADER _sigt_enter_trade error for %s", ticker)


async def _sigt_enter_future_trade(ib, ticker: str = "MNQ", qty: Optional[int] = None) -> dict:
    """MNQ futures entry -- long only, manual/API-triggered (no breakout-
    scanner wiring in this version, see MNQ_FUTURES_CONFIG's own comment).
    Real margin-aware sizing via ib.whatIfOrderAsync (SPAN margin moves
    with volatility -- more honest than a hardcoded guess), gated through
    the SAME cro_cfo_capital_budget every other strategy already uses.
    Returns a result dict rather than logging-and-returning-None like
    _sigt_enter_trade, so the manual-trigger endpoint can report exactly
    why an attempt was skipped."""
    if ticker != "MNQ":
        return {"ok": False, "reason": "only MNQ supported in this version"}
    st = state["sig_trader"]
    cfg = MNQ_FUTURES_CONFIG
    qty = qty or cfg["max_qty"]
    if qty > cfg["max_qty"]:
        return {"ok": False, "reason": f"qty {qty} exceeds max_qty={cfg['max_qty']} -- raise max_qty only after a clean live round-trip"}
    if any(p.get("ticker") == ticker and p.get("instrument_type") == "future" for p in st["positions"].values()):
        _sigt_log("SKIP", ticker, "already have open future position")
        return {"ok": False, "reason": "already have an open MNQ position"}

    try:
        contract = await _resolve_mnq_front_month(ib)
        await ib.qualifyContractsAsync(contract)

        tickers = await ib.reqTickersAsync(contract)
        await asyncio.sleep(2)
        spot = _spx_mid(tickers[0]) if tickers else 0.0
        if spot <= 0:
            _sigt_log("SKIP", ticker, "no valid live quote for front-month MNQ")
            return {"ok": False, "reason": "no valid live quote"}

        # ── Real margin-aware capital gate (same pattern every other strategy uses) ──
        # whatIfOrderAsync comes back as an empty list instead of a real
        # OrderState if the probe order's `tif` isn't explicitly set --
        # confirmed 2026-09-09: MarketOrder("BUY", qty) alone silently
        # produces an unusable whatIf response; setting .tif = "DAY"
        # explicitly is what actually gets a real margin figure back. Fail
        # closed with a clear reason rather than crashing on a missing
        # attribute if this ever regresses.
        probe_order = MarketOrder("BUY", qty)
        probe_order.tif = "DAY"
        order_state = await ib.whatIfOrderAsync(contract, probe_order)
        if not order_state or not hasattr(order_state, "initMarginChange"):
            _sigt_log("SKIP", ticker, f"whatIfOrder returned no usable margin data ({order_state!r}) -- "
                                        f"check real-time CME market data subscription")
            return {"ok": False, "reason": "whatIfOrder returned no usable margin data -- "
                                             "check real-time CME market data subscription at IBKR"}
        margin_per_position = float(order_state.initMarginChange or 0)
        if margin_per_position <= 0:
            _sigt_log("SKIP", ticker, f"whatIfOrder returned no real margin figure ({order_state.initMarginChange})")
            return {"ok": False, "reason": "could not determine real margin requirement"}

        budget = _cro_cfo_capital_budget(ib)
        if margin_per_position > budget["per_strategy_cap"]:
            _sigt_log("SKIP", ticker, f"margin ${margin_per_position:.0f} > per-strategy cap ${budget['per_strategy_cap']:.0f}")
            return {"ok": False, "reason": f"margin ${margin_per_position:.0f} exceeds per-strategy cap ${budget['per_strategy_cap']:.0f}"}
        if margin_per_position > budget["headroom"]:
            _sigt_log("SKIP", ticker, f"margin ${margin_per_position:.0f} > portfolio headroom ${budget['headroom']:.0f}")
            return {"ok": False, "reason": f"margin ${margin_per_position:.0f} exceeds portfolio headroom ${budget['headroom']:.0f}"}

        entry_price = round(spot + 0.25, 2)  # small favorable-side offset, same spirit as the options entry
        order = LimitOrder("BUY", qty, entry_price, tif="DAY")
        trade = ib.placeOrder(contract, order)
        _sigt_log("ORDERING", ticker, f"{contract.lastTradeDateOrContractMonth} x{qty} @ ${entry_price:.2f} "
                                        f"(spot ${spot:.2f}, real margin ${margin_per_position:.0f}/contract)")

        for _ in range(30):
            await asyncio.sleep(1)
            if trade.orderStatus.status == "Filled":
                break
        if trade.orderStatus.status != "Filled":
            ib.cancelOrder(order)
            _sigt_log("SKIP", ticker, f"no fill in 30s (status={trade.orderStatus.status})")
            return {"ok": False, "reason": f"no fill in 30s (status={trade.orderStatus.status})"}

        fill_price = trade.orderStatus.avgFillPrice or entry_price
        now_utc = _utcnow()
        deadline = now_utc + timedelta(minutes=cfg["hold_mins"])
        pos_id = f"{ticker}_{datetime.now(timezone(timedelta(hours=-4))).strftime('%Y%m%d_%H%M%S')}"

        pos = {
            "pos_id":            pos_id,
            "ticker":            ticker,
            "instrument_type":   "future",
            "signal_type":       "MANUAL",
            "entry_time":        now_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "deadline":          deadline.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "spot_at_entry":     round(fill_price, 2),
            "target_spot":       round(fill_price * (1 + cfg["target_pct"] / 100), 2),
            "stop_spot":         round(fill_price * (1 - cfg["stop_pct"] / 100), 2),
            "expiry":            contract.lastTradeDateOrContractMonth,
            "conid":             contract.conId,
            "qty":               qty,
            "future_entry_price": round(fill_price, 2),
            "margin_per_contract": round(margin_per_position, 2),
            "order_id":          trade.order.orderId,
            "phase":             "open",
            "live_pnl":          0.0,
        }
        st["positions"][pos_id] = pos
        _sigt_log("ENTERED", ticker,
                  f"x{qty} @ ${fill_price:.2f} tgt=${pos['target_spot']:.2f} stp=${pos['stop_spot']:.2f} "
                  f"dl={deadline.strftime('%H:%MZ')} margin=${margin_per_position:.0f}/contract")

        try:
            con = sqlite3.connect(JOURNAL_DB_PATH)
            con.execute("""INSERT INTO trade_journal
                (opened_at, ticker, expiry, action, qty, entry_price,
                 spot_price, strategy_type, is_paper, notes)
                VALUES (?,?,?,?,?,?,?,?,?,?)""",
                (_utcnow().isoformat(), ticker, contract.lastTradeDateOrContractMonth, "BUY", qty, fill_price,
                 fill_price, "signal_trader_futures", _is_paper(),
                 f"MNQ front-month margin=${margin_per_position:.0f}/contract"))
            con.commit()
            con.close()
        except Exception as je:
            log.warning("SIG_TRADER futures journal insert error: %s", je)

        _sigt_save_state()
        return {"ok": True, "pos_id": pos_id, "fill_price": fill_price, "qty": qty,
                "margin_per_contract": margin_per_position}

    except Exception as e:
        _sigt_log("ERROR", ticker, f"_sigt_enter_future_trade: {e}")
        log.exception("SIG_TRADER _sigt_enter_future_trade error for %s", ticker)
        return {"ok": False, "reason": str(e)}


def _sigt_ibkr_holds(ib, conid) -> bool | None:
    """True/False if conid is/ isn't a live IBKR position; None if we can't tell."""
    if not conid:
        return None
    try:
        return any(p.contract.conId == conid and p.position != 0 for p in ib.positions())
    except Exception:
        return None


async def _sigt_recover_close_from_fills(ib, pos: dict, pos_id: str, reason: str,
                                         is_future: bool) -> bool:
    """The record is open/closing but IBKR no longer holds the contract -- the
    SELL already went through (or it was closed out of band) and the code was
    cut off before recording. Reconstruct the exit from the most recent SLD
    execution for this conid and finalize. Returns True if it finalized (so
    the caller must NOT place another SELL). Falls back to a null-P&L close if
    no fill can be found -- either way, never sells."""
    st = state["sig_trader"]
    conid = pos.get("conid")
    ticker = pos.get("ticker", "?")
    px = None
    try:
        for f in reversed(ib.fills()):
            if f.contract.conId == conid and f.execution.side == "SLD":
                px = float(f.execution.price)
                break
        if px is None:
            from ib_insync import ExecutionFilter
            execs = await ib.reqExecutionsAsync(ExecutionFilter())
            for f in reversed(execs):
                if f.contract.conId == conid and f.execution.side == "SLD":
                    px = float(f.execution.price)
                    break
    except Exception as e:
        log.warning("SIG_TRADER recover-from-fills lookup failed %s: %s", pos_id, e)

    now_z = _utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
    if px and px > 0:
        if is_future:
            pnl = round((px - pos["future_entry_price"]) * 2 * pos.get("qty", 1), 2)
            strat_type = "signal_trader_futures"
        else:
            pnl = round((px - pos["option_entry_price"]) * 100 * pos.get("qty", 1), 2)
            strat_type = "signal_trader"
        exit_reason = f"{reason}_recovered"
        pos.update({"phase": "closed", "exit_price": round(px, 2), "exit_reason": exit_reason,
                    "pnl": pnl, "closed_at": now_z})
        _sigt_log("CLOSED", ticker,
                  f"{exit_reason} close=${px:.2f} pnl=${pnl:+.2f} (SELL already done at IBKR; recovered from fills)")
    else:
        pnl = None
        strat_type = "signal_trader_futures" if is_future else "signal_trader"
        exit_reason = f"{reason}_broker_flat"
        pos.update({"phase": "closed", "exit_price": None, "exit_reason": exit_reason,
                    "pnl": None, "closed_at": now_z})
        _sigt_log("CLOSED", ticker,
                  f"{exit_reason}: broker already flat, no SLD fill found -- marked closed, null P&L (did NOT sell)")

    st["closed_today"].append(pos)
    st["positions"].pop(pos_id, None)
    try:
        con = sqlite3.connect(JOURNAL_DB_PATH)
        con.execute("""UPDATE trade_journal SET
            closed_at=?, exit_price=?, pnl=?, win=?, exit_reason=?, notes=COALESCE(notes,'')||?
            WHERE id = (SELECT id FROM trade_journal
                        WHERE ticker=? AND strategy_type=? AND closed_at IS NULL
                        ORDER BY id DESC LIMIT 1)""",
            (_utcnow().isoformat(), px if (px and px > 0) else None, pnl,
             1 if (pnl or 0) > 0 else 0, exit_reason,
             f" | exit={exit_reason} pnl={'' if pnl is None else format(pnl, '+.2f')}",
             ticker, strat_type))
        con.commit(); con.close()
    except Exception as je:
        log.warning("SIG_TRADER recover journal update error: %s", je)
    _sigt_save_state()
    return True


async def _sigt_close_future_position(ib, pos_id: str, reason: str) -> None:
    """Close an open MNQ future position -- mirrors _sigt_close_position's
    limit-then-escalate pattern, but against the future's own live price
    directly (no separate spot-vs-option-premium translation needed)."""
    st = state["sig_trader"]
    pos = st["positions"].get(pos_id)
    if not pos or pos.get("phase") not in ("open", "closing"):
        return

    # If IBKR no longer holds this contract, the SELL already happened --
    # finalize from the fill record instead of placing a duplicate SELL that
    # would open a naked short. Also unsticks a position left at phase
    # "closing" by an interrupted prior close.
    if _sigt_ibkr_holds(ib, pos.get("conid")) is False:
        await _sigt_recover_close_from_fills(ib, pos, pos_id, reason, is_future=True)
        return

    pos["phase"] = "closing"
    ticker = pos["ticker"]
    qty = pos["qty"]

    try:
        contract = Future(ticker, pos["expiry"], "CME", currency="USD")
        contract.conId = pos["conid"]
        qualified = await ib.qualifyContractsAsync(contract)
        if qualified:
            contract = qualified[0]

        tickers = await ib.reqTickersAsync(contract)
        await asyncio.sleep(2)
        mid = _spx_mid(tickers[0]) if tickers else 0.0
        lmt = max(0.25, round(mid - 0.25, 2)) if mid > 0 else None

        if lmt:
            order = LimitOrder("SELL", qty, lmt, tif="DAY")
        else:
            order = MarketOrder("SELL", qty)

        trade = ib.placeOrder(contract, order)
        for _ in range(15):
            await asyncio.sleep(1)
            if trade.orderStatus.status == "Filled":
                break
        if trade.orderStatus.status != "Filled":
            ib.cancelOrder(order)
            mkt = MarketOrder("SELL", qty)
            mkt.tif = "DAY"
            trade = ib.placeOrder(contract, mkt)
            for _ in range(15):
                await asyncio.sleep(1)
                if trade.orderStatus.status == "Filled":
                    break

        # Fill verification -- same rule as _sigt_close_position: never mark
        # closed on an unfilled SELL (would leave a real open future position
        # untracked). Revert to "open" and let the monitor retry.
        filled = trade.orderStatus.status == "Filled" and (trade.orderStatus.avgFillPrice or 0) > 0
        if not filled:
            pos["phase"] = "open"
            _sigt_log("CLOSE_FAILED", ticker,
                      f"{reason}: SELL did not fill (status={trade.orderStatus.status}) -- position still OPEN, will retry")
            _sigt_save_state()
            return

        close_price = trade.orderStatus.avgFillPrice
        pnl = round((close_price - pos["future_entry_price"]) * 2 * qty, 2)  # MNQ multiplier = $2/index point
        pos["phase"] = "closed"
        pos["exit_price"] = round(close_price, 2)
        pos["exit_reason"] = reason
        pos["pnl"] = pnl
        pos["closed_at"] = _utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

        st["closed_today"].append(pos)
        del st["positions"][pos_id]

        _sigt_log("CLOSED", ticker, f"{reason} close=${close_price:.2f} pnl=${pnl:+.2f}")

        try:
            con = sqlite3.connect(JOURNAL_DB_PATH)
            con.execute("""UPDATE trade_journal SET
                closed_at=?, exit_price=?, pnl=?, win=?, exit_reason=?, notes=COALESCE(notes,'')||?
                WHERE id = (SELECT id FROM trade_journal
                            WHERE ticker=? AND strategy_type='signal_trader_futures' AND closed_at IS NULL
                            ORDER BY id DESC LIMIT 1)""",
                (_utcnow().isoformat(), close_price, pnl, 1 if pnl > 0 else 0, reason,
                 f" | exit={reason} pnl={pnl:+.2f}", ticker))
            con.commit()
            con.close()
        except Exception as je:
            log.warning("SIG_TRADER futures journal update error: %s", je)

        _sigt_save_state()

    except Exception as e:
        pos["phase"] = "open"  # revert so monitor can retry
        _sigt_log("ERROR", ticker, f"_sigt_close_future_position {reason}: {e}")
        log.exception("SIG_TRADER _sigt_close_future_position error %s %s", pos_id, reason)


async def _sigt_close_position(ib, pos_id: str, reason: str) -> None:
    """Close an open call position at market and record the result."""
    st = state["sig_trader"]
    pos = st["positions"].get(pos_id)
    if not pos or pos.get("phase") not in ("open", "closing"):
        return

    # If IBKR no longer holds this contract, the SELL already happened (or it
    # was closed out of band) -- finalize from the fill record instead of
    # placing a duplicate SELL that would open a naked short call. Also
    # unsticks a position left at phase "closing" by an interrupted prior
    # close (e.g. CVX 215C on 2026-09-10: SELL filled at $2.65 but the coro
    # was cut off before recording, leaving it stuck and invisible).
    if _sigt_ibkr_holds(ib, pos.get("conid")) is False:
        await _sigt_recover_close_from_fills(ib, pos, pos_id, reason, is_future=False)
        return

    pos["phase"] = "closing"
    ticker = pos["ticker"]

    try:
        from ib_insync import Option as IbOpt
        contract = IbOpt(ticker, pos["expiry"], pos["strike"], "C", "SMART", "100", "USD")
        contract.conId = pos["conid"]
        qualified = await ib.qualifyContractsAsync(contract)
        if qualified:
            contract = qualified[0]

        # Aggressive limit at mid — fall back to market
        close_price = 0.0
        tickers = await ib.reqTickersAsync(contract)
        await asyncio.sleep(2)
        mid = _spx_mid(tickers[0]) if tickers else 0.0
        lmt = max(0.01, round(mid - 0.05, 2)) if mid > 0 else None

        if lmt:
            order = LimitOrder("SELL", 1, lmt, tif="DAY")
        else:
            order = MarketOrder("SELL", 1)
            order.tif = "DAY"   # unset tif -> IBKR rejects with Error 10349 (confirmed 2026-09-10)

        trade = ib.placeOrder(contract, order)
        for _ in range(15):
            await asyncio.sleep(1)
            if trade.orderStatus.status == "Filled":
                break
        if trade.orderStatus.status != "Filled":
            # Escalate to market
            ib.cancelOrder(order)
            mkt = MarketOrder("SELL", 1)
            mkt.tif = "DAY"
            trade = ib.placeOrder(contract, mkt)
            for _ in range(15):
                await asyncio.sleep(1)
                if trade.orderStatus.status == "Filled":
                    break

        # ── Fill verification: do NOT mark closed unless the SELL actually
        # filled. Pre-2026-09-10 this fell straight through to a phantom
        # close (avgFillPrice=0 -> `or mid` -> a fake exit price), deleting
        # the position from tracking while it was still real at IBKR --
        # exactly what happened to CVX 215C on 2026-09-09. If it didn't
        # fill (pre-market, halted, no quote, rejected), revert phase to
        # "open" and let the monitor retry next cycle.
        filled = trade.orderStatus.status == "Filled" and (trade.orderStatus.avgFillPrice or 0) > 0
        if not filled:
            pos["phase"] = "open"
            _sigt_log("CLOSE_FAILED", ticker,
                      f"{reason}: SELL did not fill (status={trade.orderStatus.status}, "
                      f"avgFill={trade.orderStatus.avgFillPrice}) -- position still OPEN, will retry")
            _sigt_save_state()
            return

        close_price = trade.orderStatus.avgFillPrice
        pnl = round((close_price - pos["option_entry_price"]) * 100, 2)
        pos["phase"] = "closed"
        pos["exit_price"] = round(close_price, 2)
        pos["exit_reason"] = reason
        pos["pnl"] = pnl
        pos["closed_at"] = _utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

        st["closed_today"].append(pos)
        del st["positions"][pos_id]

        _sigt_log("CLOSED", ticker, f"{reason} close=${close_price:.2f} pnl=${pnl:+.2f}")

        # ── Update journal ──────────────────────────────────────────────────
        try:
            con = sqlite3.connect(JOURNAL_DB_PATH)
            con.execute("""UPDATE trade_journal SET
                closed_at=?, exit_price=?, pnl=?, win=?, exit_reason=?, notes=COALESCE(notes,'')||?
                WHERE id = (SELECT id FROM trade_journal
                            WHERE ticker=? AND strategy_type='signal_trader' AND closed_at IS NULL
                            ORDER BY id DESC LIMIT 1)""",
                (_utcnow().isoformat(), close_price, pnl, 1 if pnl > 0 else 0, reason,
                 f" | exit={reason} pnl={pnl:+.2f}", ticker))
            con.commit()
            con.close()
        except Exception as je:
            log.warning("SIG_TRADER journal update error: %s", je)

        _sigt_save_state()

    except Exception as e:
        pos["phase"] = "open"  # revert so monitor can retry
        _sigt_log("ERROR", ticker, f"_sigt_close_position {reason}: {e}")
        log.exception("SIG_TRADER _sigt_close_position error %s %s", pos_id, reason)


async def _sigt_monitor_coro(ib) -> None:
    """Check open positions against target/stop/deadline; update live P&L.
    Dispatches on instrument_type -- options positions get the original
    stock-spot + option-mid treatment unchanged; MNQ future positions get
    their own live price checked directly (the future IS the tradable
    instrument, no separate spot-vs-premium translation needed)."""
    st = state["sig_trader"]
    if not st["positions"]:
        return

    open_positions = {pid: p for pid, p in st["positions"].items()
                      if p.get("phase") == "open"}
    if not open_positions:
        return

    option_positions = {pid: p for pid, p in open_positions.items()
                         if p.get("instrument_type") != "future"}
    future_positions = {pid: p for pid, p in open_positions.items()
                         if p.get("instrument_type") == "future"}

    # ── 1. Batch-fetch live spot prices (options positions only) ─────────────
    from ib_insync import Stock as IbStock, Option as IbOpt
    tickers_needed = list({p["ticker"] for p in option_positions.values()})
    spot_map: dict = {}
    if tickers_needed:
        spot_contracts = [IbStock(tk, "SMART", "USD") for tk in tickers_needed]
        spot_tickers = await ib.reqTickersAsync(*spot_contracts)
        await asyncio.sleep(2)
        for td in spot_tickers:
            sym = getattr(td.contract, "symbol", None)
            if sym:
                px = _spx_safe_px(td.last) or _spx_safe_px(td.close)
                if px > 0:
                    spot_map[sym] = px

    # ── 2. Fetch live option mids for all open option positions ──────────────
    opt_contracts = []
    pid_to_opt: dict = {}  # pos_id → index in opt_contracts
    for pos_id, pos in option_positions.items():
        if not pos.get("conid"):
            continue
        c = IbOpt(pos["ticker"], pos["expiry"], pos["strike"], "C", "SMART", "100", "USD")
        c.conId = pos["conid"]
        pid_to_opt[pos_id] = len(opt_contracts)
        opt_contracts.append(c)

    opt_mids: dict = {}  # pos_id → current mid price
    if opt_contracts:
        try:
            opt_tickers = await ib.reqTickersAsync(*opt_contracts)
            await asyncio.sleep(3)
            for pos_id, idx in pid_to_opt.items():
                if idx < len(opt_tickers):
                    mid = _spx_mid(opt_tickers[idx])
                    if mid > 0:
                        opt_mids[pos_id] = mid
        except Exception as e:
            log.warning("SIG_TRADER option quote error: %s", e)

    # ── 2b. Fetch live future prices for all open future positions ───────────
    future_prices: dict = {}  # pos_id → current live price
    if future_positions:
        fut_contracts = []
        pid_to_fut: dict = {}
        for pos_id, pos in future_positions.items():
            c = Future(pos["ticker"], pos["expiry"], "CME", currency="USD")
            c.conId = pos["conid"]
            pid_to_fut[pos_id] = len(fut_contracts)
            fut_contracts.append(c)
        try:
            fut_tickers = await ib.reqTickersAsync(*fut_contracts)
            await asyncio.sleep(2)
            for pos_id, idx in pid_to_fut.items():
                if idx < len(fut_tickers):
                    px = _spx_mid(fut_tickers[idx])
                    if px > 0:
                        future_prices[pos_id] = px
        except Exception as e:
            log.warning("SIG_TRADER future quote error: %s", e)

    # ── 3. Apply target / stop / deadline; update live P&L (options) ─────────
    now_utc = _utcnow()
    for pos_id, pos in list(option_positions.items()):
        tk = pos["ticker"]
        spot = spot_map.get(tk)

        # Live P&L from actual option mid (falls back to spot-based estimate)
        opt_mid = opt_mids.get(pos_id)
        if opt_mid is not None:
            pos["live_pnl"] = round((opt_mid - pos["option_entry_price"]) * 100, 2)
            pos["option_live_mid"] = round(opt_mid, 2)
        elif spot:
            # Rough delta-1 approximation until option quote arrives
            pos["live_pnl"] = round((spot - pos["spot_at_entry"]) * 100, 2)

        if not spot:
            continue

        # _parse_utc, not raw strptime -- strptime with a literal "Z" in the
        # format string does NOT attach real tzinfo, producing a naive
        # datetime that throws "can't compare offset-naive and
        # offset-aware datetimes" against _utcnow()'s aware result the
        # moment a position's deadline is actually reached (confirmed live
        # 2026-09-09: a real CVX position sat unclosed 20+ min past its
        # deadline because of exactly this -- pre-existing bug, not
        # introduced by the futures work, but copied into it before this
        # fix since the pattern was copied from the original code).
        deadline = _parse_utc(pos["deadline"])

        if spot >= pos["target_spot"]:
            await _sigt_close_position(ib, pos_id, "target_hit")
        elif spot <= pos["stop_spot"]:
            await _sigt_close_position(ib, pos_id, "stop_hit")
        elif now_utc >= deadline:
            await _sigt_close_position(ib, pos_id, "time_exit")

    # ── 3b. Apply target / stop / deadline; update live P&L (futures) ────────
    for pos_id, pos in list(future_positions.items()):
        price = future_prices.get(pos_id)
        if price:
            pos["live_pnl"] = round((price - pos["future_entry_price"]) * 2 * pos["qty"], 2)
            pos["future_live_price"] = round(price, 2)
        if not price:
            continue

        # _parse_utc, not raw strptime -- strptime with a literal "Z" in the
        # format string does NOT attach real tzinfo, producing a naive
        # datetime that throws "can't compare offset-naive and
        # offset-aware datetimes" against _utcnow()'s aware result the
        # moment a position's deadline is actually reached (confirmed live
        # 2026-09-09: a real CVX position sat unclosed 20+ min past its
        # deadline because of exactly this -- pre-existing bug, not
        # introduced by the futures work, but copied into it before this
        # fix since the pattern was copied from the original code).
        deadline = _parse_utc(pos["deadline"])

        if price >= pos["target_spot"]:
            await _sigt_close_future_position(ib, pos_id, "target_hit")
        elif price <= pos["stop_spot"]:
            await _sigt_close_future_position(ib, pos_id, "stop_hit")
        elif now_utc >= deadline:
            await _sigt_close_future_position(ib, pos_id, "time_exit")

    _sigt_save_state()


async def _sigt_monitor_loop() -> None:
    """30-second background loop: checks open Signal Trader positions."""
    while True:
        await asyncio.sleep(30)
        try:
            st = state["sig_trader"]
            if not st["enabled"] or not st["positions"]:
                continue
            ib = state.get("ib")
            if not ib or not ib.isConnected():
                continue
            loop = state.get("streaming_loop")
            if loop:
                loop.run_in_executor(
                    None,
                    lambda: _run_in_streaming_loop(_sigt_monitor_coro(ib), timeout=25)
                )
        except Exception as e:
            log.warning("_sigt_monitor_loop error: %s", e)


def _sigt_maybe_enter(ticker: str, signal_type: str, spot: float,
                      prime_window: Optional[bool],
                      vwap_favorable: Optional[bool] = None,
                      above_sma50: Optional[bool] = None) -> None:
    """Called from /watchlist/alert — fires trade entry if conditions are met."""
    from zoneinfo import ZoneInfo as _ZI
    st  = state["sig_trader"]
    cfg = st["config"]
    if not st["enabled"]:
        return
    if ticker not in ST_SETUPS:
        return
    if len(st["positions"]) >= cfg["max_positions"]:
        return

    # Use scanner-provided prime_window flag if available, else compute locally
    if prime_window is None:
        et_now = datetime.now(_ZI("America/New_York"))
        in_window = _sigt_in_prime_window(ticker, signal_type, et_now)
    else:
        in_window = prime_window and (ST_SETUPS[ticker]["signal"] == signal_type)

    if not in_window:
        return

    # ── VWAP filter (per-ticker 5yr backtest edge) ────────────────────────
    # None = ticker not in VWAP_RULES or data unavailable → pass through
    # False = position is against the historical edge → skip
    if cfg.get("use_vwap_filter", True) and vwap_favorable is False:
        _sigt_log("SKIP", ticker, "VWAP unfavorable — backtest edge against this position")
        return

    # ── SMA50 filter (trend alignment for call entries) ───────────────────
    # Two-level gate: global toggle AND per-ticker flag in ST_SETUPS.
    # sma50_filter=False on a ticker means SMA50 effect wasn't confirmed in backtest → skip gate.
    # None data = pass through in all cases.
    ticker_sma50 = ST_SETUPS.get(ticker, {}).get("sma50_filter", True)
    if cfg.get("use_sma50_filter", True) and ticker_sma50 and above_sma50 is False:
        _sigt_log("SKIP", ticker, "below SMA50 — no call entry against trend")
        return

    ib = state.get("ib")
    if not ib or not ib.isConnected():
        _sigt_log("SKIP", ticker, "IB not connected")
        return

    loop = state.get("streaming_loop")
    if not loop:
        return

    vwap_tag = ("VWAP✓" if vwap_favorable else ("VWAP?" if vwap_favorable is None else ""))
    sma_tag  = ("SMA50✓" if above_sma50  else ("SMA50?" if above_sma50  is None else ""))
    filters  = "  ".join(t for t in [vwap_tag, sma_tag] if t)
    _sigt_log("TRIGGER", ticker,
              f"{signal_type} in prime window @ ${spot:.2f}  {filters} — entering")
    loop.run_in_executor(
        None,
        lambda: _run_in_streaming_loop(_sigt_enter_trade(ib, ticker, signal_type, spot), timeout=60)
    )


# ── Signal Trader API endpoints ────────────────────────────────────────────

class STConfigRequest(BaseModel):
    max_positions:     Optional[int]   = None
    dte_max:           Optional[int]   = None
    budget_per_trade:  Optional[float] = None
    use_vwap_filter:   Optional[bool]  = None
    use_sma50_filter:  Optional[bool]  = None


@app.get("/signal-trader/status")
def st_status():
    st = state["sig_trader"]
    return {
        "enabled":      st["enabled"],
        "config":       st["config"],
        "setups":       ST_SETUPS,
        "positions":    st["positions"],
        "closed_today": st["closed_today"],
        "decisions":    st["decisions"][-50:],
    }


@app.post("/signal-trader/enable")
def st_enable(body: dict):
    enabled = bool(body.get("enabled", False))
    state["sig_trader"]["enabled"] = enabled
    _sigt_save_state()
    return {"enabled": enabled}


@app.post("/signal-trader/config")
def st_config(req: STConfigRequest):
    cfg = state["sig_trader"]["config"]
    updates = req.model_dump(exclude_none=True)
    cfg.update(updates)
    _sigt_log("CONFIG", "system", f"updated: {updates}")
    _sigt_save_state()
    return {"config": cfg}


@app.post("/signal-trader/close/{pos_id}")
async def st_close(pos_id: str):
    st = state["sig_trader"]
    if pos_id not in st["positions"]:
        raise HTTPException(404, f"{pos_id} not found in open positions")
    ib = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IBKR not connected")
    is_future = st["positions"][pos_id].get("instrument_type") == "future"
    close_fn = _sigt_close_future_position if is_future else _sigt_close_position
    _sigt_log("MANUAL_CLOSE", st["positions"][pos_id]["ticker"], f"manual close {pos_id}")
    loop = asyncio.get_event_loop()
    await loop.run_in_executor(
        None,
        lambda: _run_in_streaming_loop(close_fn(ib, pos_id, "manual_close"), timeout=60)
    )
    return {"status": "closing", "pos_id": pos_id}


class MNQEnterRequest(BaseModel):
    qty: Optional[int] = None


@app.post("/signal-trader/mnq/enter")
async def st_mnq_enter(req: MNQEnterRequest):
    """Manual/API-triggered MNQ futures entry (2026-09-09) -- no breakout-
    scanner wiring in this version, per confirmed scope. Real margin-aware
    sizing via ib.whatIfOrderAsync, gated through the same cro_cfo_capital_
    budget every other strategy uses. See MNQ_FUTURES_CONFIG's own comment
    for why this is long-only and manual-trigger-first."""
    st = state["sig_trader"]
    if not st["enabled"]:
        raise HTTPException(400, "Signal Trader is disabled -- enable it first")
    ib = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IBKR not connected")
    loop = asyncio.get_event_loop()
    result = await loop.run_in_executor(
        None,
        lambda: _run_in_streaming_loop(_sigt_enter_future_trade(ib, "MNQ", req.qty), timeout=60)
    )
    if not result.get("ok"):
        raise HTTPException(400, result.get("reason", "entry failed"))
    return result


@app.post("/signal-trader/positions")
def st_inject_position(body: dict):
    """Inject a manually-placed option position into Signal Trader tracking."""
    required = {"ticker", "strike", "expiry", "option_entry_price", "conid"}
    missing  = required - body.keys()
    if missing:
        raise HTTPException(400, f"Missing required fields: {missing}")
    from zoneinfo import ZoneInfo as _ZI
    st    = state["sig_trader"]
    now   = datetime.now(_ZI("America/New_York"))
    ticker = body["ticker"]
    setup  = ST_SETUPS.get(ticker, {})
    pos_id = body.get("pos_id") or f"{ticker}_{now.strftime('%Y%m%d_%H%M%S')}_manual"
    pos = {
        "pos_id":              pos_id,
        "ticker":              ticker,
        "signal_type":         body.get("signal_type", "MANUAL"),
        "manual":              True,
        "entry_time":          body.get("entry_time", now.isoformat()),
        "deadline":            body.get("deadline", f"{body['expiry'][:4]}-{body['expiry'][4:6]}-{body['expiry'][6:8]}T20:00:00"),
        "spot_at_entry":       body.get("spot_at_entry", 0.0),
        "target_spot":         body.get("target_spot", 0.0),
        "stop_spot":           body.get("stop_spot", 0.0),
        "strike":              float(body["strike"]),
        "expiry":              body["expiry"],
        "conid":               body["conid"],
        "qty":                 body.get("qty", 1),
        "option_entry_price":  float(body["option_entry_price"]),
        "order_id":            body.get("order_id"),
        "phase":               "open",
        "live_pnl":            0.0,
    }
    st["positions"][pos_id] = pos
    _sigt_log("MANUAL_INJECT", ticker,
              f"strike={pos['strike']} expiry={pos['expiry']} cost=${pos['option_entry_price']:.2f}")
    _sigt_save_state()
    return {"status": "injected", "pos_id": pos_id, "position": pos}


@app.get("/signal-trader/history")
def st_history(limit: int = 50):
    try:
        con = sqlite3.connect(JOURNAL_DB_PATH)
        con.row_factory = sqlite3.Row
        rows = con.execute("""
            SELECT * FROM trade_journal WHERE strategy_type='signal_trader'
            ORDER BY rowid DESC LIMIT ?""", (limit,)).fetchall()
        con.close()
        return {"trades": [dict(r) for r in rows]}
    except Exception as e:
        return {"trades": [], "error": str(e)}


# ══════════════════════════════════════════════════════════════════════════════
# MANUAL TRADER — track, monitor, and auto-exit any manually-placed position
# Supports: iron condors, vertical spreads, naked options, stocks (any legs)
# P&L formula: sum( sign × (current_mid − fill_price) × qty × multiplier )
#   BUY leg sign=+1 (profits when price rises)
#   SELL leg sign=−1 (profits when price falls)
# ══════════════════════════════════════════════════════════════════════════════

def _mt_log(action: str, pos_id: str, detail: str) -> None:
    from zoneinfo import ZoneInfo as _ZI
    mt = state["manual_trader"]
    entry = f"{datetime.now(_ZI('America/New_York')).strftime('%H:%M:%S')} {action} [{pos_id}] {detail}"
    mt["decisions"] = mt["decisions"][-199:] + [entry]
    log.info("MT %s [%s] %s", action, pos_id, detail)


def _mt_save_state() -> None:
    mt = state["manual_trader"]
    try:
        with open(MT_STATE_PATH, "w") as f:
            json.dump({
                "enabled":   mt["enabled"],
                "positions": mt["positions"],
                "closed":    mt["closed"][-100:],
                "decisions": mt.get("decisions", [])[-199:],
            }, f, indent=2, default=str)
    except Exception as e:
        log.warning("MT save state failed: %s", e)


def _mt_load_state() -> None:
    if not os.path.exists(MT_STATE_PATH):
        return
    try:
        with open(MT_STATE_PATH) as f:
            saved = json.load(f)
        mt = state["manual_trader"]
        mt["enabled"]   = saved.get("enabled", True)
        mt["closed"]    = saved.get("closed", [])
        mt["decisions"] = saved.get("decisions", [])
        # Reload only open positions
        for pos_id, pos in saved.get("positions", {}).items():
            if pos.get("phase") == "open":
                mt["positions"][pos_id] = pos
        log.info("MT state loaded: %d open positions", len(mt["positions"]))
    except Exception as e:
        log.warning("MT load state failed: %s", e)


def _mt_calc_pnl(position: dict, mids: dict) -> float:
    """Live P&L using mark-to-market option/stock mids.
    mids: {local_symbol: current_mid_price}
    Falls back to fill_price when no live quote available.
    """
    total = 0.0
    for leg in position["legs"]:
        sym  = leg["local_symbol"]
        mid  = mids.get(sym, leg["fill_price"])
        sign = 1 if leg["action"] == "BUY" else -1
        total += sign * (mid - leg["fill_price"]) * leg["qty"] * leg.get("multiplier", 100)
    return round(total, 2)


async def _mt_get_quotes(ib, position: dict) -> dict:
    """Live mid-prices: portfolio streaming first, reqTickers fallback for stale/missing quotes."""
    from ib_insync import Option as _IbOpt
    portfolio = {item.contract.localSymbol: item for item in ib.portfolio()}
    mids: dict[str, float] = {}
    missing: list[dict] = []

    for leg in position["legs"]:
        sym  = leg["local_symbol"]
        item = portfolio.get(sym)
        if item is not None and item.marketPrice > 0:
            mids[sym] = round(item.marketPrice, 4)
        else:
            missing.append(leg)

    if missing:
        try:
            contracts = [
                _IbOpt(lg["ticker"], lg["expiry"],
                       float(lg["strike"]), lg["right"],
                       "SMART", "100", "USD")
                for lg in missing
            ]
            qualified = await ib.qualifyContractsAsync(*contracts)
            qualified = [q for q in qualified if q]
            if qualified:
                tickers = await ib.reqTickersAsync(*qualified)
                for tkr in tickers:
                    sym = tkr.contract.localSymbol
                    bid = tkr.bid if tkr.bid and tkr.bid > 0 else 0
                    ask = tkr.ask if tkr.ask and tkr.ask > 0 else 0
                    if bid > 0 and ask > 0:
                        mids[sym] = round((bid + ask) / 2, 4)
                    elif tkr.last and tkr.last > 0:
                        mids[sym] = round(tkr.last, 4)
        except Exception as _e:
            log.warning("MT reqTickers fallback failed: %s", _e)

    for leg in position["legs"]:
        if leg["local_symbol"] not in mids:
            mids[leg["local_symbol"]] = leg["fill_price"]

    return mids


def _mt_journal_insert(pos: dict):
    """Insert a new MT spread into trade_journal. Returns journal id or None."""
    try:
        con = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
        cur = con.execute("""
            INSERT INTO trade_journal
                (opened_at, ticker, expiry, action, qty, entry_price, strategy_type, notes, is_paper)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            date.today().isoformat(),
            pos["ticker"],
            pos.get("expiry", ""),
            pos.get("strategy", "manual_trader"),
            1,
            round(pos.get("net_entry", 0.0), 2),
            "manual_trader",
            json.dumps({"name": pos.get("name", ""), "legs": pos.get("legs", [])}),
            _is_paper(),
        ))
        journal_id = cur.lastrowid
        con.commit()
        con.close()
        return journal_id
    except Exception as exc:
        log.warning("MT journal insert failed: %s", exc)
        return None


def _mt_journal_close(journal_id: int, pnl: float, reason: str, fills: dict) -> None:
    """Update trade_journal row when MT spread closes with actual fill data."""
    try:
        con = sqlite3.connect(JOURNAL_DB_PATH, check_same_thread=False)
        con.execute("""
            UPDATE trade_journal
            SET closed_at=?, pnl=?, win=?, exit_reason=?,
                notes = notes || ?
            WHERE id=?
        """, (
            date.today().isoformat(),
            round(pnl, 2),
            1 if pnl > 0 else 0,
            reason,
            "\nFILLS:" + json.dumps(fills),
            journal_id,
        ))
        con.commit()
        con.close()
    except Exception as exc:
        log.warning("MT journal close failed: %s", exc)


async def _mt_flex_backfill_coro(pos_id: str, delay_s: int = 120) -> None:
    """Wait delay_s then fetch IBKR fills via Flex Query and backfill close_pnl."""
    await asyncio.sleep(delay_s)
    mt = state["manual_trader"]
    # Find the closed position
    pos = next((p for p in mt["closed"] if p.get("pos_id") == pos_id), None)
    if not pos:
        log.debug("flex_backfill %s: position not found in closed list", pos_id)
        return
    if pos.get("close_fills"):
        log.debug("flex_backfill %s: already has fills, skipping", pos_id)
        return

    try:
        qid = _flex_load_query_id()
        xml_str = await asyncio.get_event_loop().run_in_executor(
            None, lambda: _flex_fetch_xml(qid, max_send_attempts=8)
        )
    except Exception as exc:
        log.warning("flex_backfill %s: Flex fetch failed: %s", pos_id, exc)
        return

    import xml.etree.ElementTree as ET
    trades = list(ET.fromstring(xml_str).iter("Trade"))
    close_by_local: dict[str, dict] = {}
    for t in trades:
        if t.get("openCloseIndicator") != "C" or t.get("assetCategory") != "OPT":
            continue
        sym = t.get("symbol", "").strip()
        if sym not in close_by_local or t.get("tradeDate", "") > close_by_local[sym].get("tradeDate", ""):
            close_by_local[sym] = dict(t.items())

    new_fills: dict[str, float] = {}
    new_pnl = 0.0
    for leg in pos.get("legs", []):
        local_sym = leg["local_symbol"].strip()
        cand = close_by_local.get(local_sym)
        if not cand:
            log.warning("flex_backfill %s: leg %s not found in Flex data", pos_id, local_sym)
            return
        close_price = abs(float(cand.get("tradePrice", 0)))
        new_fills[local_sym] = close_price
        sign = 1 if leg["action"] == "BUY" else -1
        new_pnl += sign * (close_price - leg["fill_price"]) * leg["qty"] * leg.get("multiplier", 100)

    new_pnl = round(new_pnl, 2)
    pos["close_fills"] = new_fills
    pos["close_pnl"]   = new_pnl
    pos["win"]         = 1 if new_pnl > 0 else 0
    _mt_save_state()

    jid = pos.get("journal_id")
    if jid:
        _mt_journal_close(jid, new_pnl, pos.get("close_reason", ""), new_fills)

    _mt_log("FLEX_BACKFILL", pos_id, f"pnl={new_pnl:+.2f} fills={new_fills}")
    log.info("MT flex_backfill %s: pnl=%+.2f", pos_id, new_pnl)


_mt_closing_ids: set = set()
_mt_closing_lock = threading.Lock()

async def _mt_close_position_coro(ib, pos_id: str, reason: str) -> bool:
    """Close all legs of a position. Returns True on full fill."""
    import math as _math
    from ib_insync import Option as IbOpt, Stock as IbStock, LimitOrder
    import time as _time

    # Thread-safe guard: prevent concurrent closes for the same position.
    # Multiple monitor tasks can race when options start pricing at 9:30.
    with _mt_closing_lock:
        if pos_id in _mt_closing_ids:
            log.info("MT close %s: already in progress, skipping duplicate call", pos_id)
            return False
        _mt_closing_ids.add(pos_id)

    try:
        return await _mt_close_position_coro_inner(ib, pos_id, reason)
    finally:
        _mt_closing_ids.discard(pos_id)


async def _mt_close_position_coro_inner(ib, pos_id: str, reason: str) -> bool:
    import math as _math
    from ib_insync import Option as IbOpt, Stock as IbStock, LimitOrder
    import time as _time

    mt  = state["manual_trader"]
    pos = mt["positions"].get(pos_id)
    if not pos or pos["phase"] != "open":
        return False

    pos["phase"] = "closing"
    _mt_log("CLOSING", pos_id, reason)

    fills: dict[str, float] = {}
    trades_list = []

    portfolio = {item.contract.localSymbol: item for item in ib.portfolio()}

    # Two-phase close: BUY-to-close legs (covering shorts) must fill BEFORE
    # SELL-to-close legs. Selling a long leg while its short is still open
    # strips the hedge and IBKR rejects with "margin deficit" (error 201).
    buy_legs  = [l for l in pos["legs"] if l["action"] == "SELL"]  # short → BUY to close
    sell_legs = [l for l in pos["legs"] if l["action"] == "BUY"]   # long  → SELL to close

    async def _place_leg(leg):
        try:
            right = leg.get("right")
            if right in ("P", "C"):
                contract = IbOpt(
                    leg["ticker"], leg["expiry"],
                    float(leg["strike"]), right,
                    "SMART", "100", "USD"
                )
            else:
                contract = IbStock(leg["ticker"], "SMART", "USD")
            q = await ib.qualifyContractsAsync(contract)
            if not q:
                _mt_log("ERROR", pos_id, f"could not qualify {leg['local_symbol']}")
                return

            # Mid price: prefer streaming portfolio, fall back to live reqTickers,
            # last resort is entry fill price (signals stale data, logged as warning).
            item = portfolio.get(leg["local_symbol"])
            mid = item.marketPrice if (item and item.marketPrice and item.marketPrice > 0) else None
            if not mid:
                try:
                    tickers = await ib.reqTickersAsync(q[0])
                    td = tickers[0] if tickers else None
                    b = getattr(td, "bid", None); a = getattr(td, "ask", None)
                    lp = getattr(td, "last", None)
                    if b and a and not _math.isnan(b) and not _math.isnan(a) and b > 0 and a > 0:
                        mid = round((b + a) / 2, 2)
                    elif lp and not _math.isnan(lp) and lp > 0:
                        mid = lp
                except Exception as _te:
                    log.warning("MT reqTickers fallback failed for %s: %s", leg["local_symbol"], _te)
            if not mid:
                log.warning("MT %s: no live price for %s, using entry fill price as fallback",
                            pos_id, leg["local_symbol"])
                mid = leg["fill_price"]

            # Close is the opposite action of entry; be aggressive on fills
            close_action = "SELL" if leg["action"] == "BUY" else "BUY"
            lmt = max(round(mid * 0.85, 2), 0.01) if close_action == "SELL" else round(mid * 1.15 + 0.01, 2)
            order = LimitOrder(close_action, leg["qty"], lmt, tif="DAY")
            trade = ib.placeOrder(q[0], order)
            trades_list.append((trade, leg["local_symbol"], close_action, lmt))
            log.info("MT placed %s %s @ $%.2f (mid=%.2f)", close_action, leg["local_symbol"], lmt, mid)
        except Exception as e:
            _mt_log("ERROR", pos_id, f"order placement error {leg.get('local_symbol')}: {e}")

    async def _wait_fills(timeout_s: int):
        deadline = _time.time() + timeout_s
        while _time.time() < deadline and len(fills) < len(trades_list):
            await asyncio.sleep(2)
            for trade, sym, action, lmt in trades_list:
                if sym not in fills and trade.orderStatus.status == "Filled":
                    fills[sym] = trade.orderStatus.avgFillPrice
                    log.info("MT fill: %s %s @ $%.2f", action, sym, fills[sym])

    # Phase 1: cover shorts (BUY-to-close). Must complete before selling longs.
    for leg in buy_legs:
        await _place_leg(leg)
    await _wait_fills(60)

    # Phase 2: sell longs (SELL-to-close), only after shorts are covered.
    covered = all(l["local_symbol"] in fills for l in buy_legs)
    if not covered and sell_legs:
        log.warning("MT %s: shorts not fully covered after 60s, selling longs anyway "
                    "(margin rejection possible)", pos_id)
    for leg in sell_legs:
        await _place_leg(leg)
    await _wait_fills(60)

    all_filled = len(fills) == len(pos["legs"])

    # If zero fills at all, the close orders failed — revert to open and bail.
    if not fills:
        pos["phase"] = "open"
        _mt_log("CLOSE_FAILED", pos_id, f"{reason} — 0 fills, reverting to open")
        log.warning("MT close %s: no fills received, position reverted to open", pos_id)
        return False

    # Compute realized P&L from fills.
    # For unfilled legs (falls back to fill_price), contribution is zero.
    # Use live_pnl as close_pnl when fills are partial (some legs missed).
    realized_pnl = 0.0
    for leg in pos["legs"]:
        sym   = leg["local_symbol"]
        close = fills.get(sym, leg["fill_price"])
        sign  = 1 if leg["action"] == "BUY" else -1
        realized_pnl += sign * (close - leg["fill_price"]) * leg["qty"] * leg.get("multiplier", 100)
    realized_pnl = round(realized_pnl, 2)
    if not all_filled and realized_pnl == 0:
        realized_pnl = round(pos.get("live_pnl", 0.0), 2)

    from zoneinfo import ZoneInfo as _ZI
    now_str = datetime.now(_ZI("America/New_York")).isoformat()
    pos.update({
        "phase":        "closed",
        "close_reason": reason,
        "close_pnl":    realized_pnl,
        "closed_at":    now_str,
        "close_fills":  fills,
    })
    mt["closed"] = mt["closed"][-99:] + [pos]
    del mt["positions"][pos_id]
    _mt_save_state()

    journal_id = pos.get("journal_id")
    if journal_id:
        _mt_journal_close(journal_id, realized_pnl, reason, fills)

    # Schedule Flex backfill 2 min after close to get actual IBKR fill prices.
    # Runs even when ib_insync fills ARE captured — Flex is the authoritative source.
    try:
        loop = state.get("streaming_loop") or asyncio.get_event_loop()
        asyncio.run_coroutine_threadsafe(_mt_flex_backfill_coro(pos_id, delay_s=120), loop)
        log.info("MT: scheduled Flex backfill for %s in 120s", pos_id)
    except Exception as _fe:
        log.debug("MT: could not schedule Flex backfill: %s", _fe)

    status_word = "CLOSED" if all_filled else "PARTIAL_CLOSE"
    _mt_log(status_word, pos_id, f"{reason} pnl=${realized_pnl:+.2f} fills={len(fills)}/{len(pos['legs'])}")

    # Telegram
    try:
        import requests as _req
        with open(os.path.join(os.path.dirname(__file__), "scanner_config.json")) as _f:
            _cfg = json.load(_f)
        _fills_str = "\n".join(f"  {leg['action']} {leg['local_symbol']} close @ ${fills.get(leg['local_symbol'], 'PENDING'):.2f}"
                               for leg in pos["legs"] if isinstance(fills.get(leg["local_symbol"]), float))
        _icon = "✅" if realized_pnl >= 0 else "❌"
        _msg = (
            f"{_icon} <b>Manual Trader: {pos['name']} CLOSED</b>\n"
            f"Reason: {reason}\n\n"
            f"{_fills_str}\n\n"
            f"Realized P&L: <b>${realized_pnl:+.2f}</b>"
        )
        _req.post(
            f"https://api.telegram.org/bot{_cfg['telegram_token']}/sendMessage",
            json={"chat_id": _cfg["telegram_chat_id"], "text": _msg, "parse_mode": "HTML"},
            timeout=8,
        )
    except Exception:
        pass

    return all_filled


def _mt_reconcile_sync(ib) -> None:
    """Cross-check MT state against live IBKR portfolio.

    Two corrections:
      1. Open positions whose legs are all gone from IBKR → mark externally_closed.
      2. Closed positions with empty close_fills whose legs are still in IBKR → re-open.
    """
    mt = state["manual_trader"]
    try:
        ibkr_held = {
            item.contract.localSymbol
            for item in ib.portfolio()
            if item.position != 0
        }
    except Exception as ex:
        log.warning("MT reconcile: cannot read portfolio: %s", ex)
        return

    from zoneinfo import ZoneInfo as _ZI
    now_str = datetime.now(_ZI("America/New_York")).isoformat()

    # 1. Open → externally_closed if all legs absent from IBKR
    for pos_id, pos in list(mt["positions"].items()):
        if pos.get("phase") != "open":
            continue
        leg_syms = [l["local_symbol"] for l in pos.get("legs", [])]
        present  = [s for s in leg_syms if s in ibkr_held]
        if leg_syms and not present:
            pos.update({
                "phase":        "closed",
                "close_reason": "externally_closed (IBKR sync)",
                "close_pnl":    pos.get("live_pnl", 0.0),
                "closed_at":    now_str,
                "close_fills":  {},
            })
            mt["closed"] = mt["closed"][-99:] + [pos]
            del mt["positions"][pos_id]
            _mt_log("RECON", pos_id, "externally_closed — legs absent from IBKR portfolio")
            log.info("MT reconcile: %s externally closed (legs not in IBKR)", pos_id)

    # 2. Recently closed with no fills whose legs are STILL in IBKR → re-open
    to_reopen = []
    for pos in mt["closed"][-20:]:
        if pos.get("close_fills"):        # genuine fills → skip
            continue
        leg_syms = [l["local_symbol"] for l in pos.get("legs", [])]
        still_held = [s for s in leg_syms if s in ibkr_held]
        if still_held:
            to_reopen.append((pos, still_held))

    for pos, still_held in to_reopen:
        pos_id = pos["pos_id"]
        pos.update({
            "phase":        "open",
            "close_reason": None,
            "close_pnl":    None,
            "closed_at":    None,
            "close_fills":  {},
        })
        mt["positions"][pos_id] = pos
        mt["closed"] = [p for p in mt["closed"] if p["pos_id"] != pos_id]
        _mt_log("RECON", pos_id, f"re-opened — legs still in IBKR: {still_held}")
        log.info("MT reconcile: %s re-opened (still in IBKR: %s)", pos_id, still_held)

    if to_reopen:
        _mt_save_state()


async def _mt_monitor_coro(ib) -> None:
    """Check all open Manual Trader positions for exit conditions."""
    from zoneinfo import ZoneInfo as _ZI
    mt  = state["manual_trader"]
    now = datetime.now(_ZI("America/New_York"))

    # Sync with actual IBKR holdings before evaluating exits
    _mt_reconcile_sync(ib)

    for pos_id, pos in list(mt["positions"].items()):
        if pos.get("phase") != "open":
            continue

        # Get live quotes
        mids = await _mt_get_quotes(ib, pos)
        if not mids:
            continue

        live_pnl = _mt_calc_pnl(pos, mids)
        pos["live_pnl"] = live_pnl

        # ── Profit target ───────────────────────────────────────────────────────
        pt = pos.get("profit_target_usd")
        if pt is not None and live_pnl >= pt:
            await _mt_close_position_coro(ib, pos_id, f"profit_target_hit (${live_pnl:+.2f} >= ${pt})")
            continue

        # ── Stop loss ───────────────────────────────────────────────────────────
        sl = pos.get("stop_loss_usd")
        if sl is not None and live_pnl <= sl:
            await _mt_close_position_coro(ib, pos_id, f"stop_loss_hit (${live_pnl:+.2f} <= ${sl})")
            continue

        # ── Hard close on expiry day ────────────────────────────────────────────
        expiry = pos.get("expiry")
        hard_t = pos.get("hard_close_time", "15:45")
        if expiry and hard_t:
            exp_date = datetime.strptime(expiry, "%Y%m%d").date()
            if now.date() == exp_date:
                hh, mm = map(int, hard_t.split(":"))
                if now.hour > hh or (now.hour == hh and now.minute >= mm):
                    await _mt_close_position_coro(ib, pos_id, f"hard_close_{hard_t}_expiry_day")
                    continue

        _mt_log("MONITOR", pos_id, f"live_pnl=${live_pnl:+.2f} pt={pt} sl={sl}")

    _mt_save_state()


_red_day_alerted: str = ""   # date str of last alert, one ping per day

async def _red_day_watch_coro(ib) -> None:
    """Check SPY daily change; Telegram-alert once per day at <= -1.5%.
    Purpose: signal that index put-spread premium is 'on sale' (user standing request)."""
    global _red_day_alerted
    import math as _math
    from ib_insync import Stock as _Stk
    from zoneinfo import ZoneInfo as _ZI
    today_str = datetime.now(_ZI("America/New_York")).date().isoformat()
    if _red_day_alerted == today_str:
        return
    s = _Stk("SPY", "SMART", "USD")
    q = await ib.qualifyContractsAsync(s)
    if not q:
        return
    tds = await ib.reqTickersAsync(q[0])
    td = tds[0] if tds else None
    if not td:
        return
    def _c(v):
        return v if v is not None and not _math.isnan(v) and v > 0 else None
    b, a, last, prev = _c(td.bid), _c(td.ask), _c(td.last), _c(td.close)
    spot = (b + a) / 2 if b and a else last
    if not spot or not prev:
        return
    chg = (spot - prev) / prev * 100
    if chg <= -1.5:
        _red_day_alerted = today_str
        log.info("RED DAY: SPY %.2f (%.2f%%) — premium-sale alert", spot, chg)
        try:
            import requests as _req
            with open(os.path.join(os.path.dirname(__file__), "scanner_config.json")) as _f:
                _cfg = json.load(_f)
            _req.post(
                f"https://api.telegram.org/bot{_cfg['telegram_token']}/sendMessage",
                json={"chat_id": _cfg["telegram_chat_id"],
                      "text": (f"🔴 <b>RED DAY — index premium on sale</b>\n"
                               f"SPY ${spot:.2f} ({chg:+.2f}%)\n\n"
                               f"Standing plan: sell SPY/QQQ put spreads 5-6% OTM, "
                               f"2-3 wk expiry — credits run 2-3x normal on days like this. "
                               f"Ask Claude to scan index chains."),
                      "parse_mode": "HTML"},
                timeout=8,
            )
        except Exception as _te:
            log.warning("red-day Telegram failed: %s", _te)


async def _red_day_watch_loop() -> None:
    """5-minute watcher for red days (SPY <= -1.5%) during market hours."""
    while True:
        await asyncio.sleep(300)
        ib = state.get("ib")
        if not ib or not ib.isConnected():
            continue
        from zoneinfo import ZoneInfo as _ZI
        now = datetime.now(_ZI("America/New_York"))
        if now.weekday() >= 5:
            continue
        if not (now.replace(hour=9, minute=35, second=0) <= now <= now.replace(hour=16, minute=0, second=0)):
            continue
        loop = state.get("streaming_loop")
        if loop:
            loop.run_in_executor(
                None,
                lambda: _run_in_streaming_loop(_red_day_watch_coro(state["ib"]), timeout=60),
            )


async def _mt_monitor_loop() -> None:
    """30-second background monitor for all Manual Trader positions."""
    while True:
        await asyncio.sleep(30)
        mt = state.get("manual_trader", {})
        if not mt.get("enabled") or not mt.get("positions"):
            continue
        ib = state.get("ib")
        if not ib or not ib.isConnected():
            continue
        # Only monitor during market hours (9:25–16:05 ET)
        from zoneinfo import ZoneInfo as _ZI
        now = datetime.now(_ZI("America/New_York"))
        if not (now.replace(hour=9, minute=25, second=0) <= now <= now.replace(hour=16, minute=5, second=0)):
            continue
        loop = state.get("streaming_loop")
        if loop:
            loop.run_in_executor(
                None,
                lambda: _run_in_streaming_loop(_mt_monitor_coro(state["ib"]), timeout=120),
            )


# ── Manual Trader Pydantic models ─────────────────────────────────────────────

class MTEnterLegRequest(BaseModel):
    action: str        # "BUY" or "SELL"
    strike: float
    right:  str        # "C" or "P"

class MTEnterRequest(BaseModel):
    ticker:            str
    expiry:            str                          # "20260731"
    legs:              List[MTEnterLegRequest]       # 1=naked, 2=vertical, 4=condor
    limit_price:       float                        # net debit/credit per share
    qty:               int            = 1
    name:              Optional[str]  = None        # auto-generated if omitted
    strategy:          str            = "vertical"  # vertical | iron_condor | naked_option | custom
    profit_target_usd: Optional[float]= None
    stop_loss_usd:     Optional[float]= None
    hard_close_time:   Optional[str]  = "15:45"
    reprice_steps:     int            = 3           # reprice attempts after initial
    reprice_wait_s:    int            = 15          # seconds per attempt
    max_concession_pct:float          = 0.20        # max 20% total price reduction

class MTLegRequest(BaseModel):
    local_symbol: str                      # e.g. "INTC 260724P00085000"
    ticker:       str
    expiry:       Optional[str]  = None    # "20260724" or None for stocks
    strike:       Optional[float]= None
    right:        Optional[str]  = None    # "P", "C", or None for stocks
    action:       str                      # "BUY" or "SELL"
    qty:          int            = 1
    fill_price:   float                    # per-share fill price
    multiplier:   int            = 100     # 100 for options, 1 for stocks

class MTPositionRequest(BaseModel):
    name:              str                        # human label, e.g. "INTC Iron Condor Jul 24"
    ticker:            str                        # underlying ticker
    strategy:          str            = "custom"  # iron_condor | vertical | naked_option | stock | custom
    expiry:            Optional[str]  = None      # "20260724"
    legs:              List[MTLegRequest]
    profit_target_usd: Optional[float]= None      # close when live_pnl >= this ($)
    stop_loss_usd:     Optional[float]= None      # close when live_pnl <= this (negative $)
    hard_close_time:   Optional[str]  = "15:45"  # "HH:MM" ET, on expiry day only
    notes:             Optional[str]  = None

class MTUpdateRequest(BaseModel):
    profit_target_usd: Optional[float] = None
    stop_loss_usd:     Optional[float] = None
    hard_close_time:   Optional[str]   = None
    notes:             Optional[str]   = None


# ── Manual Trader placement coroutine ────────────────────────────────────────

async def _mt_place_order_coro(ib, req: "MTEnterRequest") -> dict:
    """Place an option order (single or multi-leg BAG) and register it in MT on fill."""
    from ib_insync import Option as IbOpt, Contract as IbBag, ComboLeg, LimitOrder as IbLimitOrder
    from zoneinfo import ZoneInfo as _ZI
    import time as _time

    ticker = req.ticker.upper()
    expiry = req.expiry
    n_legs = len(req.legs)

    # 1. Qualify all legs
    raw_contracts = [
        IbOpt(ticker, expiry, leg.strike, leg.right.upper(), "SMART", "100", "USD")
        for leg in req.legs
    ]
    qualified = await ib.qualifyContractsAsync(*raw_contracts)
    for i, q in enumerate(qualified):
        if not q or not q.conId:
            lg = req.legs[i]
            raise ValueError(f"Could not qualify {ticker} {expiry} {lg.strike}{lg.right}")

    # 2. Build contract — BAG for spreads (avoids Inactive issue), Option for single leg
    if n_legs == 1:
        contract = qualified[0]
        net_action = req.legs[0].action.upper()
    else:
        contract          = IbBag()
        contract.symbol   = ticker
        contract.secType  = "BAG"
        contract.currency = "USD"
        contract.exchange = "SMART"
        combo_legs = []
        for leg, q in zip(req.legs, qualified):
            cl = ComboLeg()
            cl.conId              = q.conId
            cl.ratio              = 1
            cl.action             = leg.action.upper()
            cl.exchange           = "SMART"
            cl.openClose          = 0
            cl.shortSaleSlot      = 0
            cl.designatedLocation = ""
            cl.exemptCode         = -1
            combo_legs.append(cl)
        contract.comboLegs = combo_legs
        # Net action: if more BUY legs → BUY (debit spread); more SELL → SELL (credit spread)
        buy_count  = sum(1 for l in req.legs if l.action.upper() == "BUY")
        sell_count = n_legs - buy_count
        net_action = "BUY" if buy_count > sell_count else "SELL"

    # 3. Reprice loop — try fill at initial price, step down, give up after reprice_steps
    price      = round(req.limit_price, 2)
    per_step   = round(req.limit_price * req.max_concession_pct / max(req.reprice_steps, 1), 2)
    per_step   = max(per_step, 0.01)
    filled_trade = None

    # Capture the REAL IBKR error text for this order specifically -- the old
    # code just assumed "Inactive" always meant precautions/transmission and
    # printed a canned guess without ever checking. Confirmed 2026-08-05 that
    # guess was wrong (Read-Only API off, all precautions already bypassed)
    # while chasing a TSLA order that still went Inactive -- same diagnostic
    # gap as the SPX 0DTE "Combo price is invalid" investigation earlier.
    _ibkr_errors: list[str] = []
    def _on_order_error(reqId, errorCode, errorString, contract):
        _ibkr_errors.append(f"[{errorCode}] {errorString}")
    ib.errorEvent += _on_order_error

    try:
        for step in range(req.reprice_steps + 1):
            order          = IbLimitOrder(net_action, req.qty, price)
            order.tif      = "DAY"
            order.transmit = True
            _ibkr_errors.clear()
            trade = ib.placeOrder(contract, order)
            await asyncio.sleep(2)

            status = trade.orderStatus.status
            if status == "Inactive":
                try:
                    ib.cancelOrder(order)
                except Exception:
                    pass
                reason = "; ".join(_ibkr_errors) if _ibkr_errors else "(no IBKR error message captured)"
                raise ValueError(f"Order went Inactive. IBKR said: {reason}")

            # Poll until fill or timeout
            deadline = _time.time() + req.reprice_wait_s
            while _time.time() < deadline:
                await asyncio.sleep(1)
                s = trade.orderStatus.status
                if trade.orderStatus.filled >= req.qty:
                    filled_trade = trade
                    break
                if s in ("Cancelled", "ApiCancelled", "Inactive"):
                    break
            if filled_trade:
                break

            if step < req.reprice_steps:
                try:
                    ib.cancelOrder(order)
                    await asyncio.sleep(1)
                except Exception:
                    pass
                new_price = round(price - per_step, 2)
                _mt_log("REPRICE", f"{ticker}_enter",
                        f"step {step+1}/{req.reprice_steps} @ ${price:.2f} no fill → ${new_price:.2f}")
                price = max(new_price, 0.01)
    finally:
        ib.errorEvent -= _on_order_error

    if not filled_trade:
        raise ValueError(
            f"Order did not fill after {req.reprice_steps + 1} attempts "
            f"(${req.limit_price:.2f} → ${price:.2f})"
        )

    # 4. Build leg fill prices from portfolio averageCost
    await asyncio.sleep(2)
    portfolio = {item.contract.conId: item for item in ib.portfolio()}
    legs_out = []
    for leg, q in zip(req.legs, qualified):
        item       = portfolio.get(q.conId)
        avg_cost   = abs(item.averageCost) if item else 0.0
        # averageCost for options is per-share (already in dollar terms, not × 100)
        fill_price = round(avg_cost, 4) if 0 < avg_cost < 500 else round(abs(filled_trade.orderStatus.avgFillPrice), 4)
        legs_out.append({
            "local_symbol": q.localSymbol,
            "ticker":       ticker,
            "expiry":       expiry,
            "strike":       leg.strike,
            "right":        leg.right.upper(),
            "action":       leg.action.upper(),
            "qty":          req.qty,
            "fill_price":   fill_price,
            "multiplier":   100,
        })

    # 5. Register MT position
    mt      = state["manual_trader"]
    now     = datetime.now(_ZI("America/New_York"))
    pos_id  = f"{ticker}_{req.strategy}_{now.strftime('%Y%m%d_%H%M%S')}"
    name    = req.name or f"{ticker} {req.strategy.replace('_',' ').title()} {expiry}"
    net_entry = round(sum(
        (1 if l["action"] == "SELL" else -1) * l["fill_price"] * l["qty"] * l["multiplier"]
        for l in legs_out
    ), 2)

    pos = {
        "pos_id":            pos_id,
        "name":              name,
        "ticker":            ticker,
        "strategy":          req.strategy,
        "expiry":            expiry,
        "legs":              legs_out,
        "net_entry":         net_entry,
        "profit_target_usd": req.profit_target_usd,
        "stop_loss_usd":     req.stop_loss_usd,
        "hard_close_time":   req.hard_close_time,
        "notes":             None,
        "phase":             "open",
        "entry_time":        now.isoformat(),
        "live_pnl":          0.0,
        "close_reason":      None,
        "close_pnl":         None,
        "closed_at":         None,
    }
    mt["positions"][pos_id] = pos
    _mt_log("ENTERED", pos_id,
            f"{name} fill=${filled_trade.orderStatus.avgFillPrice:.2f} net_entry=${net_entry:+.2f}")
    _mt_save_state()

    # 6. Telegram entry alert
    try:
        import requests as _req2
        with open(os.path.join(os.path.dirname(__file__), "scanner_config.json")) as _f:
            _cfg = json.load(_f)
        _legs_str = "\n".join(
            f"  {'🟢' if l['action']=='BUY' else '🔴'} {l['action']} {l['local_symbol']} @ ${l['fill_price']:.2f}"
            for l in legs_out
        )
        _pt  = f"${req.profit_target_usd:+.2f}" if req.profit_target_usd is not None else "—"
        _sl  = f"${req.stop_loss_usd:+.2f}"     if req.stop_loss_usd     is not None else "—"
        _msg = (
            f"📋 <b>Manual Trader: {name} ENTERED</b>\n"
            f"Strategy: {req.strategy.replace('_',' ').title()} · {ticker}\n\n"
            f"{_legs_str}\n\n"
            f"Fill: <b>${filled_trade.orderStatus.avgFillPrice:.2f}</b>  net_entry=${net_entry:+.2f}\n"
            f"Profit target: {_pt}  |  Stop loss: {_sl}"
        )
        _req2.post(
            f"https://api.telegram.org/bot{_cfg['telegram_token']}/sendMessage",
            json={"chat_id": _cfg["telegram_chat_id"], "text": _msg, "parse_mode": "HTML"},
            timeout=8,
        )
    except Exception:
        pass

    return {"status": "filled", "pos_id": pos_id, "fill_price": filled_trade.orderStatus.avgFillPrice,
            "net_entry": net_entry, "position": pos}


