# ══════════════════════════════════════════════════════════════════════════════
# ALPACA — read-only position visibility (execution venue, not tracked in-app)
#
# Orders currently go out via standalone scripts (alpaca_spread_test*.py,
# nflx_bottom_monitor.py, alpaca_cohr_spread.py), not this backend -- there is
# no in-app order placement, no journal entry, no monitor loop for these
# positions (see oversight_log.jsonl / secretary_tasks.json task 2026-08-12-005
# for the full gap and why it matters). This endpoint is the minimal fix:
# read-only visibility into whatever is actually sitting in the Alpaca account
# right now, queried live on every call, so it shows up somewhere in the app
# instead of only being visible via a direct API call.
# ══════════════════════════════════════════════════════════════════════════════

@app.get("/alpaca/positions")
def alpaca_positions():
    """Live positions + account snapshot from Alpaca. Read-only -- no order
    placement lives here. Real trades go out via the standalone scripts."""
    try:
        from alpaca.trading.client import TradingClient
    except ImportError:
        raise HTTPException(503, "alpaca-py not installed")

    cfg_path = os.path.join(os.path.dirname(__file__), "scanner_config.json")
    with open(cfg_path) as f:
        cfg = json.load(f)
    api_key = cfg.get("alpaca_api_key")
    secret_key = cfg.get("alpaca_secret_key")
    base_url = cfg.get("alpaca_base_url")
    if not api_key or not secret_key:
        raise HTTPException(503, "Alpaca API keys not configured in scanner_config.json")

    try:
        client = TradingClient(api_key, secret_key, paper=False, url_override=base_url)
        acct = client.get_account()
        positions = client.get_all_positions()
    except Exception as exc:
        raise HTTPException(502, f"Alpaca API error: {exc}")

    return {
        "account": {
            "cash":                 float(acct.cash),
            "equity":               float(acct.equity),
            "options_buying_power": float(acct.options_buying_power) if acct.options_buying_power else None,
            "buying_power":         float(acct.buying_power),
        },
        "positions": [
            {
                "symbol":         p.symbol,
                "asset_class":    str(p.asset_class),
                "qty":            float(p.qty),
                "side":           str(p.side),
                "avg_entry_price": float(p.avg_entry_price) if p.avg_entry_price else None,
                "current_price":  float(p.current_price) if p.current_price else None,
                "market_value":   float(p.market_value) if p.market_value else None,
                "unrealized_pl":  float(p.unrealized_pl) if p.unrealized_pl else None,
                "unrealized_plpc": float(p.unrealized_plpc) * 100 if p.unrealized_plpc else None,
            }
            for p in positions
        ],
    }


# ══════════════════════════════════════════════════════════════════════════════
# FX TRADER — EMA(50) + 20-bar breakout on 4 major pairs, 08:00–12:00 ET
# Strategy: 1H bars, ATR(14) stop (1.5×) + target (2×), OCA bracket orders
# ══════════════════════════════════════════════════════════════════════════════

def _fx_log(action: str, pair: str, detail: str) -> None:
    from zoneinfo import ZoneInfo as _ZI
    entry = {"time": datetime.now(_ZI("America/New_York")).strftime("%H:%M:%S"),
             "action": action, "pair": pair, "detail": detail}
    fx = state["fx_trader"]
    fx["decisions"].append(entry)
    fx["decisions"] = fx["decisions"][-200:]
    log.info("FX_TRADER [%s] %s — %s", action, pair, detail)


def _fx_save_state() -> None:
    try:
        fx = state["fx_trader"]
        with open(FX_STATE_PATH, "w") as f:
            json.dump({"enabled": fx["enabled"], "config": fx["config"],
                       "positions": fx["positions"],
                       "closed_today": fx["closed_today"],
                       "decisions": fx.get("decisions", [])[-200:]}, f, indent=2, default=str)
    except Exception as e:
        log.warning("FX_TRADER save_state error: %s", e)


def _fx_load_state() -> None:
    if not os.path.exists(FX_STATE_PATH):
        return
    try:
        from zoneinfo import ZoneInfo as _ZI
        with open(FX_STATE_PATH) as f:
            saved = json.load(f)
        fx = state["fx_trader"]
        if saved.get("enabled") is not None:
            fx["enabled"] = bool(saved["enabled"])
        fx["config"].update(saved.get("config", {}))
        fx["decisions"] = saved.get("decisions", [])
        today = datetime.now(_ZI("America/New_York")).strftime("%Y-%m-%d")
        for pair, pos in saved.get("positions", {}).items():
            if pos.get("phase") == "open" and pos.get("entry_time", "")[:10] == today:
                fx["positions"][pair] = pos
        fx["closed_today"] = [p for p in saved.get("closed_today", [])
                              if p.get("entry_time", "")[:10] == today]
    except Exception as e:
        log.warning("FX_TRADER load_state error: %s", e)


def _fx_pushover(title: str, message: str) -> None:
    """Fire-and-forget Telegram notification for FX Trader trade events."""
    import threading
    def _send():
        try:
            cfg_path = os.path.join(os.path.dirname(__file__), "scanner_config.json")
            with open(cfg_path) as f:
                cfg = json.load(f)
            token   = cfg.get("telegram_token",   "")
            chat_id = cfg.get("telegram_chat_id", "")
            if not token or not chat_id:
                return
            text = f"<b>{title}</b>\n{message}"
            requests.post(
                f"https://api.telegram.org/bot{token}/sendMessage",
                data={"chat_id": chat_id, "text": text, "parse_mode": "HTML"},
                timeout=10,
            )
        except Exception as exc:
            log.warning("FX Telegram error: %s", exc)
    threading.Thread(target=_send, daemon=True).start()


def _fx_size_qty(pair: str, stop_pips: float, risk_usd: float, spot: float) -> int:
    """Return position size in units. IBKR IDEALPRO minimum is 20,000 units."""
    pcfg    = FX_PAIRS[pair]
    pip     = pcfg["pip"]
    pip_usd = pip if pcfg["quote"] == "USD" else pip / max(spot, 1e-9)
    if stop_pips <= 0 or pip_usd <= 0:
        return 20_000
    qty = int(risk_usd / (stop_pips * pip_usd))
    return max(20_000, min(qty, 100_000))


def _fx_compute_signal(bars, pip_size: float):
    """
    EMA(50) trend + 20-bar high/low breakout on 1H bars.
    Returns (direction, stop_pips, atr14) where direction is 'LONG', 'SHORT', or None.
    """
    if len(bars) < 55:
        return None, 0, 0.0
    closes = [b.close for b in bars]
    highs  = [b.high  for b in bars]
    lows   = [b.low   for b in bars]
    # EMA(50) over all bars
    ema50 = closes[0]
    k = 2.0 / 51.0
    for c in closes[1:]:
        ema50 = c * k + ema50 * (1.0 - k)
    # 20-bar high/low lookback (exclude last bar — it is the signal bar)
    window_h = highs[-21:-1]
    window_l = lows[-21:-1]
    high20 = max(window_h) if window_h else 0.0
    low20  = min(window_l) if window_l else 1e9
    # ATR(14) — use last 14 true-range values
    trs = [max(bars[i].high - bars[i].low,
               abs(bars[i].high - bars[i - 1].close),
               abs(bars[i].low  - bars[i - 1].close)) for i in range(1, len(bars))]
    atr14     = sum(trs[-14:]) / 14 if len(trs) >= 14 else 0.0
    stop_pips = round(atr14 * 1.5 / pip_size, 1)
    last_c    = closes[-1]
    if last_c > high20 and last_c > ema50 and atr14 > 0:
        return "LONG",  stop_pips, atr14
    if last_c < low20  and last_c < ema50 and atr14 > 0:
        return "SHORT", stop_pips, atr14
    return None, 0, 0.0


async def _fx_enter_trade(ib, pair: str) -> None:
    """Fetch signal, check spread, size position, place market entry + OCA bracket."""
    from zoneinfo import ZoneInfo as _ZI
    from ib_insync import Forex as IbForex, MarketOrder, LimitOrder, StopOrder
    fx   = state["fx_trader"]
    cfg  = fx["config"]
    pcfg = FX_PAIRS[pair]
    if pair in fx["positions"]:
        _fx_log("SKIP", pair, "position already open")
        return
    if len(fx["positions"]) >= cfg["max_positions"]:
        _fx_log("SKIP", pair, f"max {cfg['max_positions']} positions reached")
        return
    try:
        # ── 1. Qualify contract + fetch 1H bars ────────────────────────────────
        contract = IbForex(pair)
        qualified = await ib.qualifyContractsAsync(contract)
        if not qualified:
            _fx_log("SKIP", pair, "qualify failed")
            return
        contract = qualified[0]
        bars = await ib.reqHistoricalDataAsync(
            contract, endDateTime="", durationStr="10 D",
            barSizeSetting="1 hour", whatToShow="MIDPOINT",
            useRTH=False, formatDate=1,
        )
        if not bars or len(bars) < 55:
            _fx_log("SKIP", pair, f"insufficient bars ({len(bars) if bars else 0})")
            return
        # ── 2. Compute EMA breakout signal ────────────────────────────────────
        direction, stop_pips, atr14 = _fx_compute_signal(bars, pcfg["pip"])
        if not direction:
            return  # no signal — silent
        # ── 3. Spread check ───────────────────────────────────────────────────
        tickers = await ib.reqTickersAsync(contract)
        await asyncio.sleep(2)
        td = tickers[0] if tickers else None
        if not td or not td.bid or not td.ask or td.bid <= 0 or td.ask <= 0:
            _fx_log("SKIP", pair, "no live quote")
            return
        spread_pips = round((td.ask - td.bid) / pcfg["pip"], 1)
        if spread_pips > cfg["max_spread_pips"]:
            _fx_log("SKIP", pair, f"spread={spread_pips}p > max={cfg['max_spread_pips']}p")
            return
        mid = (td.bid + td.ask) / 2.0
        # ── 4. Position size ──────────────────────────────────────────────────
        qty = _fx_size_qty(pair, stop_pips, cfg["risk_usd"], mid)
        # ── 5. Entry — limit order with 3-pip buffer (tif=GTC works 24/5 on Forex)
        action      = "BUY"  if direction == "LONG"  else "SELL"
        limit_px    = round(
            (td.ask + 3 * pcfg["pip"]) if direction == "LONG" else (td.bid - 3 * pcfg["pip"]),
            5,
        )
        entry_trade = ib.placeOrder(contract, LimitOrder(action, qty, limit_px, tif="GTC"))
        _fx_log("ORDERING", pair,
                f"{direction} {qty}u LMT@{limit_px:.5f}  stop_pips={stop_pips:.1f}  spread={spread_pips}p")
        for _ in range(20):
            await asyncio.sleep(1)
            if entry_trade.orderStatus.status in ("Filled", "Cancelled", "Inactive"):
                break
        if entry_trade.orderStatus.status != "Filled":
            ib.cancelOrder(entry_trade.order)
            _fx_log("SKIP", pair, f"fill failed ({entry_trade.orderStatus.status})")
            return
        fill_px = entry_trade.orderStatus.avgFillPrice or mid
        # ── 6. OCA stop + target bracket ─────────────────────────────────────
        exit_act = "SELL" if direction == "LONG" else "BUY"
        if direction == "LONG":
            stop_px   = round(fill_px - atr14 * 1.5, 5)
            target_px = round(fill_px + atr14 * 2.0, 5)
        else:
            stop_px   = round(fill_px + atr14 * 1.5, 5)
            target_px = round(fill_px - atr14 * 2.0, 5)
        oca = f"FX_{pair}_{datetime.now(_ZI('America/New_York')).strftime('%Y%m%d_%H%M%S')}"
        sl_trade = ib.placeOrder(contract,
                                 StopOrder(exit_act,  qty, stop_px,
                                           tif="GTC", ocaGroup=oca, ocaType=1))
        tp_trade = ib.placeOrder(contract,
                                 LimitOrder(exit_act, qty, target_px,
                                            tif="GTC", ocaGroup=oca, ocaType=1))
        now_utc      = _utcnow()
        target_pips  = round(atr14 * 2.0 / pcfg["pip"], 1)
        fx["positions"][pair] = {
            "pair":          pair,
            "direction":     direction,
            "entry_time":    now_utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
            "entry_price":   round(fill_px,   5),
            "stop_price":    round(stop_px,   5),
            "target_price":  round(target_px, 5),
            "stop_pips":     stop_pips,
            "target_pips":   target_pips,
            "qty":           qty,
            "phase":         "open",
            "oca_group":     oca,
            "sl_order_id":   sl_trade.order.orderId,
            "tp_order_id":   tp_trade.order.orderId,
            "conid":         contract.conId,
            "live_pnl":      0.0,
            "live_price":    round(fill_px, 5),
        }
        _fx_log("ENTERED", pair,
                f"{direction} {qty}u fill={fill_px:.5f}  sl={stop_px:.5f}  tp={target_px:.5f}  "
                f"R:R={target_pips/max(stop_pips,0.1):.1f}  risk=${cfg['risk_usd']:.0f}")
        _fx_pushover(
            f"FX {'LONG' if direction == 'LONG' else 'SHORT'} {pair}",
            f"Fill: {fill_px:.5f} | Qty: {qty:,}u\n"
            f"Stop: {stop_px:.5f} ({stop_pips:.1f}p)\n"
            f"Target: {target_px:.5f} ({target_pips:.1f}p)\n"
            f"R:R {target_pips/max(stop_pips,0.1):.1f} | Risk ${cfg['risk_usd']:.0f}",
        )
        try:
            con = sqlite3.connect(JOURNAL_DB_PATH)
            # Real trade_journal schema -- pre-2026-09-10 this referenced
            # columns (direction, entry_date, status) that don't exist, so
            # every FX Trader journal write silently failed and no FX trade
            # ever reached the P&L dashboard. Open = closed_at IS NULL.
            con.execute("""INSERT INTO trade_journal
                (opened_at, ticker, action, qty, entry_price, strategy_type, is_paper, notes)
                VALUES (?,?,?,?,?,?,?,?)""",
                (_utcnow().isoformat(), pair, direction, qty, fill_px,
                 "fx_trader", _is_paper(),
                 f"sl={stop_px:.5f} tp={target_px:.5f} spread={spread_pips}p atr={atr14:.5f}"))
            con.commit(); con.close()
        except Exception as je:
            log.warning("FX_TRADER journal insert: %s", je)
        _fx_save_state()
    except Exception as e:
        _fx_log("ERROR", pair, f"_fx_enter_trade: {e}")
        log.exception("FX_TRADER enter %s", pair)


async def _fx_close_position(ib, pair: str, reason: str) -> None:
    """Cancel OCA bracket orders, place market close, record result in state + journal."""
    from ib_insync import MarketOrder, Forex as IbForex
    fx  = state["fx_trader"]
    pos = fx["positions"].get(pair)
    if not pos or pos.get("phase") != "open":
        return
    pos["phase"] = "closing"
    try:
        # Cancel open bracket orders
        sl_id = pos.get("sl_order_id")
        tp_id = pos.get("tp_order_id")
        for ot in ib.openTrades():
            if ot.order.orderId in (sl_id, tp_id):
                try:
                    ib.cancelOrder(ot.order)
                except Exception:
                    pass
        await asyncio.sleep(1)
        # Qualify and close at market
        contract = IbForex(pair)
        contract.conId = pos.get("conid", 0)
        qualified = await ib.qualifyContractsAsync(contract)
        if qualified:
            contract = qualified[0]
        close_act   = "SELL" if pos["direction"] == "LONG" else "BUY"
        close_trade = ib.placeOrder(contract, MarketOrder(close_act, pos["qty"]))
        for _ in range(15):
            await asyncio.sleep(1)
            if close_trade.orderStatus.status == "Filled":
                break
        close_px = (close_trade.orderStatus.avgFillPrice
                    or pos.get("live_price") or pos["entry_price"])
        pcfg      = FX_PAIRS[pair]
        pips_pnl  = round(((close_px - pos["entry_price"]) if pos["direction"] == "LONG"
                           else (pos["entry_price"] - close_px)) / pcfg["pip"], 1)
        pnl_usd   = (round(pips_pnl * pcfg["pip"] * pos["qty"], 2)
                     if pcfg["quote"] == "USD"
                     else round(pips_pnl * pcfg["pip"] / max(close_px, 1e-9) * pos["qty"], 2))
        pos.update({"phase": "closed", "exit_price": round(close_px, 5), "exit_reason": reason,
                    "pips_pnl": pips_pnl, "pnl_usd": pnl_usd,
                    "closed_at": _utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")})
        fx["closed_today"].append(pos)
        del fx["positions"][pair]
        _fx_log("CLOSED", pair,
                f"{reason} @ {close_px:.5f}  pips={pips_pnl:+.1f}  pnl=${pnl_usd:+.2f}")
        _exit_label = {"tp_hit": "TARGET HIT", "sl_hit": "STOP HIT",
                       "eod_force_close": "EOD CLOSE", "manual_close": "MANUAL CLOSE"}.get(reason, reason.upper())
        _fx_pushover(
            f"FX {_exit_label} {pair}",
            f"Exit: {close_px:.5f}\n"
            f"P&L: {pips_pnl:+.1f} pips | ${pnl_usd:+.2f}\n"
            f"Entry was: {pos['entry_price']:.5f} ({pos['direction']})",
        )
        try:
            con = sqlite3.connect(JOURNAL_DB_PATH)
            con.execute("""UPDATE trade_journal SET
                closed_at=?, exit_price=?, pnl=?, win=?, exit_reason=?, notes=COALESCE(notes,'')||?
                WHERE id = (SELECT id FROM trade_journal
                            WHERE ticker=? AND strategy_type='fx_trader' AND closed_at IS NULL
                            ORDER BY id DESC LIMIT 1)""",
                (_utcnow().isoformat(), close_px, pnl_usd, 1 if pnl_usd > 0 else 0, reason,
                 f" | exit={reason} pips={pips_pnl:+.1f} pnl=${pnl_usd:+.2f}", pair))
            con.commit(); con.close()
        except Exception as je:
            log.warning("FX_TRADER journal close: %s", je)
        _fx_save_state()
    except Exception as e:
        pos["phase"] = "open"  # revert so monitor can retry
        _fx_log("ERROR", pair, f"_fx_close_position {reason}: {e}")
        log.exception("FX_TRADER close %s %s", pair, reason)


async def _fx_monitor_coro(ib) -> None:
    """
    Runs every 60s: (1) reconcile OCA bracket fills, (2) update live P&L,
    (3) EOD force-close, (4) scan for new signals if in entry window.
    """
    from zoneinfo import ZoneInfo as _ZI
    from ib_insync import Forex as IbForex
    fx  = state["fx_trader"]
    cfg = fx["config"]
    et_now     = datetime.now(_ZI("America/New_York"))
    is_weekday = et_now.weekday() < 5
    t_str      = et_now.strftime("%H:%M")

    # ── 1. Reconcile OCA bracket fills ────────────────────────────────────────
    if fx["positions"] and is_weekday:
        try:
            # ib.portfolio() is synchronous and returns cached positions
            ibkr_pairs = set()
            for p in ib.portfolio():
                sym  = getattr(p.contract, "symbol",   "")
                cur  = getattr(p.contract, "currency", "")
                name = sym + cur
                if name in FX_PAIRS and abs(p.position) > 0:
                    ibkr_pairs.add(name)
        except Exception:
            ibkr_pairs = set(fx["positions"].keys())  # conservative: assume all still open

        for pair in list(fx["positions"].keys()):
            pos = fx["positions"].get(pair)
            if not pos or pos.get("phase") != "open":
                continue
            if pair in ibkr_pairs:
                continue  # still open on IBKR — nothing to reconcile
            # Position gone from IBKR → OCA bracket must have hit TP or SL
            lp   = pos.get("live_price", pos["entry_price"])
            pcfg = FX_PAIRS[pair]
            pips = round(((lp - pos["entry_price"]) if pos["direction"] == "LONG"
                          else (pos["entry_price"] - lp)) / pcfg["pip"], 1)
            pnl  = (round(pips * pcfg["pip"] * pos["qty"], 2)
                    if pcfg["quote"] == "USD"
                    else round(pips * pcfg["pip"] / max(lp, 1e-9) * pos["qty"], 2))
            tp = pos.get("target_price")
            sl = pos.get("stop_price")
            if pos["direction"] == "LONG":
                reason = "tp_hit" if (tp and lp >= tp) else "sl_hit"
            else:
                reason = "tp_hit" if (tp and lp <= tp) else "sl_hit"
            pos.update({"phase": "closed", "exit_price": round(lp, 5), "exit_reason": reason,
                        "pips_pnl": pips, "pnl_usd": pnl,
                        "closed_at": _utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")})
            fx["closed_today"].append(pos)
            del fx["positions"][pair]
            _fx_log("CLOSED", pair, f"{reason} via OCA  pips={pips:+.1f}  pnl=${pnl:+.2f}")
            try:
                con = sqlite3.connect(JOURNAL_DB_PATH)
                con.execute("""UPDATE trade_journal SET
                    closed_at=?, exit_price=?, pnl=?, win=?, exit_reason=?, notes=COALESCE(notes,'')||?
                    WHERE id = (SELECT id FROM trade_journal
                                WHERE ticker=? AND strategy_type='fx_trader' AND closed_at IS NULL
                                ORDER BY id DESC LIMIT 1)""",
                    (_utcnow().isoformat(), lp, pnl, 1 if pnl > 0 else 0, reason,
                     f" | exit={reason} pips={pips:+.1f} pnl=${pnl:+.2f}", pair))
                con.commit(); con.close()
            except Exception as je:
                log.warning("FX_TRADER reconcile journal: %s", je)
            _fx_save_state()

    # ── 2. Update live P&L + EOD force-close ──────────────────────────────────
    for pair in list(fx["positions"].keys()):
        pos = fx["positions"].get(pair)
        if not pos or pos.get("phase") != "open":
            continue
        try:
            contract = IbForex(pair)
            tickers  = await ib.reqTickersAsync(contract)
            await asyncio.sleep(1)
            td = tickers[0] if tickers else None
            if td and td.bid and td.ask and td.bid > 0 and td.ask > 0:
                mid             = (td.bid + td.ask) / 2.0
                pos["live_price"] = round(mid, 5)
                pcfg              = FX_PAIRS[pair]
                pips              = round(((mid - pos["entry_price"]) if pos["direction"] == "LONG"
                                          else (pos["entry_price"] - mid)) / pcfg["pip"], 1)
                pos["live_pnl"]   = (round(pips * pcfg["pip"] * pos["qty"], 2)
                                     if pcfg["quote"] == "USD"
                                     else round(pips * pcfg["pip"] / max(mid, 1e-9) * pos["qty"], 2))
        except Exception:
            pass
        # EOD force-close — FX session ends 17:00 ET weekdays
        if is_weekday and t_str >= cfg["force_close_time"]:
            await _fx_close_position(ib, pair, "eod_force_close")

    # ── 3. Entry scan (once per 5 min, only inside entry window) ──────────────
    in_window = is_weekday and cfg["entry_start"] <= t_str <= cfg["entry_end"]
    if in_window:
        last_scan = fx.get("last_scan")
        now_ts    = _utcnow().timestamp()
        if last_scan is None or (now_ts - last_scan) >= 300:
            fx["last_scan"] = now_ts
            _fx_log("SCAN", "system", f"scanning {len(FX_PAIRS)} pairs  pos={len(fx['positions'])}/{cfg['max_positions']}")
            for pair in FX_PAIRS:
                if pair in fx["positions"]:
                    continue
                try:
                    await _fx_enter_trade(ib, pair)
                    await asyncio.sleep(1)
                except Exception as e:
                    _fx_log("ERROR", pair, f"scan: {e}")

    _fx_save_state()


async def _fx_monitor_loop() -> None:
    """60-second background task for FX Trader (runs 24/5 when enabled)."""
    while True:
        await asyncio.sleep(60)
        try:
            fx = state["fx_trader"]
            if not fx["enabled"]:
                continue
            ib = state.get("ib")
            if not ib or not ib.isConnected():
                continue
            await asyncio.get_event_loop().run_in_executor(
                None,
                lambda: _run_in_streaming_loop(_fx_monitor_coro(ib), timeout=55)
            )
        except Exception as e:
            log.warning("_fx_monitor_loop error: %s", e)


# ── FX Trader API endpoints ────────────────────────────────────────────────

class FXConfigRequest(BaseModel):
    risk_usd:         Optional[float] = None
    max_spread_pips:  Optional[float] = None
    max_positions:    Optional[int]   = None
    entry_start:      Optional[str]   = None
    entry_end:        Optional[str]   = None
    force_close_time: Optional[str]   = None


@app.get("/fx-trader/status")
def fx_status():
    fx = state["fx_trader"]
    return {
        "enabled":      fx["enabled"],
        "config":       fx["config"],
        "pairs":        FX_PAIRS,
        "positions":    fx["positions"],
        "closed_today": fx["closed_today"],
        "decisions":    fx["decisions"][-50:],
    }


@app.post("/fx-trader/enable")
def fx_enable(body: dict):
    enabled = bool(body.get("enabled", False))
    state["fx_trader"]["enabled"] = enabled
    _fx_save_state()
    return {"enabled": enabled}


@app.post("/fx-trader/config")
def fx_config_update(req: FXConfigRequest):
    cfg     = state["fx_trader"]["config"]
    updates = req.model_dump(exclude_none=True)
    cfg.update(updates)
    _fx_log("CONFIG", "system", f"updated: {updates}")
    _fx_save_state()
    return {"config": cfg}


@app.post("/fx-trader/close/{pair}")
async def fx_close(pair: str):
    fx = state["fx_trader"]
    if pair not in fx["positions"]:
        raise HTTPException(404, f"{pair} not in open positions")
    ib = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IBKR not connected")
    _fx_log("MANUAL_CLOSE", pair, "manual close requested")
    loop = asyncio.get_event_loop()
    await loop.run_in_executor(
        None,
        lambda: _run_in_streaming_loop(_fx_close_position(ib, pair, "manual_close"), timeout=60)
    )
    return {"status": "closing", "pair": pair}


@app.post("/fx-trader/force-entry/{pair}")
async def fx_force_entry(pair: str, body: dict = {}):
    """
    Place a real test trade bypassing the EMA signal filter.
    Uses minimum lot (1,000 units), live quote, 10-pip stop + target OCA bracket.
    Only use for connectivity testing — logs as TEST_ENTRY in decisions.
    """
    from ib_insync import Forex as IbForex, MarketOrder, LimitOrder, StopOrder
    from zoneinfo import ZoneInfo as _ZI
    pair = pair.upper()
    if pair not in FX_PAIRS:
        raise HTTPException(400, f"Unknown pair {pair}. Supported: {list(FX_PAIRS)}")
    ib = state.get("ib")
    if not ib or not ib.isConnected():
        raise HTTPException(503, "IBKR not connected")

    fx   = state["fx_trader"]
    pcfg = FX_PAIRS[pair]
    pip  = pcfg["pip"]

    direction = body.get("direction", "LONG").upper()
    if direction not in ("LONG", "SHORT"):
        raise HTTPException(400, "direction must be LONG or SHORT")

    stop_pips   = float(body.get("stop_pips", 10))
    target_pips = float(body.get("target_pips", 10))
    qty         = int(body.get("qty", 20_000))  # IBKR IDEALPRO minimum

    async def _do():
        contract = IbForex(pair)
        qualified = await ib.qualifyContractsAsync(contract)
        if not qualified:
            raise ValueError(f"Could not qualify {pair}")
        contract = qualified[0]

        tickers = await ib.reqTickersAsync(contract)
        await asyncio.sleep(2)
        td = tickers[0] if tickers else None
        if not td or not td.bid or not td.ask or td.bid <= 0 or td.ask <= 0:
            raise ValueError(f"No live quote for {pair}")

        spread_pips = round((td.ask - td.bid) / pip, 1)
        mid = (td.bid + td.ask) / 2.0

        # Use a limit order with a 3-pip buffer (works 24/5 unlike tif=DAY MKT orders)
        action = "BUY" if direction == "LONG" else "SELL"
        limit_px = round(
            (td.ask + 3 * pip) if direction == "LONG" else (td.bid - 3 * pip),
            5,
        )
        entry_trade = ib.placeOrder(
            contract, LimitOrder(action, qty, limit_px, tif="GTC")
        )
        _fx_log("TEST_ORDERING", pair,
                f"{direction} {qty}u LMT@{limit_px:.5f}  spread={spread_pips}p  mid={mid:.5f}")

        for _ in range(20):
            await asyncio.sleep(1)
            if entry_trade.orderStatus.status in ("Filled", "Cancelled", "Inactive"):
                break

        if entry_trade.orderStatus.status != "Filled":
            reason = entry_trade.orderStatus.status
            log_msgs = "; ".join(str(m) for m in entry_trade.log[-3:]) if entry_trade.log else ""
            ib.cancelOrder(entry_trade.order)
            raise ValueError(f"Fill failed: {reason} | {log_msgs}")

        fill_px = entry_trade.orderStatus.avgFillPrice or mid
        exit_act = "SELL" if direction == "LONG" else "BUY"
        if direction == "LONG":
            stop_px   = round(fill_px - stop_pips   * pip, 5)
            target_px = round(fill_px + target_pips * pip, 5)
        else:
            stop_px   = round(fill_px + stop_pips   * pip, 5)
            target_px = round(fill_px - target_pips * pip, 5)

        oca = f"FX_{pair}_{datetime.now(_ZI('America/New_York')).strftime('%Y%m%d_%H%M%S')}_TEST"
        ib.placeOrder(contract, StopOrder(exit_act, qty, stop_px,
                                          tif="GTC", ocaGroup=oca, ocaType=1))
        ib.placeOrder(contract, LimitOrder(exit_act, qty, target_px,
                                           tif="GTC", ocaGroup=oca, ocaType=1))

        _fx_log("TEST_ENTERED", pair,
                f"{direction} {qty}u fill={fill_px:.5f}  sl={stop_px:.5f}  tp={target_px:.5f}  "
                f"spread={spread_pips}p")
        return {
            "status":      "filled",
            "pair":        pair,
            "direction":   direction,
            "qty":         qty,
            "fill_price":  round(fill_px, 5),
            "stop_price":  round(stop_px, 5),
            "target_price": round(target_px, 5),
            "stop_pips":   stop_pips,
            "target_pips": target_pips,
            "spread_pips": spread_pips,
            "oca_group":   oca,
            "order_id":    entry_trade.order.orderId,
        }

    try:
        result = await asyncio.get_event_loop().run_in_executor(
            None,
            lambda: _run_in_streaming_loop(_do(), timeout=60),
        )
    except (ValueError, RuntimeError, TimeoutError) as e:
        raise HTTPException(503, str(e))
    return result


@app.get("/fx-trader/history")
def fx_history(limit: int = 50):
    try:
        con = sqlite3.connect(JOURNAL_DB_PATH)
        con.row_factory = sqlite3.Row
        rows = con.execute("""
            SELECT * FROM trade_journal WHERE strategy_type='fx_trader'
            ORDER BY rowid DESC LIMIT ?""", (limit,)).fetchall()
        con.close()
        return {"trades": [dict(r) for r in rows]}
    except Exception as e:
        return {"trades": [], "error": str(e)}


# ── Live Data WebSocket -- account/strategy snapshot push (2026-09-07) ──────
# Structurally independent from /ws/tape below: that endpoint needs the
# special streaming-thread treatment because it owns a live ib_insync.IB()
# connection (one dedicated IBKR client id per ticker watched). This one
# never touches ib_insync directly -- it only reads state's plain dicts
# (already-computed, in-memory) and proxies 2 lightweight HTTP calls to the
# standalone agents that have their own server (Day Trader :8010, SPY
# Weekly Condor :8011) -- runs fine on uvicorn's own loop.
_live_ws_clients: set = set()

# Per-strategy adapter -- NOT a generic walker. Confirmed live 2026-09-07:
# state["spx_0dte"] keys open items as "spreads", not "positions" like
# every other in-process strategy; state["manual_trader"] uses "closed",
# not "closed_today" like everyone else, and its "closed" list is the last
# 100 closes (not day-scoped), so a naive sum would silently misreport
# "today's" P&L -- left null there rather than fabricate a wrong number,
# same convention pnl_dashboard's own Alpaca-merge already uses (see its
# comment: "showing a fabricated number would be worse than omitting it").
def _live_snapshot_inprocess_strategies() -> dict:
    out = {}

    def _today_pnl(closed_list):
        try:
            return round(sum(float(r.get("pnl", 0) or 0) for r in closed_list), 2)
        except Exception:
            return None

    at = state.get("autotrader", {})
    out["autotrader"] = {"enabled": at.get("enabled", False),
                          "open_position_count": len(at.get("positions", {})),
                          "today_pnl": None}  # only cumulative counters kept, no daily-reset list

    st = state.get("stock_trader", {})
    out["stock_trader"] = {"enabled": st.get("enabled", False),
                            "open_position_count": len(st.get("positions", {})),
                            "today_pnl": _today_pnl(st.get("closed_today", []))}

    sx = state.get("spx_0dte", {})
    out["spx_0dte"] = {"enabled": sx.get("enabled", False),
                        "open_position_count": len(sx.get("spreads", {})),
                        "today_pnl": _today_pnl(sx.get("closed_today", []))}

    ev = state.get("evc", {})
    out["evc"] = {"enabled": ev.get("enabled", False),
                  "open_position_count": len(ev.get("positions", {})),
                  "today_pnl": _today_pnl(ev.get("closed_today", []))}

    sig = state.get("sig_trader", {})
    out["sig_trader"] = {"enabled": sig.get("enabled", False),
                          "open_position_count": len(sig.get("positions", {})),
                          "today_pnl": _today_pnl(sig.get("closed_today", []))}

    fx = state.get("fx_trader", {})
    out["fx_trader"] = {"enabled": fx.get("enabled", False),
                         "open_position_count": len(fx.get("positions", {})),
                         "today_pnl": _today_pnl(fx.get("closed_today", []))}

    mt = state.get("manual_trader", {})
    out["manual_trader"] = {"enabled": mt.get("enabled", False),
                             "open_position_count": len(mt.get("positions", {})),
                             "today_pnl": None}  # "closed" isn't day-scoped, see docstring above

    return out


def _live_snapshot_standalone_agent(url: str) -> dict | None:
    """Sync helper -- always called via run_in_executor, never directly in
    an async context (would block the event loop otherwise)."""
    try:
        r = requests.get(url, timeout=3)
        r.raise_for_status()
        return r.json()
    except Exception:
        return None


def _plain_bar(b: dict | None) -> dict | None:
    """Cast a bars-dataframe row to plain JSON-safe types before it goes
    over the WebSocket. state["bars"] rows come from a pandas DataFrame
    (_bars_to_df / df.tail(80).to_dict), so "volume" in particular is
    typically numpy.int64 -- unlike numpy.float64 (which subclasses
    Python's float and serializes fine), numpy.int64 does NOT subclass
    int and raises TypeError under the plain json.dumps() that
    WebSocket.send_json() uses (no FastAPI/pydantic encoder in the path
    the way the existing /bars/{ticker} REST endpoint gets for free)."""
    if not b:
        return None
    return {
        "time": b.get("time"),
        "open": float(b["open"]), "high": float(b["high"]),
        "low": float(b["low"]), "close": float(b["close"]),
        "volume": float(b["volume"]) if b.get("volume") is not None else None,
    }


async def _build_live_snapshot() -> dict:
    loop = asyncio.get_event_loop()
    dt_status, spy_status = await asyncio.gather(
        loop.run_in_executor(None, _live_snapshot_standalone_agent, f"{DAY_TRADER_AGENT_URL}/day-trader/status"),
        loop.run_in_executor(None, _live_snapshot_standalone_agent, f"{SPY_CONDOR_AGENT_URL}/spy-condor/status"),
    )
    ib = state.get("ib")
    return {
        "type": "snapshot",
        "time": datetime.now(timezone.utc).isoformat(),
        "account": {"net_liquidation": _get_net_liq(ib) if ib and ib.isConnected() else None},
        "strategies": {
            **_live_snapshot_inprocess_strategies(),
            "day_trader": ({"enabled": dt_status.get("enabled", False),
                             "open_position_count": len(dt_status.get("positions", {})),
                             "today_pnl": None, "reachable": True}
                            if dt_status is not None else {"reachable": False}),
            "spy_weekly_condor": ({"enabled": spy_status.get("enabled", False),
                                    "open_position_count": len(spy_status.get("positions", {})),
                                    "today_pnl": spy_status.get("summary", {}).get("today_pnl"),
                                    "reachable": True}
                                   if spy_status is not None else {"reachable": False}),
        },
        # Signals (research/Signals tab): state["signals"][ticker] is
        # already recomputed on every live IBKR tick by on_bar_update()
        # (reqHistoricalDataAsync(..., keepUpToDate=True) streams into the
        # currently-forming bar) -- this was already real-time on the
        # backend, the frontend just polled it every 15s. Pushing it here
        # closes that gap to this broadcaster's existing ~3s cadence.
        # predict()'s own return already casts every field to plain
        # float/str, so no extra casting needed here (unlike bars, below).
        "signals": dict(state.get("signals", {})),
        "latest_bar": {
            ticker: _plain_bar(bars[-1] if bars else None)
            for ticker, bars in state.get("bars", {}).items()
        },
        "latest_bar_1m": {
            ticker: _plain_bar(bars[-1] if bars else None)
            for ticker, bars in state.get("bars_1m", {}).items()
        },
    }


async def _live_snapshot_broadcaster() -> None:
    while True:
        try:
            snapshot = await _build_live_snapshot()
            for ws in list(_live_ws_clients):
                try:
                    await ws.send_json(snapshot)
                except Exception:
                    _live_ws_clients.discard(ws)
        except Exception as exc:
            log.warning("Live snapshot broadcaster error: %s", exc)
        await asyncio.sleep(3)


# ── Independent Traders: run/schedule status ─────────────────────────────
# The 8 strategies now running outside this process (2026-08-27 Day Trader
# extraction, 2026-09-07 SPY Weekly Condor extraction, plus Ashley/
# Butterflies x3/GOOG Condor/Safe Income Trader which were always standalone
# scripts). Two of these (Day Trader, SPY Weekly Condor) have their own
# HTTP server and a /health endpoint; the rest fire on a Windows Task
# Scheduler cadence with no live server to ask, so "is this still scheduled
# and when did/will it run" has to come from Task Scheduler itself.
INDEPENDENT_TRADER_TASK_NAMES = {
    "ashley":        "IBKR-AshleyExecutorWatchdog",
    "butterfly_spy": "IBKR-SPYButterflyFixed",
    "butterfly_qqq": "IBKR-QQQButterflyWindow",
    "butterfly_iwm": "IBKR-IWMButterflyWindow",
    "goog_condor":   "IBKR-GOOGCondorMonday",
    "safe_income":   "IBKR-SafeIncomeTrader",
    "chartexpert":   "IBKR-ChartExpertAutoTrader",
    "harami_daily":  "IBKR-HaramiDailyEntry",
}


_TASK_SCHEDULER_SCRIPT = os.path.join(os.path.dirname(__file__), "query_scheduled_tasks.ps1")


def _query_task_scheduler_sync() -> dict:
    """Sync -- always called via run_in_executor, never directly in an
    async context. Returns {task_name: {State, LastRunTime, NextRunTime,
    LastTaskResult}}. Real subprocess call (~1-2s) -- this is why this
    lives behind its own slow-poll REST endpoint, not folded into the 3s
    /ws/live broadcast. Runs a real .ps1 file (query_scheduled_tasks.ps1)
    rather than an inline -Command string -- an inline string with nested
    quotes (ToString("o") inside a PSCustomObject inside a ForEach-Object)
    hit real PowerShell argument-parsing quote-stripping and silently
    failed every call (confirmed live 2026-09-07); a real file with
    -File sidesteps that whole class of bug."""
    names = list(INDEPENDENT_TRADER_TASK_NAMES.values())
    try:
        proc = subprocess.run(
            ["powershell", "-NoProfile", "-NonInteractive", "-File", _TASK_SCHEDULER_SCRIPT,
             "-TaskNames", ",".join(names)],
            capture_output=True, text=True, timeout=15)
        if proc.returncode != 0 or not proc.stdout.strip():
            log.warning("Task Scheduler query returned nothing (code=%s): %s", proc.returncode, proc.stderr[-500:])
            return {}
        data = json.loads(proc.stdout)
        if isinstance(data, dict):
            data = [data]
        return {d["Name"]: d for d in data}
    except Exception as exc:
        log.warning("Task Scheduler query failed: %s", exc)
        return {}


def _state_file_field(path: str, key: str):
    try:
        with open(path) as f:
            return json.load(f).get(key)
    except Exception:
        return None


# Real open-position visibility for the scheduled-task independent traders
# (Butterflies/GOOG Condor/Ashley/Safe Income) -- added 2026-09-08 after a
# real incident where IWM/QQQ butterflies were open for ~6 real hours with
# zero visibility anywhere in the UI (the tab only ever showed Task
# Scheduler last/next-run times for these rows, never live position state
# -- a genuine v1 scope gap, not a bug, but one that contributed to a real
# stuck-position bug going unnoticed until manually investigated). Reads
# the same registry files each strategy's own pretrade/close code already
# treats as the source of truth -- no new tracking mechanism invented.
_ALPACA_0DTE_ROW_FILTER = {
    "butterfly_spy": ("SPY", "long_butterfly_0dte"),
    "butterfly_qqq": ("QQQ", "long_butterfly_0dte"),
    "butterfly_iwm": ("IWM", "long_butterfly_0dte"),
    "goog_condor":   ("GOOG", "iron_condor_weekly"),
    "ashley":        (None, "ashley_signal"),  # ticker varies (usually SPY), don't filter on it
}


def _open_positions_for_row(row_id: str) -> list:
    if row_id == "harami_daily":
        try:
            with open("harami_trader_state.json") as f:
                positions = json.load(f).get("positions", {})
        except Exception:
            return []
        out = []
        for key, p in positions.items():
            phase = p.get("phase")
            if phase in ("pending_entry",):
                out.append({"pos_id": key, "ticker": p.get("ticker"), "entry_time": p.get("placed_at"),
                           "summary": f"MOO BUY {p.get('qty')}x placed, awaiting fill (real order, expected ~${p.get('expected_spot'):.2f})"})
            elif phase == "open":
                out.append({"pos_id": key, "ticker": p.get("ticker"), "entry_time": p.get("entry_fill_date"),
                           "summary": f"REAL: {p.get('qty')}x @ ${p.get('entry_price'):.2f}, exit planned {p.get('exit_date')} (5-day hold)"})
            elif phase == "pending_exit":
                out.append({"pos_id": key, "ticker": p.get("ticker"), "entry_time": p.get("entry_fill_date"),
                           "summary": f"MOC SELL placed, awaiting fill (entry was ${p.get('entry_price'):.2f})"})
        return out
    if row_id == "chartexpert":
        try:
            with open("chartexpert_shadow_state.json") as f:
                positions = json.load(f).get("open", {})
        except Exception:
            return []
        return [
            {
                "pos_id": ticker,
                "ticker": ticker,
                "entry_time": p.get("signal_time"),
                "summary": f"{'SHADOW' if p.get('shadow', True) else 'LIVE'} {p.get('strike')}C exp {p.get('expiry')} -- "
                           f"bought (simulated) @ ${p.get('option_entry_ask'):.2f}, up-prob {p.get('up_pct')}%, "
                           f"underlying entry ${p.get('underlying_entry'):.2f} / high ${p.get('high_water_mark'):.2f} "
                           f"(0.5% trailing stop)",
            }
            for ticker, p in positions.items()
        ]
    if row_id == "safe_income":
        try:
            with open("safe_income_auto_state.json") as f:
                positions = json.load(f).get("positions", {})
        except Exception:
            return []
        return [
            {
                "pos_id": pid,
                "ticker": p.get("ticker"),
                "entry_time": p.get("entered_at"),
                "summary": f"{p.get('ticker')} {p.get('short_k')}/{p.get('long_k')} {p.get('right')} "
                           f"exp {p.get('expiry')} -- credit ${p.get('entry_credit')} ({p.get('exit_rule')})",
            }
            for pid, p in positions.items()
        ]

    filt = _ALPACA_0DTE_ROW_FILTER.get(row_id)
    if not filt:
        return []
    want_ticker, want_strategy = filt
    try:
        with open("alpaca_0dte_positions.json") as f:
            positions = json.load(f).get("positions", {})
    except Exception:
        return []
    out = []
    for pid, p in positions.items():
        if p.get("strategy") != want_strategy:
            continue
        if want_ticker is not None and p.get("ticker") != want_ticker:
            continue
        legs = p.get("legs", [])
        leg_summary = ", ".join(f"{l.get('leg')} {l.get('strike')}" for l in legs) if legs else "?"
        out.append({
            "pos_id": pid,
            "ticker": p.get("ticker"),
            "entry_time": p.get("entry_time"),
            "summary": f"{p.get('ticker')} {leg_summary} -- net {'credit' if (p.get('net_entry_credit') or 0) > 0 else 'debit'} "
                       f"${abs(p.get('net_entry_credit') or 0):.2f}, max risk ${p.get('max_risk')}"
                       + (f", closes by {p.get('hard_close_time')} ET" if p.get("hard_close_time") else ""),
        })
    return out


@app.get("/independent-traders/status")
async def independent_traders_status():
    loop = asyncio.get_event_loop()
    tasks_info, dt_health, spy_health = await asyncio.gather(
        loop.run_in_executor(None, _query_task_scheduler_sync),
        loop.run_in_executor(None, _live_snapshot_standalone_agent, f"{DAY_TRADER_AGENT_URL}/health"),
        loop.run_in_executor(None, _live_snapshot_standalone_agent, f"{SPY_CONDOR_AGENT_URL}/health"),
    )

    rows = [
        {"id": "day_trader", "label": "Day Trader", "kind": "always_on",
         "reachable": dt_health is not None, "health": dt_health},
        {"id": "spy_weekly_condor", "label": "SPY Weekly Condor", "kind": "always_on",
         "reachable": spy_health is not None, "health": spy_health},
    ]
    for row_id, label, task_key, state_file, activity_key in [
        ("ashley", "Ashley", "ashley", "ashleyklieu_trigger_executor_state.json", "last_processed_date"),
        ("butterfly_spy", "Butterflies (SPY)", "butterfly_spy", None, None),
        ("butterfly_qqq", "Butterflies (QQQ)", "butterfly_qqq", None, None),
        ("butterfly_iwm", "Butterflies (IWM)", "butterfly_iwm", None, None),
        ("goog_condor", "GOOG Condor", "goog_condor", None, None),
        ("safe_income", "Safe Income Trader", "safe_income", None, None),
        ("chartexpert", "Chartexpert Trade (Shadow)", "chartexpert", None, None),
        ("harami_daily", "Harami Daily (Live)", "harami_daily", None, None),
    ]:
        task_name = INDEPENDENT_TRADER_TASK_NAMES[task_key]
        info = tasks_info.get(task_name, {})
        rows.append({
            "id": row_id, "label": label, "kind": "scheduled",
            "task_state": info.get("State"),
            "last_run": info.get("LastRunTime"),
            "next_run": info.get("NextRunTime"),
            "last_result": info.get("LastTaskResult"),
            "last_activity": _state_file_field(state_file, activity_key) if state_file else None,
            "open_positions": _open_positions_for_row(row_id),
        })
    return {"traders": rows}


@app.websocket("/ws/live")
async def ws_live(websocket: WebSocket):
    await websocket.accept()
    _live_ws_clients.add(websocket)
    try:
        while True:
            await websocket.receive_text()  # only used to detect disconnect promptly
    except Exception:
        pass
    finally:
        _live_ws_clients.discard(websocket)


# ── Live Tape WebSocket ─────────────────────────────────────────────────────
@app.websocket("/ws/tape/{ticker}")
async def ws_tape(websocket: WebSocket, ticker: str, block: Optional[int] = Query(
        default=None,
        description="Manual block-size override, in shares. Omit for automatic ADV-relative "
                    "sizing (same 0.5%-of-ADV / $1M-floor rule validated for dark-pool sizing "
                    "2026-08-30 -- lands at a consistent real p94.7-p99.8 across small and mega "
                    "caps, unlike a flat share count).")):
    """
    Stream real-time tick-by-tick trade data (Time & Sales) for a stock.
    Each message is a JSON object with the raw tick plus plain-English explanations.
    Uses a separate IB client ID (pool 20-29) so it never conflicts with the main app.

    The dedicated IB() client's connect/subscribe/teardown all run on the shared
    streaming-thread event loop (state["streaming_loop"]) via _run_in_streaming_loop —
    the same loop the main IBKR connection uses. Running them on this handler's own
    (uvicorn) loop caused ib_insync transport futures to bind to the wrong loop
    ("attached to a different loop" errors). Ticks are handed back to this handler's
    loop via call_soon_threadsafe since asyncio.Queue isn't safe to touch cross-loop.
    """
    await websocket.accept()

    ticker_adv = None
    if block is None:
        try:
            with open("darkpool_adv_cache.json") as f:
                ticker_adv = json.load(f).get("adv", {}).get(ticker.upper())
        except Exception:
            ticker_adv = None

    cid = _acquire_tape_cid()
    if cid is None:
        await websocket.send_json({
            "type": "error",
            "message": "Too many concurrent tape connections (max 10). Please try again shortly.",
        })
        await websocket.close()
        return

    main_loop = asyncio.get_running_loop()
    tick_queue: asyncio.Queue = asyncio.Queue()
    contract = None
    tape_print_buffer: list = []   # accumulated this session; flushed to DB on close
    session: dict = {"ib": None, "tick_idx": 0}   # populated on the streaming-loop thread

    def on_update(t):
        # Fires on the streaming-loop thread (that's where tape_ib/ticker_sub live) —
        # hand ticks to this handler's loop instead of touching the Queue directly.
        new = t.tickByTicks[session["tick_idx"]:]
        session["tick_idx"] = len(t.tickByTicks)
        for tk in new:
            main_loop.call_soon_threadsafe(tick_queue.put_nowait, tk)

    async def _connect_and_subscribe():
        tib = IB()
        await tib.connectAsync(TWS_HOST, TWS_PORT, clientId=cid, timeout=15)
        c = Stock(ticker.upper(), "SMART", "USD")
        await tib.qualifyContractsAsync(c)
        ticker_sub = tib.reqTickByTickData(c, "AllLast", numberOfTicks=0, ignoreSize=False)
        ticker_sub.updateEvent += on_update
        session["ib"] = tib
        return c

    async def _teardown():
        tib = session.get("ib")
        if not tib:
            return
        try:
            if contract and tib.isConnected():
                tib.cancelTickByTickData(contract, "AllLast")
        except Exception:
            pass
        try:
            tib.disconnect()
        except Exception:
            pass

    try:
        contract = await main_loop.run_in_executor(
            None, lambda: _run_in_streaming_loop(_connect_and_subscribe(), timeout=15)
        )

        # Per-session accumulators
        cum_vol:    int   = 0
        cum_pv:     float = 0.0
        buy_vol:    int   = 0
        sell_vol:   int   = 0
        last_price: Optional[float] = None
        last_dir:   int   = 0
        open_price: Optional[float] = None
        block_count: int  = 0

        def _direction(price: float) -> int:
            nonlocal last_price, last_dir
            if last_price is None:      return 0
            if price > last_price:      last_dir = 1
            elif price < last_price:    last_dir = -1
            return last_dir

        await websocket.send_json({"type": "connected", "ticker": ticker.upper(), "client_id": cid})

        while True:
            try:
                tk = await asyncio.wait_for(tick_queue.get(), timeout=20)
            except asyncio.TimeoutError:
                # keep the WS alive during quiet periods (pre-market, AH)
                await websocket.send_json({"type": "heartbeat"})
                tib = session.get("ib")
                if not tib or not tib.isConnected():
                    break
                continue

            price = float(tk.price)
            size  = int(tk.size)
            if size == 0 or price <= 0:
                continue

            if block is None:
                # Real threshold study, 2026-08-30: a flat share count is
                # miscalibrated across tickers -- comparable mega-caps' real
                # p95 print size ranged ~100 shares (META) to ~29,000 (AAPL),
                # a ~300x spread, at the SAME nominal "5000 shares" default.
                # Auto-size once, on this session's first real tick, to the
                # SAME 0.5%-of-ADV / $1M-floor rule already validated for
                # dark-pool sizing (lands at a consistent real p94.7-p99.8
                # across small and mega caps there) -- converted to an
                # equivalent share count at this ticker's current price.
                block_dollars = max(1_000_000, 0.005 * ticker_adv) if ticker_adv else 1_000_000
                block = max(1, round(block_dollars / price))

            d = _direction(price)
            if open_price is None:
                open_price = price

            cum_vol  += size
            cum_pv   += price * size
            vwap      = cum_pv / cum_vol
            if d >= 0: buy_vol  += size
            else:      sell_vol += size
            net_delta = buy_vol - sell_vol
            is_block  = size >= block
            if is_block:
                block_count += 1
            last_price = price

            # ── Plain-English explanations ──────────────────────────────────
            side     = "bought" if d >= 0 else "sold"
            dir_word = "UP" if d > 0 else "DOWN" if d < 0 else "flat"

            what_happened = (
                f"{size:,} shares {side} at ${price:.2f}"
                + (f" — price ticked {dir_word}" if d != 0 else "")
            )

            vwap_diff = price - vwap
            if abs(vwap_diff) < 0.03:
                vwap_story = (
                    f"Trading right at the session average (VWAP ${vwap:.2f}) — "
                    f"neither side has an edge right now"
                )
            elif vwap_diff > 0:
                vwap_story = (
                    f"${vwap_diff:.2f} above today's average — buyers are willing to pay up "
                    f"(VWAP ${vwap:.2f})"
                )
            else:
                vwap_story = (
                    f"${abs(vwap_diff):.2f} below today's average — price looks cheap "
                    f"relative to where most trading happened today (VWAP ${vwap:.2f})"
                )

            if net_delta > 0:
                delta_story = (
                    f"Buyers are in control — {_tape_fmt_vol(net_delta)} more shares "
                    f"bought than sold so far today"
                )
            elif net_delta < 0:
                delta_story = (
                    f"Sellers are in control — {_tape_fmt_vol(abs(net_delta))} more shares "
                    f"sold than bought so far today"
                )
            else:
                delta_story = "Perfectly balanced — equal buying and selling pressure so far"

            block_story = None
            if is_block:
                block_story = (
                    f"Large institutional print: {size:,} shares {side} at ${price:.2f}. "
                    f"Block trades (≥ {block:,} shares) come from funds or trading desks "
                    f"moving a large position — they rarely trade like this by accident."
                )

            pct_from_open = None
            if open_price and open_price > 0:
                pct_from_open = round((price - open_price) / open_price * 100, 2)

            ts_str    = tk.time.strftime("%Y-%m-%dT%H:%M:%S")
            sess_date = tk.time.strftime("%Y-%m-%d")
            cvd_score_now = (state["tape_sentiment"].get(ticker.upper(), {})
                             .get("score"))

            await websocket.send_json({
                "type":           "tick",
                "time":           tk.time.strftime("%H:%M:%S.%f")[:-3],
                "price":          price,
                "size":           size,
                "direction":      d,
                "cum_vol":        cum_vol,
                "vwap":           round(vwap, 2),
                "buy_vol":        buy_vol,
                "sell_vol":       sell_vol,
                "delta":          net_delta,
                "exchange":       tk.exchange or "—",
                "is_block":       is_block,
                "block_threshold": block,
                "is_after_hours": tk.tickAttribLast.pastLimit,
                "block_count":    block_count,
                "open_price":     open_price,
                "pct_from_open":  pct_from_open,
                "what_happened":  what_happened,
                "vwap_story":     vwap_story,
                "delta_story":    delta_story,
                "block_story":    block_story,
            })

            # Buffer this print for DB persistence (flushed in batch on session close)
            tape_print_buffer.append({
                "ts":             ts_str,
                "session_date":   sess_date,
                "ticker":         ticker.upper(),
                "price":          price,
                "size":           size,
                "direction":      d,
                "exchange":       tk.exchange or "",
                "is_block":       int(is_block),
                "is_after_hours": int(bool(tk.tickAttribLast.pastLimit)),
                "vwap":           round(vwap, 4),
                "cum_vol":        cum_vol,
                "buy_vol":        buy_vol,
                "sell_vol":       sell_vol,
                "net_delta":      net_delta,
                "pct_from_open":  pct_from_open,
                "cvd_score":      cvd_score_now,
            })

    except WebSocketDisconnect:
        pass
    except Exception as exc:
        log.error("Tape WS error for %s: %s", ticker, exc)
        try:
            await websocket.send_json({"type": "error", "message": str(exc)})
        except Exception:
            pass
    finally:
        try:
            await main_loop.run_in_executor(
                None, lambda: _run_in_streaming_loop(_teardown(), timeout=10)
            )
        except Exception:
            pass
        _release_tape_cid(cid)
        # Persist all buffered prints to tape_data.db in one batch write
        if tape_print_buffer:
            loop = asyncio.get_event_loop()
            loop.run_in_executor(
                None, _tape_db_flush_prints, ticker.upper(), tape_print_buffer
            )
            log.info("Tape WS closed for %s (cid=%d) — flushing %d prints to tape_data.db",
                     ticker, cid, len(tape_print_buffer))
        else:
            log.info("Tape WS closed for %s (cid=%d)", ticker, cid)


# ── Shared guard ───────────────────────────────────────────────────────────
def _require_connection():
    if not state["connected"] or not state["ib"]:
        raise HTTPException(503, "IBKR not connected — ensure TWS/IB Gateway is running")


# ── Entry point ────────────────────────────────────────────────────────────
if __name__ == "__main__":
    uvicorn.run("main:app", host="127.0.0.1", port=8000, reload=False)
